class FacetControls(ttk.Frame):
    """A column of one dropdown per factor: combine, split, or a single level.

    Ported from ABEL's _FacetControls. Each graphing tab owns an instance, so
    tabs facet independently, and each starts in the inert "split Group,
    combine everything else" state -- an untouched column plots exactly what
    the tab plotted before factors existed.
    """

    # "Split series by" rather than "Facet by": the column sits under a list of
    # subjects and its job is to say how that pool divides into plotted series,
    # which is the one thing a reader needs to know without learning the word.
    # default_split says what an untouched column means on this tab. It is True
    # everywhere the tab already drew one series per group, so the column starts
    # in the state that reproduces that plot. Signal Linkage passes False: it
    # never had grouping and pooled every selected subject into one analysis, so
    # splitting the series factor by default would silently change what the tab
    # computes the first time it is opened.
    def __init__(self, parent, app, on_change=None, header="Split series by:",
                 default_split=True):
        super().__init__(parent)
        self.app = app
        self._on_change = on_change
        self._default_split = bool(default_split)
        self._combos = {}
        self._vars = {}
        self._signature = None

        ttk.Label(self, text=header, font=('Segoe UI', 8, 'bold')).pack(anchor='w')
        self._hint = ttk.Label(
            self, text="Define factors on the Factors tab to split plots.",
            foreground='gray', font=('Segoe UI', 8),
            wraplength=app.ui_px(180), justify='left')
        self._hint.pack(anchor='w')
        self._rows = ttk.Frame(self)
        self._rows.pack(fill='x')

    def rebuild(self, force=False):
        """Rebuild one dropdown per factor, restoring the previous selections.

        Cheap to call on every redraw: when the factors and their levels are
        unchanged it returns before touching a widget. Without that guard,
        rebuilding mid-interaction would drop the user's selection and close an
        open dropdown, so the signature check is what makes this safe to wire
        to refresh paths rather than to one explicit event.
        """
        subjects = sorted(self.app.processed_data.keys())
        factors = self.app.get_factor_definitions(subjects)
        assignments = self.app.get_subject_factors(subjects)
        order_map = self.app.params.get('factor_level_order') or {}
        # include_declared: a level named on the Factors tab but not yet filled
        # still belongs in the column you filter by, or declaring it looks like
        # it did nothing. It cannot mint an empty series -- facet_series drops
        # labels with no members.
        levels = {f: factor_levels(subjects, assignments, f, order_map.get(f),
                                   include_declared=True)
                  for f in factors}

        signature = tuple((f, tuple(levels[f])) for f in factors)
        if not force and signature == self._signature:
            return
        self._signature = signature

        previous = self.selections()
        for child in self._rows.winfo_children():
            child.destroy()
        self._combos, self._vars = {}, {}
        if factors:
            self._hint.pack_forget()
        else:
            self._hint.pack(anchor='w')

        for factor in factors:
            row = ttk.Frame(self._rows)
            row.pack(fill='x', pady=1)
            ttk.Label(row, text=f"{factor}:", font=('Segoe UI', 8),
                      width=9, anchor='w').pack(side='left')
            var = tk.StringVar()
            combo = ttk.Combobox(
                row, textvariable=var, state='readonly', width=14,
                values=[FACTOR_COMBINE, FACTOR_SPLIT] + list(levels[factor]))
            # Restore what was chosen before, but only if it still exists --
            # a level can disappear when assignments change underneath.
            want = previous.get(factor)
            if want not in (combo['values'] or ()):
                # The series factor splits by default and everything else
                # combines. Read it from the app rather than hard-coding
                # 'Group': renaming that factor, or nominating another with
                # "Plot as series", otherwise left every dropdown on every tab
                # defaulting to COMBINE, which collapses each plot to a single
                # pooled series.
                want = (FACTOR_SPLIT
                        if (self._default_split
                            and factor == self.app.series_factor)
                        else FACTOR_COMBINE)
            var.set(want)
            combo.pack(side='left', fill='x', expand=True)
            combo.bind('<<ComboboxSelected>>', lambda _e: self._changed())
            self._combos[factor] = combo
            self._vars[factor] = var

    def _changed(self):
        if callable(self._on_change):
            self._on_change()

    def selections(self):
        """``{factor: COMBINE | SPLIT | level}`` as currently chosen."""
        return {f: v.get() for f, v in self._vars.items()}

    def set_selections(self, selections):
        for factor, value in (selections or {}).items():
            var = self._vars.get(factor)
            if var is not None and value in (self._combos[factor]['values'] or ()):
                var.set(value)


class _ProgressCancelled(Exception):
    """Raised inside a background worker when the user hits Cancel on the
    detailed progress window, so the run aborts cleanly (not as an error)."""


class ZoneEditor:
    """Interactive zone editor for defining behavioral zones"""
    
    def __init__(self, parent, main_app):
        self.parent = parent
        self.main_app = main_app
        self.zones = {k: v.copy() for k, v in main_app.zones.items()}
        self.maze_width = main_app.params['maze_width_cm']
        
        self.selected_zone = None
        self.drag_corner = None
        self.zone_patches = {}
        
        self.setup_ui()
        
    def setup_ui(self):
        """Create the zone editor interface"""
        # Main container
        main_frame = ttk.Frame(self.parent)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
        
        # Left panel - Controls.
        # The action buttons (Save & Apply / Cancel) are packed against the
        # BOTTOM of this column before anything that expands, so they keep their
        # space no matter how short the screen is; the settings above them are
        # placed in a scrolling viewport instead of being clipped away.
        control_outer = ttk.LabelFrame(main_frame, text="Zone Controls", padding=6)
        control_outer.pack(side=tk.LEFT, fill=tk.Y, padx=(0, 8))

        action_frame = ttk.Frame(control_outer)
        action_frame.pack(side=tk.BOTTOM, fill=tk.X, pady=(6, 0))
        ttk.Button(action_frame, text="Save & Apply", style='Compact.TButton',
                   command=self.save_zones).pack(fill=tk.X, pady=1)
        ttk.Button(action_frame, text="Cancel", style='Compact.TButton',
                   command=self.parent.destroy).pack(fill=tk.X, pady=1)
        ttk.Button(action_frame, text="Analysis Settings...", style='Compact.TButton',
                   command=self.open_analysis_settings).pack(fill=tk.X, pady=(1, 4))
        ttk.Separator(control_outer, orient=tk.HORIZONTAL).pack(
            side=tk.BOTTOM, fill=tk.X, pady=4)

        control_frame = self.main_app.make_scrollable(control_outer, fit_width=True)

        # Template selection
        ttk.Label(control_frame, text="Maze Template:").pack(anchor=tk.W, pady=(0, 5))
        current_maze = self.main_app.params['maze_type']
        template_values = list(self.main_app.zone_templates.keys()) + ['Custom Arena']
        self.template_var = tk.StringVar(value=current_maze if current_maze in template_values else 'Custom Arena')
        template_combo = ttk.Combobox(control_frame, textvariable=self.template_var,
                                     values=template_values,
                                     state='readonly', width=20)
        template_combo.pack(fill=tk.X, pady=(0, 5))
        template_combo.bind('<<ComboboxSelected>>', self.load_template)

        # Maze width (editable; always shown so users can adjust)
        maze_width_frame = ttk.Frame(control_frame)
        maze_width_frame.pack(fill=tk.X, pady=(0, 10))
        ttk.Label(maze_width_frame, text="Arena Width (cm):").pack(side=tk.LEFT)
        self.maze_width_var = tk.StringVar(value=str(self.maze_width))
        maze_width_entry = ttk.Entry(maze_width_frame, textvariable=self.maze_width_var, width=8)
        maze_width_entry.pack(side=tk.LEFT, padx=5)
        ttk.Button(maze_width_frame, text="Apply", width=6, style='Compact.TButton',
                   command=self._apply_maze_width).pack(side=tk.LEFT)
        
        ttk.Separator(control_frame, orient=tk.HORIZONTAL).pack(fill=tk.X, pady=10)
        
        # Zone list
        ttk.Label(control_frame, text="Zones:").pack(anchor=tk.W, pady=(0, 5))
        
        zone_list_frame = ttk.Frame(control_frame)
        zone_list_frame.pack(fill=tk.BOTH, expand=True, pady=(0, 10))
        
        scrollbar = ttk.Scrollbar(zone_list_frame)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        self.zone_listbox = tk.Listbox(zone_list_frame, yscrollcommand=scrollbar.set,
                                       height=8, width=24)
        self.zone_listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.config(command=self.zone_listbox.yview)
        self.zone_listbox.bind('<<ListboxSelect>>', self.select_zone_from_list)
        
        self.populate_zone_list()

        # Zone management buttons (for custom arena)
        zone_mgmt_frame = ttk.Frame(control_frame)
        zone_mgmt_frame.pack(fill=tk.X, pady=(0, 5))
        ttk.Button(zone_mgmt_frame, text="+ Add", style='Compact.TButton',
                   command=self.add_zone).pack(side=tk.LEFT, padx=(0, 2))
        ttk.Button(zone_mgmt_frame, text="- Remove", style='Compact.TButton',
                   command=self.remove_zone).pack(side=tk.LEFT, padx=(0, 2))
        ttk.Button(zone_mgmt_frame, text="Rename", style='Compact.TButton',
                   command=self.rename_zone).pack(side=tk.LEFT)
        
        # Zone details
        ttk.Separator(control_frame, orient=tk.HORIZONTAL).pack(fill=tk.X, pady=10)
        ttk.Label(control_frame, text="Selected Zone Details:").pack(anchor=tk.W, pady=(0, 5))
        
        details_frame = ttk.Frame(control_frame)
        details_frame.pack(fill=tk.X, pady=(0, 10))
        
        ttk.Label(details_frame, text="X Min:").grid(row=0, column=0, sticky=tk.W, pady=2)
        self.x_min_var = tk.StringVar()
        self.x_min_entry = ttk.Entry(details_frame, textvariable=self.x_min_var, width=10)
        self.x_min_entry.grid(row=0, column=1, padx=5, pady=2)
        
        ttk.Label(details_frame, text="X Max:").grid(row=1, column=0, sticky=tk.W, pady=2)
        self.x_max_var = tk.StringVar()
        self.x_max_entry = ttk.Entry(details_frame, textvariable=self.x_max_var, width=10)
        self.x_max_entry.grid(row=1, column=1, padx=5, pady=2)
        
        ttk.Label(details_frame, text="Y Min:").grid(row=2, column=0, sticky=tk.W, pady=2)
        self.y_min_var = tk.StringVar()
        self.y_min_entry = ttk.Entry(details_frame, textvariable=self.y_min_var, width=10)
        self.y_min_entry.grid(row=2, column=1, padx=5, pady=2)
        
        ttk.Label(details_frame, text="Y Max:").grid(row=3, column=0, sticky=tk.W, pady=2)
        self.y_max_var = tk.StringVar()
        self.y_max_entry = ttk.Entry(details_frame, textvariable=self.y_max_var, width=10)
        self.y_max_entry.grid(row=3, column=1, padx=5, pady=2)

        ttk.Label(details_frame, text="Category:").grid(row=4, column=0, sticky=tk.W, pady=2)
        self.zone_category_var = tk.StringVar()
        ttk.Entry(details_frame, textvariable=self.zone_category_var, width=10).grid(row=4, column=1, padx=5, pady=2)

        # Color picker
        color_frame = ttk.Frame(details_frame)
        color_frame.grid(row=5, column=0, columnspan=2, sticky=tk.W, pady=2)
        ttk.Label(color_frame, text="Color:").pack(side=tk.LEFT)
        self.zone_color_var = tk.StringVar(value='#CCCCCC')
        self.color_preview = tk.Label(color_frame, bg='#CCCCCC', width=4, relief='solid', borderwidth=1)
        self.color_preview.pack(side=tk.LEFT, padx=4)
        ttk.Button(color_frame, text="Pick Color", style='Compact.TButton',
                   command=self.pick_zone_color).pack(side=tk.LEFT)
        
        ttk.Button(details_frame, text="Update Zone", style='Compact.TButton',
                  command=self.update_zone_from_entries).grid(row=6, column=0, columnspan=2, pady=6)
        
        # Right panel - Visualization
        viz_frame = ttk.Frame(main_frame)
        viz_frame.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        
        # Create matplotlib figure
        self.fig, self.ax = plt.subplots(figsize=(6.5, 6.5))
        self.canvas = FigureCanvasTkAgg(self.fig, master=viz_frame)
        self.canvas.draw()
        self.canvas.get_tk_widget().pack(fill=tk.BOTH, expand=True)
        
        # Instructions
        instructions = ("Click and drag zone edges to resize.\n"
                       "Adjust values in the left panel for precise control.")
        ttk.Label(viz_frame, text=instructions, foreground='gray').pack(pady=5)
        
        # Bind mouse events
        self.canvas.mpl_connect('button_press_event', self.on_mouse_press)
        self.canvas.mpl_connect('button_release_event', self.on_mouse_release)
        self.canvas.mpl_connect('motion_notify_event', self.on_mouse_move)
        
        # Initial plot
        self.plot_zones()
    
    def populate_zone_list(self):
        """Populate the zone listbox"""
        self.zone_listbox.delete(0, tk.END)
        for zone_name in self.zones.keys():
            self.zone_listbox.insert(tk.END, zone_name)
    
    def select_zone_from_list(self, event=None):
        """Handle zone selection from listbox"""
        selection = self.zone_listbox.curselection()
        if selection:
            zone_name = self.zone_listbox.get(selection[0])
            self.selected_zone = zone_name
            self.update_zone_details()
            self.highlight_selected_zone()
    
    def update_zone_details(self):
        """Update the zone details entry fields"""
        if self.selected_zone and self.selected_zone in self.zones:
            zone = self.zones[self.selected_zone]
            self.x_min_var.set(f"{zone['x_min']:.2f}")
            self.x_max_var.set(f"{zone['x_max']:.2f}")
            self.y_min_var.set(f"{zone['y_min']:.2f}")
            self.y_max_var.set(f"{zone['y_max']:.2f}")
            self.zone_category_var.set(zone.get('category', ''))
            color = zone.get('color', '#CCCCCC')
            self.zone_color_var.set(color)
            try:
                self.color_preview.config(bg=color)
            except Exception:
                pass
    
    def update_zone_from_entries(self):
        """Update zone from entry field values and adjust adjacent zones"""
        if not self.selected_zone:
            messagebox.showwarning("Warning", "Please select a zone first")
            return
        
        try:
            x_min = float(self.x_min_var.get())
            x_max = float(self.x_max_var.get())
            y_min = float(self.y_min_var.get())
            y_max = float(self.y_max_var.get())
            
            if x_min >= x_max or y_min >= y_max:
                messagebox.showerror("Error", "Invalid zone dimensions: min must be less than max")
                return
            
            # Get old values
            old_zone = self.zones[self.selected_zone].copy()
            
            # Update selected zone
            self.zones[self.selected_zone]['x_min'] = x_min
            self.zones[self.selected_zone]['x_max'] = x_max
            self.zones[self.selected_zone]['y_min'] = y_min
            self.zones[self.selected_zone]['y_max'] = y_max
            # Also save category and color from UI
            cat = self.zone_category_var.get().strip()
            if cat:
                self.zones[self.selected_zone]['category'] = cat
            color = self.zone_color_var.get().strip()
            if color:
                self.zones[self.selected_zone]['color'] = color
            
            # Adjust adjacent zones to maintain continuity
            # Check for zones that share borders and adjust them
            for zone_name, zone_data in self.zones.items():
                if zone_name == self.selected_zone:
                    continue
                
                # Adjust horizontal adjacency (x-axis)
                # If a zone's x_min matches our old x_max, update it to new x_max
                if abs(zone_data['x_min'] - old_zone['x_max']) < 0.01:
                    zone_data['x_min'] = x_max
                # If a zone's x_max matches our old x_min, update it to new x_min
                elif abs(zone_data['x_max'] - old_zone['x_min']) < 0.01:
                    zone_data['x_max'] = x_min
                
                # Adjust vertical adjacency (y-axis)
                # If a zone's y_min matches our old y_max, update it to new y_max
                if abs(zone_data['y_min'] - old_zone['y_max']) < 0.01:
                    zone_data['y_min'] = y_max
                # If a zone's y_max matches our old y_min, update it to new y_min
                elif abs(zone_data['y_max'] - old_zone['y_min']) < 0.01:
                    zone_data['y_max'] = y_min
            
            self.plot_zones()
            
        except ValueError:
            messagebox.showerror("Error", "Invalid numeric values")
    
    def load_template(self, event=None):
        """Load selected template"""
        template_name = self.template_var.get()
        if template_name == 'Custom Arena':
            # Keep existing zones (don't overwrite with a template).
            # If there are no zones yet, start with a single placeholder zone.
            if not self.zones:
                half = self.maze_width / 2
                self.zones = {
                    'Zone1': {
                        'x_min': 0, 'x_max': half,
                        'y_min': 0, 'y_max': half,
                        'color': '#AADDFF',
                        'category': 'zone1'
                    }
                }
            self.populate_zone_list()
            self.plot_zones()
        elif template_name in self.main_app.zone_templates:
            template = self.main_app.zone_templates[template_name]
            self.zones = {k: v.copy() for k, v in template['zones'].items()}
            self.maze_width = template['maze_width_cm']
            self.populate_zone_list()
            self.plot_zones()
    
    def plot_zones(self):
        """Plot all zones on the canvas"""
        self.ax.clear()
        self.zone_patches = {}
        
        # Set up the plot
        self.ax.set_xlim(0, self.maze_width)
        self.ax.set_ylim(0, self.maze_width)
        self.ax.set_aspect('equal')
        self.ax.set_xlabel('X (cm)')
        self.ax.set_ylabel('Y (cm)')
        self.ax.set_title('Zone Configuration')
        self.ax.grid(True, alpha=0.3)
        
        # Plot each zone
        for zone_name, zone_data in self.zones.items():
            x_min = zone_data['x_min']
            y_min = zone_data['y_min']
            width = zone_data['x_max'] - x_min
            height = zone_data['y_max'] - y_min
            
            # Create rectangle patch
            rect = Rectangle((x_min, y_min), width, height,
                           linewidth=2, edgecolor='black',
                           facecolor=zone_data.get('color', '#CCCCCC'),
                           alpha=0.5, picker=True)
            self.ax.add_patch(rect)
            self.zone_patches[zone_name] = rect
            
            # Add label
            center_x = x_min + width / 2
            center_y = y_min + height / 2
            self.ax.text(center_x, center_y, zone_name,
                        ha='center', va='center',
                        fontsize=8, weight='bold',
                        bbox=dict(boxstyle='round', facecolor='white', alpha=0.7))
        
        self.canvas.draw()
    
    def highlight_selected_zone(self):
        """Highlight the currently selected zone"""
        # Reset all zones to normal
        for zone_name, patch in self.zone_patches.items():
            if zone_name == self.selected_zone:
                patch.set_linewidth(4)
                patch.set_edgecolor('red')
            else:
                patch.set_linewidth(2)
                patch.set_edgecolor('black')
        
        self.canvas.draw()
    
    def on_mouse_press(self, event):
        """Handle mouse press for zone selection and dragging"""
        if event.inaxes != self.ax:
            return
        
        # Find which zone was clicked
        for zone_name, patch in self.zone_patches.items():
            if patch.contains(event)[0]:
                self.selected_zone = zone_name
                
                # Determine which corner/edge is being dragged
                zone = self.zones[zone_name]
                x, y = event.xdata, event.ydata
                
                # Check proximity to edges (within 10% of zone size)
                tolerance = 0.1 * min(zone['x_max'] - zone['x_min'], 
                                     zone['y_max'] - zone['y_min'])
                
                near_left = abs(x - zone['x_min']) < tolerance
                near_right = abs(x - zone['x_max']) < tolerance
                near_bottom = abs(y - zone['y_min']) < tolerance
                near_top = abs(y - zone['y_max']) < tolerance
                
                if near_left and near_bottom:
                    self.drag_corner = 'bottom_left'
                elif near_right and near_bottom:
                    self.drag_corner = 'bottom_right'
                elif near_left and near_top:
                    self.drag_corner = 'top_left'
                elif near_right and near_top:
                    self.drag_corner = 'top_right'
                elif near_left:
                    self.drag_corner = 'left'
                elif near_right:
                    self.drag_corner = 'right'
                elif near_bottom:
                    self.drag_corner = 'bottom'
                elif near_top:
                    self.drag_corner = 'top'
                
                # Update UI
                for i, zname in enumerate(self.zones.keys()):
                    if zname == zone_name:
                        self.zone_listbox.selection_clear(0, tk.END)
                        self.zone_listbox.selection_set(i)
                        break
                
                self.update_zone_details()
                self.highlight_selected_zone()
                break
    
    def on_mouse_move(self, event):
        """Handle mouse movement for dragging"""
        if event.inaxes != self.ax or not self.selected_zone or not self.drag_corner:
            return
        
        zone = self.zones[self.selected_zone]
        x, y = event.xdata, event.ydata
        
        # Store old values to calculate delta for connected zones
        old_x_min = zone['x_min']
        old_x_max = zone['x_max']
        old_y_min = zone['y_min']
        old_y_max = zone['y_max']
        
        # Update zone boundaries based on drag corner
        if 'left' in self.drag_corner:
            zone['x_min'] = max(0, min(x, zone['x_max'] - 1))
        if 'right' in self.drag_corner:
            zone['x_max'] = min(self.maze_width, max(x, zone['x_min'] + 1))
        if 'bottom' in self.drag_corner:
            zone['y_min'] = max(0, min(y, zone['y_max'] - 1))
        if 'top' in self.drag_corner:
            zone['y_max'] = min(self.maze_width, max(y, zone['y_min'] + 1))
        
        # For EPM and EPM_Complex, update connected zones to maintain adjacency
        template_name = self.template_var.get()
        if template_name in ['EPM', 'EPM_Complex']:
            self._update_connected_zones(self.selected_zone, old_x_min, old_x_max, old_y_min, old_y_max)
        
        self.update_zone_details()
        self.plot_zones()
        self.highlight_selected_zone()
    
    def _update_connected_zones(self, zone_name, old_x_min, old_x_max, old_y_min, old_y_max):
        """Update connected zones to maintain adjacency in EPM mazes"""
        zone = self.zones[zone_name]
        template_name = self.template_var.get()
        
        # Calculate what changed
        x_min_changed = zone['x_min'] != old_x_min
        x_max_changed = zone['x_max'] != old_x_max
        y_min_changed = zone['y_min'] != old_y_min
        y_max_changed = zone['y_max'] != old_y_max
        
        # Define edge connections for EPM
        if template_name == 'EPM':
            # When center changes, update arms' connection edges AND their width/position
            if zone_name == 'center':
                # Update open arms (vertical arms on Y-axis)
                if 'open_arm_up' in self.zones:
                    self.zones['open_arm_up']['y_min'] = zone['y_max']  # Connect to center top
                    self.zones['open_arm_up']['x_min'] = zone['x_min']  # Match center width
                    self.zones['open_arm_up']['x_max'] = zone['x_max']  # Match center width
                
                if 'open_arm_down' in self.zones:
                    self.zones['open_arm_down']['y_max'] = zone['y_min']  # Connect to center bottom
                    self.zones['open_arm_down']['x_min'] = zone['x_min']  # Match center width
                    self.zones['open_arm_down']['x_max'] = zone['x_max']  # Match center width
                
                # Update closed arms (horizontal arms on X-axis)
                if 'closed_arm_right' in self.zones:
                    self.zones['closed_arm_right']['x_min'] = zone['x_max']  # Connect to center right
                    self.zones['closed_arm_right']['y_min'] = zone['y_min']  # Match center width
                    self.zones['closed_arm_right']['y_max'] = zone['y_max']  # Match center width
                
                if 'closed_arm_left' in self.zones:
                    self.zones['closed_arm_left']['x_max'] = zone['x_min']  # Connect to center left
                    self.zones['closed_arm_left']['y_min'] = zone['y_min']  # Match center width
                    self.zones['closed_arm_left']['y_max'] = zone['y_max']  # Match center width
            
            # When arms change, update center edges
            elif zone_name == 'open_arm_up':
                if 'center' in self.zones and y_min_changed:
                    self.zones['center']['y_max'] = zone['y_min']
            elif zone_name == 'open_arm_down':
                if 'center' in self.zones and y_max_changed:
                    self.zones['center']['y_min'] = zone['y_max']
            elif zone_name == 'closed_arm_right':
                if 'center' in self.zones and x_min_changed:
                    self.zones['center']['x_max'] = zone['x_min']
            elif zone_name == 'closed_arm_left':
                if 'center' in self.zones and x_max_changed:
                    self.zones['center']['x_min'] = zone['x_max']
                    
        elif template_name == 'EPM_Complex':
            # More complex connections with proximal/distal zones
            if zone_name == 'center':
                # Update proximal zones connected to center
                if 'open_proximal_up' in self.zones:
                    self.zones['open_proximal_up']['y_min'] = zone['y_max']
                    self.zones['open_proximal_up']['x_min'] = zone['x_min']
                    self.zones['open_proximal_up']['x_max'] = zone['x_max']
                    # Cascade to distal
                    if 'open_distal_up' in self.zones:
                        self.zones['open_distal_up']['x_min'] = zone['x_min']
                        self.zones['open_distal_up']['x_max'] = zone['x_max']
                
                if 'open_proximal_down' in self.zones:
                    self.zones['open_proximal_down']['y_max'] = zone['y_min']
                    self.zones['open_proximal_down']['x_min'] = zone['x_min']
                    self.zones['open_proximal_down']['x_max'] = zone['x_max']
                    # Cascade to distal
                    if 'open_distal_down' in self.zones:
                        self.zones['open_distal_down']['x_min'] = zone['x_min']
                        self.zones['open_distal_down']['x_max'] = zone['x_max']
                
                if 'closed_proximal_right' in self.zones:
                    self.zones['closed_proximal_right']['x_min'] = zone['x_max']
                    self.zones['closed_proximal_right']['y_min'] = zone['y_min']
                    self.zones['closed_proximal_right']['y_max'] = zone['y_max']
                    # Cascade to distal
                    if 'closed_distal_right' in self.zones:
                        self.zones['closed_distal_right']['y_min'] = zone['y_min']
                        self.zones['closed_distal_right']['y_max'] = zone['y_max']
                
                if 'closed_proximal_left' in self.zones:
                    self.zones['closed_proximal_left']['x_max'] = zone['x_min']
                    self.zones['closed_proximal_left']['y_min'] = zone['y_min']
                    self.zones['closed_proximal_left']['y_max'] = zone['y_max']
                    # Cascade to distal
                    if 'closed_distal_left' in self.zones:
                        self.zones['closed_distal_left']['y_min'] = zone['y_min']
                        self.zones['closed_distal_left']['y_max'] = zone['y_max']
            
            # Update distal zones when proximal zones change
            elif zone_name == 'open_proximal_up':
                if 'center' in self.zones and y_min_changed:
                    self.zones['center']['y_max'] = zone['y_min']
                if 'open_distal_up' in self.zones:
                    if y_max_changed:
                        self.zones['open_distal_up']['y_min'] = zone['y_max']
                    # Match width
                    self.zones['open_distal_up']['x_min'] = zone['x_min']
                    self.zones['open_distal_up']['x_max'] = zone['x_max']
            
            elif zone_name == 'open_proximal_down':
                if 'center' in self.zones and y_max_changed:
                    self.zones['center']['y_min'] = zone['y_max']
                if 'open_distal_down' in self.zones:
                    if y_min_changed:
                        self.zones['open_distal_down']['y_max'] = zone['y_min']
                    # Match width
                    self.zones['open_distal_down']['x_min'] = zone['x_min']
                    self.zones['open_distal_down']['x_max'] = zone['x_max']
            
            elif zone_name == 'closed_proximal_right':
                if 'center' in self.zones and x_min_changed:
                    self.zones['center']['x_max'] = zone['x_min']
                if 'closed_distal_right' in self.zones:
                    if x_max_changed:
                        self.zones['closed_distal_right']['x_min'] = zone['x_max']
                    # Match width
                    self.zones['closed_distal_right']['y_min'] = zone['y_min']
                    self.zones['closed_distal_right']['y_max'] = zone['y_max']
            
            elif zone_name == 'closed_proximal_left':
                if 'center' in self.zones and x_max_changed:
                    self.zones['center']['x_min'] = zone['x_max']
                if 'closed_distal_left' in self.zones:
                    if x_min_changed:
                        self.zones['closed_distal_left']['x_max'] = zone['x_min']
                    # Match width
                    self.zones['closed_distal_left']['y_min'] = zone['y_min']
                    self.zones['closed_distal_left']['y_max'] = zone['y_max']
            
            # When distal zones change, update proximal
            elif zone_name == 'open_distal_up':
                if 'open_proximal_up' in self.zones and y_min_changed:
                    self.zones['open_proximal_up']['y_max'] = zone['y_min']
            elif zone_name == 'open_distal_down':
                if 'open_proximal_down' in self.zones and y_max_changed:
                    self.zones['open_proximal_down']['y_min'] = zone['y_max']
            elif zone_name == 'closed_distal_right':
                if 'closed_proximal_right' in self.zones and x_min_changed:
                    self.zones['closed_proximal_right']['x_max'] = zone['x_min']
            elif zone_name == 'closed_distal_left':
                if 'closed_proximal_left' in self.zones and x_max_changed:
                    self.zones['closed_proximal_left']['x_min'] = zone['x_max']
    
    def on_mouse_release(self, event):
        """Handle mouse release"""
        self.drag_corner = None
    
    def save_zones(self):
        """Save zones back to main application"""
        # Apply any pending maze width change
        self._apply_maze_width()
        self.main_app.zones = {k: v.copy() for k, v in self.zones.items()}
        self.main_app.params['maze_width_cm'] = self.maze_width
        self.main_app.params['maze_type'] = self.template_var.get()
        messagebox.showinfo("Success", "Zones saved successfully!")
        self.parent.destroy()

    def open_analysis_settings(self):
        """Open the Analysis Settings popup window."""
        win = tk.Toplevel(self.parent)
        win.title("Analysis Settings")
        win.resizable(False, False)
        win.grab_set()

        # ── Position Calibration ──────────────────────────────────────
        cal_frame = ttk.LabelFrame(win, text="Position Calibration", padding=10)
        cal_frame.pack(fill=tk.X, padx=12, pady=(12, 6))

        ttk.Label(cal_frame, text="Y-Axis Normalization Method:",
                  font=('', 9, 'bold')).pack(anchor=tk.W)

        y_cal_var = tk.StringVar(
            value=self.main_app.params.get('y_calibration_method', 'legacy'))

        cal_options = [
            ('legacy',
             'Legacy  (original behavior)',
             'y_offset = min(16, y_min_pixel)   |   Y scale = X pixel range\n'
             'May mis-align zones if the arena has vertical padding in the video.'),
            ('normalize_y_min',
             'Normalize from Y minimum  (recommended fix)',
             'y_offset = y_min_pixel   |   Y scale = X pixel range\n'
             'Removes the 16-pixel cap so Y always starts at 0 cm, matching X.'),
            ('independent_y_scale',
             'Independent X and Y scales  (most accurate)',
             'y_offset = y_min_pixel   |   Y scale = Y pixel range  (not X)\n'
             'Best when the arena appears non-square in the camera frame.'),
        ]
        for value, label, desc in cal_options:
            rb_frame = ttk.Frame(cal_frame)
            rb_frame.pack(anchor=tk.W, pady=(4, 0))
            ttk.Radiobutton(rb_frame, text=label,
                            variable=y_cal_var, value=value).pack(anchor=tk.W)
            ttk.Label(rb_frame, text=desc, foreground='gray',
                      font=('', 8)).pack(anchor=tk.W, padx=(24, 0))

        # ── Zone Entry Bouts (photometry alignment) ───────────────────
        bouts_frame = ttk.LabelFrame(
            win, text="Zone Entry Bouts  (photometry alignment windows)", padding=10)
