    def _create_zone_templates(self):
        """Create predefined zone templates for different maze types"""
        templates = {}
        
        # EPM (Elevated Plus Maze) - 76cm plus-shaped maze
        # Open arms on Y-axis, closed arms on X-axis
        # Conservative center zone based on actual mouse behavior analysis
        epm_width = 76
        epm_center = epm_width / 2  # 38 cm
        arm_length = 38
        
        # Conservative center dimensions (based on DG01 & DG11 analysis)
        # Make center a square for EPM simple and complex
        center_halfwidth = 8  # 16 cm total width/height (square center)
        
        # Arms inherit dimensions
        open_arm_width = center_halfwidth * 2  # 16 cm
        closed_arm_width = center_halfwidth * 2  # 16 cm
        
        templates['EPM'] = {
            'name': 'Elevated Plus Maze (EPM)',
            'maze_width_cm': 76,
            'zones': {
                'center': {
                    'x_min': epm_center - center_halfwidth,
                    'x_max': epm_center + center_halfwidth,
                    'y_min': epm_center - center_halfwidth,
                    'y_max': epm_center + center_halfwidth,
                    'color': '#FFD700',  # Gold
                    'category': 'center'
                },
                'open_arm_up': {
                    'x_min': epm_center - open_arm_width/2,
                    'x_max': epm_center + open_arm_width/2,
                    'y_min': epm_center + center_halfwidth,  # Start where center ends... !
                    'y_max': epm_center + arm_length,
                    'color': '#90EE90',  # Light green
                    'category': 'open'
                },
                'open_arm_down': {
                    'x_min': epm_center - open_arm_width/2,
                    'x_max': epm_center + open_arm_width/2,
                    'y_min': epm_center - arm_length,
                    'y_max': epm_center - center_halfwidth,  # Start where center ends
                    'color': '#90EE90',  # Light green
                    'category': 'open'
                },
                'closed_arm_right': {
                    'x_min': epm_center + center_halfwidth,  # Start where center ends
                    'x_max': epm_center + arm_length,
                    'y_min': epm_center - closed_arm_width/2,
                    'y_max': epm_center + closed_arm_width/2,
                    'color': '#FFB6C1',  # Light pink
                    'category': 'closed'
                },
                'closed_arm_left': {
                    'x_min': epm_center - arm_length,
                    'x_max': epm_center - center_halfwidth,  # Start where center ends...
                    'y_min': epm_center - closed_arm_width/2,
                    'y_max': epm_center + closed_arm_width/2,
                    'color': '#FFB6C1',  # Light pink
                    'category': 'closed'
                }
            }
        }
        
        # EPM Complex (Elevated Plus Maze with proximal/distal zones)
        # Open arms on Y-axis, closed arms on X-axis
        # Distal = last 10 cm of each arm
        # Proximal = remaining part of arm closer to center
        distal_length = 10  # Last 10 cm of each arm
        
        # Calculate proximal zone boundaries (from center edge to start of distal zone)
        open_arm_proximal_length = arm_length - center_halfwidth - distal_length
        closed_arm_proximal_length = arm_length - center_halfwidth - distal_length
        
        templates['EPM_Complex'] = {
            'name': 'Elevated Plus Maze (EPM) - Complex Zones',
            'maze_width_cm': 76,
            'zones': {
                'center': {
                    'x_min': epm_center - center_halfwidth,
                    'x_max': epm_center + center_halfwidth,
                    'y_min': epm_center - center_halfwidth,
                    'y_max': epm_center + center_halfwidth,
                    'color': '#FFD700',  # Gold
                    'category': 'center'
                },
                'open_proximal_up': {
                    'x_min': epm_center - open_arm_width/2,
                    'x_max': epm_center + open_arm_width/2,
                    'y_min': epm_center + center_halfwidth,  # Start where center ends
                    'y_max': epm_center + center_halfwidth + open_arm_proximal_length,
                    'color': '#98FB98',  # Pale green
                    'category': 'open_proximal'
                },
                'open_distal_up': {
                    'x_min': epm_center - open_arm_width/2,
                    'x_max': epm_center + open_arm_width/2,
                    'y_min': epm_center + center_halfwidth + open_arm_proximal_length,
                    'y_max': epm_center + arm_length,
                    'color': '#228B22',  # Forest green
                    'category': 'open_distal'
                },
                'open_proximal_down': {
                    'x_min': epm_center - open_arm_width/2,
                    'x_max': epm_center + open_arm_width/2,
                    'y_min': epm_center - center_halfwidth - open_arm_proximal_length,
                    'y_max': epm_center - center_halfwidth,  # End where center starts
                    'color': '#98FB98',  # Pale green
                    'category': 'open_proximal'
                },
                'open_distal_down': {
                    'x_min': epm_center - open_arm_width/2,
                    'x_max': epm_center + open_arm_width/2,
                    'y_min': epm_center - arm_length,
                    'y_max': epm_center - center_halfwidth - open_arm_proximal_length,
                    'color': '#228B22',  # Forest green
                    'category': 'open_distal'
                },
                'closed_proximal_right': {
                    'x_min': epm_center + center_halfwidth,  # Start where center ends
                    'x_max': epm_center + center_halfwidth + closed_arm_proximal_length,
                    'y_min': epm_center - closed_arm_width/2,
                    'y_max': epm_center + closed_arm_width/2,
                    'color': '#FFB6C1',  # Light pink
                    'category': 'closed_proximal'
                },
                'closed_distal_right': {
                    'x_min': epm_center + center_halfwidth + closed_arm_proximal_length,
                    'x_max': epm_center + arm_length,
                    'y_min': epm_center - closed_arm_width/2,
                    'y_max': epm_center + closed_arm_width/2,
                    'color': '#C71585',  # Medium violet red
                    'category': 'closed_distal'
                },
                'closed_proximal_left': {
                    'x_min': epm_center - center_halfwidth - closed_arm_proximal_length,
                    'x_max': epm_center - center_halfwidth,  # End where center starts
                    'y_min': epm_center - closed_arm_width/2,
                    'y_max': epm_center + closed_arm_width/2,
                    'color': '#FFB6C1',  # Light pink
                    'category': 'closed_proximal'
                },
                'closed_distal_left': {
                    'x_min': epm_center - arm_length,
                    'x_max': epm_center - center_halfwidth - closed_arm_proximal_length,
                    'y_min': epm_center - closed_arm_width/2,
                    'y_max': epm_center + closed_arm_width/2,
                    'color': '#C71585',  # Medium violet red
                    'category': 'closed_distal'
                }
            }
        }
        
        # OFT (Open Field Test) - 51cm square arena
        oft_width = 51
        oft_center = oft_width / 2
        center_margin = 12.75  # 25% from edge = center zone
        corner_size = 12.75  # 25% of width for corner zones
        
        templates['OFT'] = {
            'name': 'Open Field Test (OFT)',
            'maze_width_cm': 51,
            'zones': {
                'center': {
                    'x_min': center_margin,
                    'x_max': oft_width - center_margin,
                    'y_min': center_margin,
                    'y_max': oft_width - center_margin,
                    'color': '#FFD700',  # Gold
                    'category': 'center'
                },
                'corner_top_left': {
                    'x_min': 0,
                    'x_max': corner_size,
                    'y_min': oft_width - corner_size,
                    'y_max': oft_width,
                    'color': '#DDA0DD',  # Plum
                    'category': 'corner'
                },
                'corner_top_right': {
                    'x_min': oft_width - corner_size,
                    'x_max': oft_width,
                    'y_min': oft_width - corner_size,
                    'y_max': oft_width,
                    'color': '#DDA0DD',  # Plum
                    'category': 'corner'
                },
                'corner_bottom_left': {
                    'x_min': 0,
                    'x_max': corner_size,
                    'y_min': 0,
                    'y_max': corner_size,
                    'color': '#DDA0DD',  # Plum
                    'category': 'corner'
                },
                'corner_bottom_right': {
                    'x_min': oft_width - corner_size,
                    'x_max': oft_width,
                    'y_min': 0,
                    'y_max': corner_size,
                    'color': '#DDA0DD',  # Plum
                    'category': 'corner'
                },
                'edge_top': {
                    'x_min': corner_size,
                    'x_max': oft_width - corner_size,
                    'y_min': oft_width - center_margin,
                    'y_max': oft_width,
                    'color': '#87CEEB',  # Sky blue
                    'category': 'edge'
                },
                'edge_bottom': {
                    'x_min': corner_size,
                    'x_max': oft_width - corner_size,
                    'y_min': 0,
                    'y_max': center_margin,
                    'color': '#87CEEB',  # Sky blue
                    'category': 'edge'
                },
                'edge_left': {
                    'x_min': 0,
                    'x_max': center_margin,
                    'y_min': corner_size,
                    'y_max': oft_width - corner_size,
                    'color': '#87CEEB',  # Sky blue
                    'category': 'edge'
                },
                'edge_right': {
                    'x_min': oft_width - center_margin,
                    'x_max': oft_width,
                    'y_min': corner_size,
                    'y_max': oft_width - corner_size,
                    'color': '#87CEEB',  # Sky blue
                    'category': 'edge'
                }
            }
        }
        
        return templates
    
    def load_zone_template(self, template_name):
        """Load a zone template and apply it to current configuration"""
        if template_name not in self.zone_templates:
            messagebox.showerror("Error", f"Template '{template_name}' not found")
            return
        
        template = self.zone_templates[template_name]
        # Deep copy to avoid reference issues
        import copy
        self.zones = copy.deepcopy(template['zones'])
        self.params['maze_type'] = template_name
        self.params['maze_width_cm'] = template['maze_width_cm']

    def open_zone_editor(self):
        """Open interactive zone editor window"""
        editor_window = tk.Toplevel(self.root)
        editor_window.title("Zone Editor")
        self.fit_toplevel(editor_window, 1000, 800)
        
        # Create editor instance
        editor = ZoneEditor(editor_window, self)
        
        # Wait for window to close
        self.root.wait_window(editor_window)
        
    def create_menu(self):
        """Create menu bar"""
        menubar = tk.Menu(self.root)
        self.root.config(menu=menubar)
        
        # File menu
        file_menu = tk.Menu(menubar, tearoff=0)
        menubar.add_cascade(label="File", menu=file_menu)
        file_menu.add_command(label="New Project", command=self.new_project)
        file_menu.add_command(label="Open Project", command=self.open_project)
        file_menu.add_command(label="Save Project", command=self.save_project)
        file_menu.add_separator()
        file_menu.add_command(label="Exit", command=self.root.quit)
        
        # Settings menu
        settings_menu = tk.Menu(menubar, tearoff=0)
        menubar.add_cascade(label="Settings", menu=settings_menu)
        settings_menu.add_command(label="Change Project Directory", command=self.change_project_dir)
        settings_menu.add_command(label="Processing Parameters", command=self.edit_parameters)
        settings_menu.add_separator()
        settings_menu.add_command(label="Zone Editor", command=self.open_zone_editor)
        settings_menu.add_separator()

        # Interface density. Auto-picked from the screen height at startup, but
        # exposed here so users on small or high-DPI displays can override it.
        scale_menu = tk.Menu(settings_menu, tearoff=0)
        settings_menu.add_cascade(label="Interface Scale", menu=scale_menu)
        self._ui_scale_var = tk.DoubleVar(value=self.ui_scale)
        for label, value in self.UI_SCALE_PRESETS:
            scale_menu.add_radiobutton(
                label=f"{label}  ({int(value * 100)}%)",
                variable=self._ui_scale_var, value=value,
                command=lambda v=value: self.set_ui_scale(v))

        # Plot size. Figures render deliberately small by default; this lets the
        # user scale them up/down. Persisted between sessions.
        plot_menu = tk.Menu(settings_menu, tearoff=0)
        settings_menu.add_cascade(label="Plot Size", menu=plot_menu)
        self._plot_scale_var = tk.DoubleVar(value=getattr(self, 'plot_scale', 1.0))
        for label, value in self.PLOT_SCALE_PRESETS:
            plot_menu.add_radiobutton(
                label=f"{label}  ({int(value * 100)}%)",
                variable=self._plot_scale_var, value=value,
                command=lambda v=value: self.set_plot_scale(v))
        settings_menu.add_separator()
        settings_menu.add_command(label="\ud83d\udcbe Save Configuration Preset", command=self.save_config_preset)
        settings_menu.add_command(label="\ud83d\udcc2 Load Configuration Preset", command=self.load_config_preset)
    
    # ──────────────────────────────────────────────────────────────────────
    # UI density / scaling
    #
    # Fonts throughout the app are given as point sizes (e.g. ('Segoe UI', 9)).
    # Tk converts points -> pixels through its `tk scaling` factor, so changing
    # that ONE value rescales every font in the application at once, including
    # the several hundred hard-coded tuples. That is the single lever used
    # here; widget padding (which is in pixels and therefore unaffected) is
    # scaled explicitly in apply_theme(). Widget `width=`/`height=` options are
    # in character cells, so they follow the font automatically.
    # ──────────────────────────────────────────────────────────────────────

    # Named-font base point sizes. Tk on Windows reports some of these as
    # negative (= pixels), which would NOT follow `tk scaling`; normalizing them
    # to positive points makes menus, listboxes and text widgets scale too.
    _UI_NAMED_FONTS = {
        'TkDefaultFont': 9, 'TkTextFont': 9, 'TkMenuFont': 9,
        'TkHeadingFont': 9, 'TkIconFont': 9, 'TkSmallCaptionFont': 8,
        'TkTooltipFont': 8, 'TkFixedFont': 9,
    }

    UI_SCALE_PRESETS = [
        ("Compact (small screens)", 0.75),
        ("Cozy", 0.85),
        ("Default", 0.90),
        ("Comfortable", 1.00),
        ("Large", 1.15),
    ]

    # Global plot-size presets (multiplies PLOT_BASE_SCALE). 100% = the compact
    # default; users who want bigger graphs pick a larger value.
    PLOT_SCALE_PRESETS = [
        ("Tiny", 0.5),
        ("Small", 0.75),
        ("Default", 1.0),
        ("Large", 1.25),
        ("Larger", 1.5),
        ("Huge", 2.0),
    ]

    def _ui_prefs_path(self):
        return os.path.join(os.path.expanduser('~'), '.tracy_ui.json')

    def _load_ui_prefs(self):
        """Return the persisted UI-prefs dict (empty on any error). The file is a
        shared JSON store for cross-session settings (UI scale, coherence
        frequency bands, …)."""
        try:
            with open(self._ui_prefs_path(), 'r') as fh:
                data = json.load(fh)
                return data if isinstance(data, dict) else {}
        except Exception:
            return {}

    def _save_ui_prefs(self, updates):
        """Merge ``updates`` into the persisted UI-prefs file (read-modify-write)
        so writing one key never clobbers the others."""
        try:
            prefs = self._load_ui_prefs()
            prefs.update(updates)
            with open(self._ui_prefs_path(), 'w') as fh:
                json.dump(prefs, fh)
        except Exception:
            pass

    def _persist_freq_bands(self):
        """Save the current coherence frequency bands so edits survive a restart
        (fixes bands reverting to defaults every session)."""
        try:
            self._save_ui_prefs({'freq_bands': self.conn_params.get('freq_bands', [])})
        except Exception:
            pass

    def _load_persisted_conn_params(self):
        """Overlay persisted coherence settings onto conn_params at startup.
        Currently restores the user-defined frequency bands; validated so a
        corrupt file falls back to the built-in defaults already in place."""
        prefs = self._load_ui_prefs()
        bands = prefs.get('freq_bands')
        if isinstance(bands, list):
            clean = []
            for b in bands:
                try:
                    clean.append({'name': str(b['name']),
                                  'fmin': float(b['fmin']),
                                  'fmax': float(b['fmax'])})
                except (TypeError, KeyError, ValueError):
                    continue
            if clean:
                self.conn_params['freq_bands'] = clean

    def _auto_ui_scale(self):
        """Pick a density from the screen height. The layouts were authored on a
        1080p display, so shorter screens need proportionally smaller chrome for
        tall panels (e.g. the Zone Editor's control column) to fit."""
        try:
            sh = self.root.winfo_screenheight()
        except Exception:
            return 0.90
        if sh < 800:
            return 0.72
        if sh < 900:
            return 0.78
        if sh < 1000:
            return 0.85
        return 0.90

    def _init_ui_metrics(self):
        """Establish the app-wide UI scale before any widget is created."""
        try:
            self._ui_base_scaling = float(self.root.tk.call('tk', 'scaling'))
        except Exception:
            self._ui_base_scaling = 1.3333333
        # A DPI-unaware process always sees 96 DPI; guard against odd values.
        if not (0.5 <= self._ui_base_scaling <= 4.0):
            self._ui_base_scaling = 1.3333333

        prefs = self._load_ui_prefs()
        try:
            scale = float(prefs.get('ui_scale'))
        except (TypeError, ValueError):
            scale = None
        if scale is None or not (0.6 <= scale <= 1.4):
            scale = self._auto_ui_scale()
        self.ui_scale = scale
        # User plot-size preference (multiplies PLOT_BASE_SCALE in the embed
        # helper). Clamped to a sane range; default 1.0.
        try:
            ps = float(prefs.get('plot_scale', 1.0))
        except (TypeError, ValueError):
            ps = 1.0
        self.plot_scale = min(3.0, max(0.3, ps))
        self._apply_ui_scale()

    def _apply_ui_scale(self):
        """Push self.ui_scale into Tk. Safe to call again at runtime."""
        try:
            self.root.tk.call('tk', 'scaling', self._ui_base_scaling * self.ui_scale)
        except Exception:
            pass
        for name, base in self._UI_NAMED_FONTS.items():
            try:
                f = tkfont.nametofont(name)
                cur = f.cget('size')
                if cur < 0:
                    # Negative == pixels, which ignore `tk scaling`. Convert to
                    # the equivalent point size so this font scales like the
                    # rest of the app. (Sizes are already points on Windows Tk;
                    # this is for builds that report pixels.)
                    cur = int(round(abs(cur) / self._ui_base_scaling))
                f.configure(size=cur or base)
            except Exception:
                pass

    def ui_px(self, n):
        """Scale a pixel dimension (padding, canvas height, window size) to the
        current UI density. Pixels do not follow `tk scaling`, so anything
        expressed in pixels must go through here to stay proportional."""
        return max(1, int(round(n * self.ui_scale)))

    def set_ui_scale(self, value):
        """Change UI density at runtime and persist the choice."""
        self.ui_scale = float(value)
        self._apply_ui_scale()
        self.apply_theme()
        # Merge so we don't wipe other persisted prefs (e.g. freq_bands).
        self._save_ui_prefs({'ui_scale': self.ui_scale})
        try:
            messagebox.showinfo(
                "UI Scale",
                "Interface scale updated.\n\n"
                "Some panels only re-measure when rebuilt — restart TRACY for the "
                "change to apply everywhere.")
        except Exception:
            pass

    def set_plot_scale(self, value):
        """Change the global plot size at runtime and persist it. Figures are
        re-rendered at this scale the next time they are drawn."""
        try:
            self.plot_scale = min(3.0, max(0.3, float(value)))
        except (TypeError, ValueError):
            return
        self._save_ui_prefs({'plot_scale': self.plot_scale})
        try:
            messagebox.showinfo(
                "Plot Size",
                f"Plot size set to {int(round(self.plot_scale * 100))}%.\n\n"
                "Re-plot (or reopen a graph) to apply the new size.")
        except Exception:
            pass

    def fit_toplevel(self, win, width=None, height=None, parent=None):
        """Size a Toplevel so it always fits on the user's screen.

        Hard-coded dialog sizes (e.g. 1000x800) run off the bottom of a 768p or
        900p display, which is how action buttons at the foot of a dialog become
        unreachable. This clamps the request to the usable screen area, leaving
        room for the taskbar and title bar, and centers the result.
        """
        try:
            win.update_idletasks()
            sw = win.winfo_screenwidth()
            sh = win.winfo_screenheight()
            # Leave room for the taskbar / window decorations.
            max_w = max(320, sw - 40)
            max_h = max(240, sh - 90)
            w = int(width) if width else win.winfo_reqwidth()
            h = int(height) if height else win.winfo_reqheight()
            w = min(w, max_w)
            h = min(h, max_h)
            base = parent if parent is not None else self.root
            try:
                x = base.winfo_rootx() + max(0, (base.winfo_width() - w) // 2)
                y = base.winfo_rooty() + max(0, (base.winfo_height() - h) // 3)
            except Exception:
                x, y = (sw - w) // 2, (sh - h) // 3
            x = max(0, min(x, sw - w))
            y = max(0, min(y, sh - h))
            win.geometry(f"{w}x{h}+{x}+{y}")
            win.minsize(min(320, w), min(240, h))
        except Exception:
            if width and height:
                try:
                    win.geometry(f"{int(width)}x{int(height)}")
                except Exception:
                    pass
        return win

    # Every graphing tab puts the same kind of thing in the same place, so the
    # app is learned once rather than per tab. Selection (who is plotted) and
    # Settings (how) stack in a left column; Output (the figure) fills the rest.
    def make_layout_zones(self, parent, selection_title="Selection",
                          settings_title="Settings", column_px=300):
        """Return the tab's ``(selection, settings, output, actions)`` frames.

        Building the arrangement here rather than hand-laying each tab is what
        makes the consistency survive later edits.

        Selection and Settings share **one** scroll region rather than one each:
        nested scroll regions are a usability trap, and on a short screen the
        thing the user needs to reach could be in either zone. Actions sit
        outside it, pinned to the bottom of the column as established by the
        v1.9.0 accessibility pass, so the buttons never scroll away. Output
        scrolls separately, because a tall figure and a long option list are
        genuinely independent.

        The column is sized with ui_px and a grid weight, never a character
        count, so it stays proportional under Windows display scaling.
        """
        container = ttk.Frame(parent)
        container.pack(fill='both', expand=True)
        container.grid_rowconfigure(0, weight=1)
        # weight 0 keeps the controls at their measured width and hands every
        # extra pixel to the figure, which is the zone that benefits from them.
        container.grid_columnconfigure(0, weight=0, minsize=self.ui_px(column_px))
        container.grid_columnconfigure(1, weight=1)

        left = ttk.Frame(container)
        left.grid(row=0, column=0, sticky='nsew', padx=(self.ui_px(4), self.ui_px(6)),
                  pady=self.ui_px(4))
        left.grid_columnconfigure(0, weight=1)

        scroll_host = ttk.Frame(left)
        scroll_host.grid(row=0, column=0, sticky='nsew')
        # An unconstrained Canvas asks for its Tk default of 10 cm, which is a
        # physical measure and so grows with the display DPI -- at 150% it alone
        # would claim ~570 px and the controls column would be twice its
        # intended width. Ask for the width we actually want instead.
        column = self.make_scrollable(scroll_host, width=self.ui_px(column_px))

        selection = ttk.LabelFrame(column, text=selection_title, padding=4)
        selection.pack(fill='x')

        settings = ttk.LabelFrame(column, text=settings_title, padding=4)
        settings.pack(fill='both', expand=True, pady=(self.ui_px(4), 0))

        actions = ttk.Frame(left)
        actions.grid(row=1, column=0, sticky='ew', pady=(self.ui_px(4), 0))

        # Keep Actions directly beneath the controls instead of pinned to the
        # bottom of the column: row 0 asks only for what the controls need and
        # the slack falls to row 2. When the controls do overflow, row 0 is
        # capped at what is left and the buttons are still above the fold, so
        # the v1.9.0 "actions never scroll away" guarantee is unchanged.
        #
        # This is not only cosmetic. Pinned to the bottom of a maximised window,
        # a ttk.Menubutton's menu has no room to drop: Bout Analysis measured
        # 172 px below the Plot button for a 264 px menu, and Tk answers that by
        # throwing the menu to the top of the display, far from the button.
        left.grid_rowconfigure(0, weight=0)
        left.grid_rowconfigure(2, weight=1)
        _column_canvas = column._scroll_canvas

        def _fit_controls(_e=None):
            avail = max(self.ui_px(120),
                        left.winfo_height() - actions.winfo_reqheight()
                        - self.ui_px(8))
            _column_canvas.configure(
                height=min(column.winfo_reqheight(), avail))
        column.bind('<Configure>', _fit_controls, add='+')
        left.bind('<Configure>', _fit_controls, add='+')

        output_host = ttk.Frame(container)
        output_host.grid(row=0, column=1, sticky='nsew', pady=self.ui_px(4),
                         padx=(0, self.ui_px(4)))
        # Output takes every spare pixel, so its request is only a floor on how
        # narrow the window may get; keep it modest for the same reason.
        output = self.make_scrollable(output_host, width=self.ui_px(320))
        return selection, settings, output, actions

    def button_grid(self, parent, items, cols=3, style=None):
        """Lay *items* out as a wrapping grid of buttons rather than one row.

        A row of five or six actions is wider than the zone it now has to fit
        in, and a button past the right edge is simply unreachable -- there is
        no horizontal scrollbar to find it with. Wrapping costs a little height
        in a column that already scrolls.
        """
        for col in range(cols):
            parent.grid_columnconfigure(col, weight=1)
        for i, (text, command) in enumerate(items):
            kwargs = {'style': style} if style else {}
            ttk.Button(parent, text=text, command=command, **kwargs).grid(
                row=i // cols, column=i % cols, sticky='ew',
                padx=(0 if i % cols == 0 else self.ui_px(3), 0),
                pady=(0 if i < cols else self.ui_px(3), 0))

    def register_option_clusters(self, tab_key, plot_type_var, clusters, table,
                                 always=()):
        """Show only the option clusters the current plot type uses.

        *clusters* maps a name to a container frame that was gridded once and is
        then shown or hidden whole. Hiding a whole container is what keeps a
        hidden cluster from leaving a reserved gap -- hiding individual widgets
        would collapse their contents but keep their grid rows.

        *table* is ``{plot_type: {cluster_name, ...}}``. Keeping it a table
        rather than a predicate per widget means the whole disclosure rule for a
        tab can be read in one place, and one handler drives every tab.
        """
        if not hasattr(self, '_option_clusters'):
            self._option_clusters = {}
        self._option_clusters[tab_key] = (plot_type_var, clusters, table, set(always))
        plot_type_var.trace_add('write', lambda *_a: self.apply_option_disclosure(tab_key))
        # Called once here as well as on change, so the initial state is
        # established rather than inherited from however the frames were built.
        self.apply_option_disclosure(tab_key)

    def apply_option_disclosure(self, tab_key):
        """Re-apply *tab_key*'s disclosure rule for the current plot type."""
        entry = getattr(self, '_option_clusters', {}).get(tab_key)
        if not entry:
            return
        plot_type_var, clusters, table, always = entry
        try:
            plot_type = plot_type_var.get()
        except Exception:
            return
        # Match the longest key that the plot type contains, so "Distance from
        # Center (Euclidean)" cannot be captured by "Distance from Center".
        wanted = table.get(plot_type)
        if wanted is None:
            for key in sorted(table, key=len, reverse=True):
                if key in plot_type:
                    wanted = table[key]
                    break
        if wanted is None:
            # An unrecognised plot type shows everything. Hiding a control the
            # user needs is worse than showing one they do not.
            wanted = set(clusters)
        wanted = set(wanted) | always

        for name, frame in clusters.items():
            try:
                if name in wanted:
                    frame.grid()
                else:
                    frame.grid_remove()
            except Exception:
                pass

    def make_scrollable(self, parent, fit_width=False, width=None):
        """Wrap `parent` in a scrolling viewport and return the inner frame.

        Content taller than the window stays reachable by scrolling instead of
        being clipped off the bottom of the screen. With `fit_width=True` the
        viewport adopts the natural width of its content (for a fixed-width side
        column); otherwise the content is pinned to the viewport width.
        """
        outer = ttk.Frame(parent)
        outer.pack(fill=tk.BOTH, expand=True)
        canvas = tk.Canvas(outer, highlightthickness=0, borderwidth=0,
                           background=self.colors['bg_light'])
        if width is not None:
            canvas.configure(width=width)
        vsb = ttk.Scrollbar(outer, orient='vertical', command=canvas.yview)
        inner = ttk.Frame(canvas)
        win_id = canvas.create_window((0, 0), window=inner, anchor='nw')
        canvas.configure(yscrollcommand=vsb.set)
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        vsb.pack(side=tk.RIGHT, fill=tk.Y)

        def _sync(_e=None):
            canvas.configure(scrollregion=canvas.bbox('all'))
            if fit_width:
                # A Canvas does not inherit its child's size, so ask for the
                # content's natural width or the column collapses to the Tk
                # default (~238 px) and clips its controls horizontally.
                canvas.configure(width=inner.winfo_reqwidth())
            else:
                # Pin the inner frame to the viewport width so nothing is pushed
                # horizontally out of view -- and to the viewport HEIGHT while
                # the content is shorter than it.
                #
                # A canvas window item keeps its natural requested height unless
                # told otherwise, so without this every `expand=True` child is
                # capped at the content's own request and the zone sits part
                # empty with a figure clipped inside it. Measured before this
                # line existed: the Output zone wasted 449-1343 px on all eight
                # graphing tabs. Content taller than the viewport keeps its own
                # height and scrolls as before.
                canvas.itemconfigure(
                    win_id, width=canvas.winfo_width(),
                    height=max(inner.winfo_reqheight(), canvas.winfo_height()))
        inner.bind('<Configure>', _sync)
        canvas.bind('<Configure>', _sync)
        # Let callers that need to size the viewport reach it (make_layout_zones
        # caps the control column so its Actions row stays under the controls).
        inner._scroll_canvas = canvas
        # Once the item height is pinned, swapping the content changes the inner
        # frame's *requested* size but not its allocated one, so no <Configure>
        # fires and _sync would never see the new content. Anything that
        # replaces content calls _scroll_plot_zone_to_top, which re-runs this.
        canvas._resync_content = _sync

        def _wheel(event):
            canvas.yview_scroll(int(-1 * (event.delta / 120)), 'units')
        canvas.bind('<Enter>', lambda e: canvas.bind_all('<MouseWheel>', _wheel))
        canvas.bind('<Leave>', lambda e: canvas.unbind_all('<MouseWheel>'))
        return inner

    def apply_theme(self):
        """Apply custom color scheme to the application"""
        style = ttk.Style()
        px = self.ui_px

        # Configure root window
        self.root.configure(bg=self.colors['bg_light'])
        
        # Configure ttk styles
        style.theme_use('clam')
        
        # Configure notebook (tabs)
        style.configure('TNotebook', background=self.colors['bg_light'], borderwidth=0)
        style.configure('TNotebook.Tab',
                       background=self.colors['bg_medium'],
                       foreground=self.colors['text_light'],
                       padding=[px(11), px(5)],
                       font=('Segoe UI', 10, 'bold'),
                       borderwidth=0)
        style.map('TNotebook.Tab',
                 background=[('selected', self.colors['bg_dark'])],
                 foreground=[('selected', 'white')],
                 expand=[('selected', [1, 1, 1, 0])])
        
        # Configure frames
        style.configure('TFrame', background=self.colors['bg_light'])
        style.configure('TLabelframe', background=self.colors['bg_light'], 
                       foreground=self.colors['text_dark'],
                       borderwidth=2, relief='groove')
        style.configure('TLabelframe.Label', background=self.colors['bg_light'],
                       foreground=self.colors['accent_dark_blue'],
                       font=('Segoe UI', 10, 'bold'))
        
        # Configure buttons with better styling
        style.configure('TButton',
                       background=self.colors['accent_blue'],
                       foreground='white',
                       borderwidth=0,
                       relief='raised',
                       focuscolor='none',
                       font=('Segoe UI', 9, 'bold'),
                       padding=[px(8), px(4)])
        style.map('TButton',
                 background=[('active', self.colors['accent_dark_blue']),
                           ('pressed', self.colors['bg_medium'])],
                 relief=[('pressed', 'sunken'), ('active', 'raised')])
        
        # Configure labels
        style.configure('TLabel', background=self.colors['bg_light'],
                       foreground=self.colors['text_dark'],
                       font=('Segoe UI', 9))
        
        # Configure entries
        style.configure('TEntry', fieldbackground='white',
                       foreground=self.colors['text_dark'],
                       borderwidth=1)
        
        # Configure checkbuttons
        style.configure('TCheckbutton', background=self.colors['bg_light'],
                       foreground=self.colors['text_dark'],
                       font=('Segoe UI', 9))
        
        # Configure combobox
        style.configure('TCombobox', fieldbackground='white',
                       background=self.colors['accent_blue'],
                       foreground=self.colors['text_dark'])

        # Compact button variant for dense control panels, so a row of buttons
        # fits without clipping the last label. The roomy default 'TButton' is
        # kept for primary / standalone actions.
        style.configure('Compact.TButton',
                       background=self.colors['accent_blue'],
                       foreground='white',
                       borderwidth=0, relief='raised', focuscolor='none',
                       font=('Segoe UI', 9, 'bold'),
                       padding=[px(5), px(2)])
        style.map('Compact.TButton',
                 background=[('active', self.colors['accent_dark_blue']),
                           ('pressed', self.colors['bg_medium'])],
                 relief=[('pressed', 'sunken'), ('active', 'raised')])

        # Spinboxes: give the arrows a real hit target and keep the field from
        # collapsing to a couple of characters at small scales, which is what
        # made them unusable on low-resolution displays.
        for _sb in ('TSpinbox', 'TCombobox'):
            try:
                style.configure(_sb, arrowsize=px(12), padding=[px(2), px(1)])
            except tk.TclError:
                pass
        style.configure('TLabelframe', borderwidth=1)
        # A Treeview row keeps ttk's fixed 20 px height whatever the font is, so
        # at any scale above 1.0 the rows overlap and the text is clipped top and
        # bottom. Every tree in the app (subject x factor grid, exclusions,
        # per-subject shifts) is fed from here.
        try:
            style.configure('Treeview', rowheight=px(22))
        except tk.TclError:
            pass
        # Trim the default label/checkbutton/radiobutton padding so dense
        # control panels stack in noticeably less vertical space.
        for _w in ('TLabel', 'TCheckbutton', 'TRadiobutton'):
            try:
                style.configure(_w, padding=[0, px(1)])
            except tk.TclError:
                pass

    def _apply_plot_style(self):
        """Apply a single, app-wide matplotlib style so every figure (embedded
        or popped out) shares fonts, colors, grid and spines and visually
        matches the application chrome instead of looking like 20 different
        plots."""
        try:
            accent = self.colors['accent_blue']
            accent_dark = self.colors['accent_dark_blue']
            text_dark = self.colors['text_dark']
            cycle = [accent, '#e67e22', '#2ca02c', '#9467bd',
                     '#d62728', '#17becf', '#8c564b', accent_dark]
            plt.rcParams.update({
                'font.family': ['Segoe UI', 'DejaVu Sans', 'sans-serif'],
                'font.size': 9,
                'axes.titlesize': 11,
                'axes.titleweight': 'bold',
                'axes.labelsize': 9,
                'axes.labelcolor': text_dark,
                'axes.edgecolor': '#b8c2cc',
                'axes.linewidth': 0.8,
                'axes.titlecolor': text_dark,
                'axes.spines.top': False,
                'axes.spines.right': False,
                'axes.grid': True,
                'axes.axisbelow': True,
                'grid.color': '#d9e0e7',
                'grid.linewidth': 0.6,
                'grid.alpha': 0.8,
                'xtick.color': text_dark,
                'ytick.color': text_dark,
                'xtick.labelsize': 8,
                'ytick.labelsize': 8,
                'legend.fontsize': 8,
                'legend.frameon': True,
                'legend.framealpha': 0.9,
                'legend.edgecolor': '#d9e0e7',
                'figure.facecolor': 'white',
                'figure.titlesize': 12,
                'figure.titleweight': 'bold',
                'axes.facecolor': 'white',
                'savefig.facecolor': 'white',
                'savefig.dpi': 150,
                'axes.prop_cycle': plt.cycler(color=cycle),
            })
        except Exception:
            # Styling is cosmetic; never let it block startup.
            pass

    def create_notebook(self):
        """Create tabbed interface"""
        self.notebook = ttk.Notebook(self.root)
        self.notebook.pack(fill='both', expand=True, padx=5, pady=5)
        self._tab_mousewheel_handlers = {}

        # --- Main tab groups (ABEL-style): leaf tabs live in nested notebooks ---
        # Welcome is a single landing page added directly to the main notebook.
        self.create_welcome_tab()

        # Project group: project setup + data-shaping tabs
        self._project_group_frame = ttk.Frame(self.notebook)
        self.notebook.add(self._project_group_frame, text="Project")
        self.project_notebook = ttk.Notebook(self._project_group_frame)
        self.project_notebook.pack(fill='both', expand=True, padx=5, pady=5)

        # Data group: analysis / results tabs
        self._data_group_frame = ttk.Frame(self.notebook)
        self.notebook.add(self._data_group_frame, text="Data")
        self.data_notebook = ttk.Notebook(self._data_group_frame)
        self.data_notebook.pack(fill='both', expand=True, padx=5, pady=5)

        # Info group: overview, changelog, system check
        self._info_group_frame = ttk.Frame(self.notebook)
        self.notebook.add(self._info_group_frame, text="Info")
        self.info_notebook = ttk.Notebook(self._info_group_frame)
        self.info_notebook.pack(fill='both', expand=True, padx=5, pady=5)

        self._sub_notebooks = [
            self.project_notebook, self.data_notebook, self.info_notebook,
        ]
        self._group_frame_to_subnb = {
            str(self._project_group_frame): self.project_notebook,
            str(self._data_group_frame): self.data_notebook,
            str(self._info_group_frame): self.info_notebook,
        }

        # Project-group subtabs
        self.create_project_tab()
        self.create_processing_tab()
        self.create_boutframes_tab()
        self.create_factors_tab()
        self.create_exclusions_tab()
        # Data-group subtabs
        self.create_behavioral_data_tab()
        self.create_visualization_tab()
        self.create_connectivity_analysis_tab()
        self.create_spike_analysis_tab()
        self.create_bout_analysis_tab()
        self.create_decision_probability_tab()
        self.create_kinematics_tab()
        self.create_signal_linkage_tab()
        # Info-group subtabs
        self.create_info_tab()
        self.create_system_tab()

        # Keep mouse wheel bound to the active tab's scroll canvas.
        self.notebook.bind("<<NotebookTabChanged>>", self._on_notebook_tab_changed)
        for _sub_nb in self._sub_notebooks:
            _sub_nb.bind("<<NotebookTabChanged>>", self._on_notebook_tab_changed)
        self.root.after(50, self._on_notebook_tab_changed)

        # Auto-check for updates on startup (background thread, non-blocking)
        self.root.after(1500, self.check_for_updates)

    def _register_tab_mousewheel(self, tab, canvas, content_frame=None):
        """Register a tab-specific mousewheel handler for a scrollable canvas."""
        def _on_mousewheel(event):
            try:
                delta = int(-1 * (event.delta / 120))
                if delta != 0:
                    canvas.yview_scroll(delta, "units")
            except tk.TclError:
                return

        tab_id = str(tab)
        self._tab_mousewheel_handlers[tab_id] = _on_mousewheel

        def _activate_mousewheel(event=None):
            self.root.bind_all("<MouseWheel>", _on_mousewheel)

        tab.bind("<Enter>", _activate_mousewheel)
        canvas.bind("<Enter>", _activate_mousewheel)
        if content_frame is not None:
            content_frame.bind("<Enter>", _activate_mousewheel)

    def _on_notebook_tab_changed(self, event=None):
        """Bind global wheel events to the currently selected leaf tab's canvas handler."""
        current_tab = self.notebook.select()
        # If a main-tab group is selected, drill into its sub-notebook to find the
        # actually-visible leaf tab.
        sub_nb = self._group_frame_to_subnb.get(current_tab)
        if sub_nb is not None:
            current_tab = sub_nb.select()
        handler = self._tab_mousewheel_handlers.get(current_tab)
        if handler is not None:
            self.root.bind_all("<MouseWheel>", handler)
        # Factors can be created or reassigned while a graphing tab is off
        # screen. rebuild() returns immediately when nothing changed, so this
        # is cheap enough to hang off every tab switch.
        self.refresh_facet_controls()
        # _active_facet belongs to whichever tab last plotted, so left in place
        # it would resolve one tab's series names through another tab's facet
        # -- plot on Visualization with a subject deselected, then run Spike on
        # the same group, and that subject silently vanishes. Cleared here, a
        # stale name falls back to real group membership; every tab that facets
        # repopulates it before it draws. Every graphing tab now has a column,
        # but the clear is still what keeps them independent of each other.
        self._active_facet = None
        # The selection lists beside those columns are filled from the subject
        # set and group membership, which refresh_facet_controls does not touch.
        self._refresh_group_name_lists()
    
