    def update_input_fields(self):
        """Show/hide input fields based on processing mode"""
        if self.processing_mode.get() == "single":
            self.single_frame.grid(row=1, column=0, columnspan=3, sticky='ew', pady=10)
            self.batch_frame.grid_remove()
        else:
            self.single_frame.grid_remove()
            self.batch_frame.grid(row=1, column=0, columnspan=3, sticky='ew', pady=10)
    
    def apply_file_naming_settings(self):
        """Apply the file naming settings from the UI to params"""
        self.params['fpdata_pattern'] = self.fpdata_pattern_var.get().strip()
        self.params['fpdata_suffix'] = self.fpdata_suffix_var.get().strip()
        self.params['timestamp_pattern'] = self.timestamp_pattern_var.get().strip()
        self.params['timestamp_suffix'] = self.timestamp_suffix_var.get().strip()
        self.update_param_labels()
        self.log_message("File naming settings applied successfully!")

    def resolve_channel_wavelength(self, data, ch):
        """Return preferred wavelength (470 or 570) for a given channel index.

        Uses explicit per-subject mapping if present (data['channel_wavelength_map']).
        Falls back to heuristics: prefer available wavelengths, then alternate 470/570.
        """
        # If explicit numeric map exists, use it
        cmap = data.get('channel_wavelength_map')
        if isinstance(cmap, dict) and ch in cmap:
            try:
                return int(cmap[ch])
            except Exception:
                pass

        # If channel name map exists, infer from leading letter (G=470, R=570)
        names = data.get('channel_names') or data.get('channel_name_map')
        if isinstance(names, (list, dict)):
            name = None
            if isinstance(names, list) and len(names) > ch:
                name = names[ch]
            elif isinstance(names, dict) and ch in names:
                name = names[ch]
            if isinstance(name, str):
                if name.upper().startswith('G'):
                    return 470
                if name.upper().startswith('R'):
                    return 570

        has_470 = data.get('has_470', False)
        has_570 = data.get('has_570', False)
        if has_470 and not has_570:
            return 470
        if has_570 and not has_470:
            return 570

        # Default alternating assignment: even -> 470, odd -> 570
        return 470 if (ch % 2 == 0) else 570

    def get_channel_name(self, data, ch):
        """Return assigned channel name like 'G0' or 'R1' for channel index."""
        names = data.get('channel_names')
        if isinstance(names, list) and len(names) > ch:
            return names[ch]
        cmap = data.get('channel_name_map')
        if isinstance(cmap, dict) and ch in cmap:
            return cmap[ch]
        return f'Ch{ch}'

    def compute_default_channel_map(self, data, n_channels):
        """Compute a sensible default mapping of indices -> channel names.

        Rules:
        - If only 470 present, name G0..G(n-1)
        - If only 570 present, name R0..R(n-1)
        - If both present, alternate G0, R0, G1, R1...
        - Single channel -> G0
        """
        has_470 = data.get('has_470', False)
        has_570 = data.get('has_570', False)
        mapping = {}
        if n_channels <= 0:
            return mapping

        if n_channels == 1:
            mapping[0] = 'G0' if has_470 or not has_570 else 'R0'
            return mapping

        if has_470 and not has_570:
            for i in range(n_channels):
                mapping[i] = f'G{i}'
            return mapping

        if has_570 and not has_470:
            for i in range(n_channels):
                mapping[i] = f'R{i}'
            return mapping

        # Both present or unknown: alternate assignment
        g_idx = 0
        r_idx = 0
        for i in range(n_channels):
            if i % 2 == 0:
                mapping[i] = f'G{g_idx}'
                g_idx += 1
            else:
                mapping[i] = f'R{r_idx}'
                r_idx += 1
        return mapping

    def build_viz_channel_checkboxes(self, subject):
        """Create/refresh channel checkboxes for visualization tab for a subject."""
        # Clear existing
        for widget in getattr(self, 'viz_channel_check_frame').winfo_children():
            widget.destroy()

        data = self.processed_data.get(subject, {})
        n = self.get_num_channels(data)
        self.viz_channel_vars = []
        for i in range(n):
            var = tk.IntVar(value=1)
            chk = ttk.Checkbutton(self.viz_channel_check_frame,
                                  text=self.get_channel_name(data, i), variable=var)
            chk.pack(side='left')
            self.viz_channel_vars.append(var)

    def get_selected_viz_channels(self, data):
        """Return list of selected channel indices from the viz UI (or all if none).

        Accepts either a data dict or uses UI state for current selection.
        """
        # If called with data object, prefer stored mapping selection
        try:
            sel = [i for i, v in enumerate(self.viz_channel_vars) if v.get()]
            return sel if sel else list(range(self.get_num_channels(data)))
        except Exception:
            return list(range(self.get_num_channels(data)))

    def build_channel_mapping_ui(self, subject):
        """Create dropdowns allowing user to assign G/R names to each channel."""
        data = self.processed_data.get(subject, {})
        n = self.get_num_channels(data)
        parent = getattr(self, 'viz_channel_check_frame').master

        if not hasattr(self, 'viz_channel_map_frame'):
            self.viz_channel_map_frame = ttk.Frame(parent)
            self.viz_channel_map_frame.pack(side='left', padx=(10, 0))
        else:
            for w in self.viz_channel_map_frame.winfo_children():
                w.destroy()

        ttk.Label(self.viz_channel_map_frame, text='Mapping:').pack(anchor='w')

        # Determine default mapping and existing mapping.
        # channel_names may be stored as a list (index->name) or a dict; normalize to dict.
        existing = data.get('channel_name_map') or data.get('channel_names') or {}
        if isinstance(existing, list):
            existing = {idx: name for idx, name in enumerate(existing)}
        default_map = self.compute_default_channel_map(data, n)

        self.viz_channel_name_vars = []
        # Offer a generous range of designations plus whatever is already mapped,
        # so high region indices (R4/R5/…) remain selectable in the override UI.
        options = [f'G{i}' for i in range(8)] + [f'R{i}' for i in range(8)]
        for i in range(n):
            cur = existing.get(i, default_map.get(i, f'Ch{i}'))
            if cur not in options:
                options.append(cur)
        options.append('None')
        for i in range(n):
            cur = existing.get(i, default_map.get(i, f'Ch{i}'))
            var = tk.StringVar(value=cur)
            frame = ttk.Frame(self.viz_channel_map_frame)
            frame.pack(anchor='w')
            ttk.Label(frame, text=f'Ch{i}:').pack(side='left')
            combo = ttk.Combobox(frame, textvariable=var, values=options, width=6, state='readonly')
            combo.pack(side='left', padx=(4, 6))
            # Store callback
            combo.bind('<<ComboboxSelected>>', lambda e, s=subject: self.on_channel_mapping_changed(s))
            self.viz_channel_name_vars.append(var)

        # Save initial mapping into processed_data
        self.on_channel_mapping_changed(subject)

    def on_channel_mapping_changed(self, subject):
        """Save mapping selections back into processed_data for the given subject."""
        if subject not in self.processed_data:
            return
        mapping = {}
        if hasattr(self, 'viz_channel_name_vars'):
            for i, var in enumerate(self.viz_channel_name_vars):
                val = var.get()
                if val and val != 'None':
                    mapping[i] = val

        # Store both list and dict forms
        names_list = [mapping.get(i, f'Ch{i}') for i in range(max(mapping.keys())+1)] if mapping else None
        self.processed_data[subject]['channel_name_map'] = mapping
        if names_list:
            self.processed_data[subject]['channel_names'] = names_list

    def on_viz_subject_selected(self, event=None):
        """Handle subject selection in Visualization tab: refresh channel checkboxes and mapping UI."""
        sel = self.viz_subject_listbox.curselection()
        if not sel:
            return
        subject = self.viz_subject_listbox.get(sel[0])
        data = self.processed_data.get(subject, {})

        # Build channel checkboxes and mapping UI
        self.build_viz_channel_checkboxes(subject)
        self.build_channel_mapping_ui(subject)

    def get_num_channels(self, data):
        """Infer number of photometry channels from processed arrays."""
        # Check for processed zscore/dff/corrected arrays with channel columns
        keys_to_check = ['zscore_470', 'zscore_570', 'zscore', 'corrected_470', 'corrected_570', 'corrected', 'dff_470', 'dff_570', 'dff', 'data']
        for k in keys_to_check:
            if k in data and isinstance(data[k], np.ndarray) and data[k].ndim == 2:
                ncols = data[k].shape[1]
                # common format: [time, computer_ts, Ch0, Ch1, ...]
                if ncols > 2:
                    return max(0, ncols - 2)
        return 0

    def get_channel_signal(self, data, ch, kind='corrected'):
        """Return 1D numpy array for a given channel and signal kind.

        kind: one of 'raw' (data), 'dff', 'corrected', 'zscore'
        This will pick the wavelength (470/570) according to resolve_channel_wavelength.
        Returns None if no signal found for that channel.
        """
        kind_map = {
            'raw': 'data',
            'dff': 'dff',
            'corrected': 'corrected',
            'zscore': 'zscore'
        }
        base = kind_map.get(kind, kind)

        wl = self.resolve_channel_wavelength(data, ch)
        key_wl = f"{base}_{wl}"

        # Prefer wavelength-specific key
        if key_wl in data and isinstance(data[key_wl], np.ndarray):
            arr = data[key_wl]
            col_idx = 2 + ch
            if arr.shape[1] > col_idx:
                return arr[:, col_idx]

        # Fallback to non-wavelength-specific key
        if base in data and isinstance(data[base], np.ndarray):
            arr = data[base]
            # Handle deinterleaved many-col layout for 'data' where channels may be paired
            col_idx = 2 + ch
            if arr.shape[1] > col_idx:
                return arr[:, col_idx]

        return None

    def get_num_frames(self, data):
        """Return number of frames (rows) from any available processed array."""
        for k in ['zscore_470', 'zscore_570', 'zscore', 'corrected_470', 'corrected_570', 'corrected', 'dff_470', 'dff_570', 'dff', 'data']:
            if k in data and isinstance(data[k], np.ndarray):
                return data[k].shape[0]
        return 0
    
    def update_project_status(self):
        """Update project status display"""
        self.project_status_text.delete('1.0', tk.END)
        if self.current_project:
            project_path = os.path.join(self.project_dir, self.current_project)
            self.project_status_text.insert('1.0', f"Project: {self.current_project}\n")
            self.project_status_text.insert('end', f"Location: {project_path}\n\n")
            
            # Show folder structure
            self.project_status_text.insert('end', "Project Structure:\n")
            self.project_status_text.insert('end', f"  📁 {self.current_project}/\n")
            self.project_status_text.insert('end', f"    📄 project_config.json (full project configuration)\n")
            self.project_status_text.insert('end', f"    📄 {self.current_project}.tracy (groups & settings - for sharing)\n")
            self.project_status_text.insert('end', f"    📁 raw/ (original data files)\n")
            self.project_status_text.insert('end', f"    📁 processed/ (processed subject data)\n")
            self.project_status_text.insert('end', f"    📁 figures/ (exported plots)\n\n")
            
            # List processed subjects
            if self.processed_data:
                self.project_status_text.insert('end', f"Processed Subjects ({len(self.processed_data)}):\n")
                for subject in self.processed_data.keys():
                    excluded_info = ""
                    if subject in self.exclusions and self.exclusions[subject]:
                        excluded_channels = ', '.join(self.exclusions[subject])
                        excluded_info = f" [Excluded: {excluded_channels}]"
                    self.project_status_text.insert('end', f"  - {subject}{excluded_info}\n")
            
            # Show exclusions summary
            if self.exclusions:
                total_exclusions = sum(len(channels) for channels in self.exclusions.values())
                self.project_status_text.insert('end', f"\nExclusions Summary:\n")
                self.project_status_text.insert('end', f"  {total_exclusions} channel(s) excluded across {len(self.exclusions)} subject(s)\n")
        else:
            self.project_status_text.insert('1.0', "No project loaded.\nCreate or open a project to begin.")
    
    def log_message(self, message):
        """Add message to results log"""
        self.results_text.insert('end', f"{message}\n")
        self.results_text.see('end')
        self.root.update()
    
