    def _order_zones_by_category(self, zones):
        """Order zones according to their category using defined order"""
        zone_to_category = {}
        for zone_name in zones:
            if zone_name in self.zones:
                zone_to_category[zone_name] = self.zones[zone_name].get('category', 'other')
            else:
                zone_to_category[zone_name] = 'other'
        
        maze_type = self.params.get('maze_type', 'EPM')
        category_order = self._get_category_order(maze_type)
        
        if category_order:
            # Sort zones by their category order, then alphabetically within category
            def sort_key(zone_name):
                category = zone_to_category.get(zone_name, 'other')
                try:
                    cat_idx = category_order.index(category)
                except ValueError:
                    cat_idx = len(category_order)
                return (cat_idx, zone_name)
            
            return sorted(zones, key=sort_key)
        else:
            return sorted(zones)
    
    def _get_zone_color(self, zone_name):
        """Get color for a zone based on its category"""
        if zone_name in self.zones:
            return self.zones[zone_name].get('color', '#808080')
        return '#808080'
    
    def _get_aggregate_zone_name(self, zone_name, mode='simple'):
        """Get aggregate name for a zone (combines bilateral zones)
        
        Args:
            zone_name: The name of the zone
            mode: 'simple' for basic aggregation (open, center, closed) or 'complex' for detailed zones
        """
        # Remove directional suffixes to create aggregate names
        zone_lower = zone_name.lower()
        
        # In simple mode, aggregate all open/closed zones together
        if mode == 'simple':
            # Map specific zones to simple aggregates
            if any(x in zone_lower for x in ['open_arm', 'open_proximal', 'open_distal']):
                return 'open_arms'
            elif any(x in zone_lower for x in ['closed_arm', 'closed_proximal', 'closed_distal']):
                return 'closed_arms'
            elif 'corner_' in zone_lower:
                return 'corners'
            elif 'edge_' in zone_lower:
                return 'edges'
            else:
                # Keep as-is for center and other zones
                return zone_name
        
        # In complex mode, keep proximal/distal separate but combine bilateral zones
        # Check for proximal/distal zones first (more specific)
        if 'open_proximal_up' in zone_lower or 'open_proximal_down' in zone_lower:
            return 'open_proximal'
        elif 'open_distal_up' in zone_lower or 'open_distal_down' in zone_lower:
            return 'open_distal'
        elif 'closed_proximal_left' in zone_lower or 'closed_proximal_right' in zone_lower:
            return 'closed_proximal'
        elif 'closed_distal_left' in zone_lower or 'closed_distal_right' in zone_lower:
            return 'closed_distal'
        # For simple EPM (non-complex), aggregate arms
        elif 'open_arm_up' in zone_lower or 'open_arm_down' in zone_lower:
            return 'open_arms'
        elif 'closed_arm_left' in zone_lower or 'closed_arm_right' in zone_lower:
            return 'closed_arms'
        elif 'corner_' in zone_lower:
            return 'corners'
        elif 'edge_' in zone_lower:
            return 'edges'
        else:
            # Keep as-is for center and other zones
            return zone_name
    
    def _order_aggregate_zones(self, zones, maze_type, mode='simple'):
        """Order aggregate zones according to maze type and mode
        
        Args:
            zones: List of zone names
            maze_type: Type of maze (EPM, EPM_Complex, OFT, etc.)
            mode: 'simple' for basic aggregation (open, center, closed) or 'complex' for detailed zones
        """
        if mode == 'simple':
            # Simple mode always shows 3 zones for EPM
            if maze_type in ['EPM', 'EPM_Complex']:
                order = ['closed_arms', 'center', 'open_arms']
            elif maze_type == 'OFT':
                order = ['corners', 'edges', 'center']
            else:
                return sorted(zones)
        else:
            # Complex mode shows detailed breakdown
            if maze_type == 'EPM_Complex':
                order = ['closed_distal', 'closed_proximal', 'center', 'open_proximal', 'open_distal']
            elif maze_type == 'EPM':
                order = ['closed_arms', 'center', 'open_arms']
            elif maze_type == 'OFT':
                order = ['corners', 'edges', 'center']
            else:
                return sorted(zones)
        
        # Sort zones according to the order
        ordered = []
        for item in order:
            if item in zones:
                ordered.append(item)
        
        # Add any zones not in the predefined order
        for zone in sorted(zones):
            if zone not in ordered:
                ordered.append(zone)
        
        return ordered
    
    def _get_aggregate_zone_color(self, aggregate_name, maze_type):
        """Get color for an aggregate zone"""
        color_map = {
            'open_arms': '#90EE90',
            'open_arm': '#90EE90',
            'closed_arms': '#FFB6C1',
            'closed_arm': '#FFB6C1',
            'open_proximal': '#98FB98',
            'open_distal': '#228B22',
            'closed_proximal': '#FFB6C1',
            'closed_distal': '#C71585',
            'center': '#FFD700',
            'corners': '#DDA0DD',
            'edges': '#87CEEB'
        }
        return color_map.get(aggregate_name, '#808080')
    
    def _is_valid_bout(self, bout, min_std=0.01):
        """Check if bout has valid data
        
        Args:
            bout: Bout trace array
            min_std: Minimum standard deviation threshold
            
        Returns:
            bool: True if bout is valid, False otherwise
        """
        # Check for all NaN
        if np.all(np.isnan(bout)):
            return False
        
        # Check for all zeros
        if np.all(bout == 0):
            return False
        
        # Check for constant values (std = 0 or very close to 0)
        bout_std = np.nanstd(bout)
        if np.isnan(bout_std) or bout_std < min_std:
            return False
        
        # Check if all values are identical (within floating point precision)
        unique_vals = np.unique(bout[~np.isnan(bout)])
        if len(unique_vals) == 1:
            return False
        
        return True
    
    def apply_baseline_correction(self, bout, frame, start_idx, prebout, baseline_frames):
        """Apply baseline correction to a bout trace"""
        # Calculate where the actual prebout starts within the bout array
        actual_prebout_length = frame - start_idx
        
        # Determine the baseline window (first N frames of the prebout period)
        baseline_end = min(baseline_frames, actual_prebout_length)
        
        if baseline_end > 0:
            # Calculate mean of baseline period
            baseline_mean = np.nanmean(bout[:baseline_end])
            
            # Subtract baseline from entire trace
            if not np.isnan(baseline_mean):
                bout_corrected = bout - baseline_mean
                return bout_corrected
        
        # If baseline correction can't be applied, return original
        return bout
    
    def convert_ttl_to_boutframes(self, ttl_file, computer_timestamps):
        """Convert TTL or DigitalIOs timestamps to boutframes format
        
        Supports two file formats:
        1. TTL format: timestamp,value (no header) - processes every other row
        2. DigitalIOs format: DigitalIOName,Flag,State,SystemTS,ComputerTS (with header) - processes all rows
        
        Args:
            ttl_file: Path to TTL/DigitalIOs CSV file
            computer_timestamps: Array of computer timestamps from FP data
            
        Returns:
            DataFrame with columns: Behavior, Frame
        """
        try:
            # Load file and check format
            # First try with header to detect DigitalIOs format
            ttl_data_with_header = pd.read_csv(ttl_file)
            
            # Detect file format
            is_digitalios = False
            if 'DigitalIOName' in ttl_data_with_header.columns or 'ComputerTimestamp' in ttl_data_with_header.columns:
                is_digitalios = True
                self.log_message(f"Detected DigitalIOs format file")
            
            if is_digitalios:
                # DigitalIOs format: behavior in column 0, timestamp in column 4
                behavior_names = ttl_data_with_header.iloc[:, 0].values
                bout_timestamps = ttl_data_with_header.iloc[:, 4].values  # ComputerTimestamp column
                
                self.log_message(f"Found {len(bout_timestamps)} DigitalIO events in file")
                
                # Convert timestamps to frames by finding nearest computer timestamp
                bout_frames = []
                bout_behaviors = []
                for i, (behavior, ttl_ts) in enumerate(zip(behavior_names, bout_timestamps)):
                    # Find the closest frame
                    frame_diffs = np.abs(computer_timestamps - ttl_ts)
                    closest_frame = np.argmin(frame_diffs)
                    min_diff = frame_diffs[closest_frame]
                    
                    # Only include if within reasonable threshold (e.g., 1 second)
                    # TTL timestamps are in microseconds, so 1 second = 1,000,000
                    if min_diff < 1000000:  # 1 second
                        bout_frames.append(closest_frame)
                        bout_behaviors.append(behavior)
                        self.log_message(f"  {behavior} @ {ttl_ts:.1f} -> Frame {closest_frame} (diff: {min_diff:.1f})")
                    else:
                        self.log_message(f"  WARNING: {behavior} timestamp {ttl_ts} not found in recording range (min diff: {min_diff:.1f})")
                
                # Create boutframes DataFrame with behavior names
                boutframes_df = pd.DataFrame({
                    'Behavior': bout_behaviors,
                    'Frame': bout_frames
                })
                
                self.log_message(f"Successfully converted {len(bout_frames)} DigitalIO events to bout frames")
                
            else:
                # Original TTL format: timestamp in column 0, no header.
                ttl_data = pd.read_csv(ttl_file, header=None)
                ttl_timestamps = ttl_data.iloc[:, 0].values

                # How the rows map to bouts is controlled by the 'ttl_format'
                # param (set via the "Raw TTL event format" selector):
                #   'pairs_start'    – onset/offset pairs; keep onsets only [legacy]
                #   'single'         – one row per bout (each row is an onset)
                #   'pairs_startend' – onset/offset pairs; emit start AND end frames
                ttl_format = self.params.get('ttl_format', 'pairs_start')

                def _ts_to_frame(ttl_ts, label='TTL'):
                    """Nearest FP frame for a TTL timestamp, or None if out of range."""
                    frame_diffs = np.abs(computer_timestamps - ttl_ts)
                    closest_frame = int(np.argmin(frame_diffs))
                    min_diff = frame_diffs[closest_frame]
                    # TTL timestamps are in microseconds, so 1 second = 1,000,000
                    if min_diff < 1000000:  # within 1 second
                        self.log_message(
                            f"  {label} @ {ttl_ts:.1f} -> Frame {closest_frame} (diff: {min_diff:.1f})")
                        return closest_frame
                    self.log_message(
                        f"  WARNING: {label} timestamp {ttl_ts} not found in recording "
                        f"range (min diff: {min_diff:.1f})")
                    return None

                if ttl_format == 'pairs_startend':
                    # Pair rows: even index = onset, following odd index = offset.
                    start_ts = ttl_timestamps[::2]
                    end_ts = ttl_timestamps[1::2]
                    n_pairs = min(len(start_ts), len(end_ts))
                    if len(start_ts) != len(end_ts):
                        self.log_message(
                            f"  WARNING: odd number of TTL rows ({len(ttl_timestamps)}); "
                            f"last onset has no matching offset and was dropped.")
                    self.log_message(
                        f"Found {n_pairs} TTL onset/offset pair(s) in file "
                        f"(start/end bout format)")
                    start_frames, end_frames = [], []
                    for i in range(n_pairs):
                        sf = _ts_to_frame(start_ts[i], 'TTL start')
                        ef = _ts_to_frame(end_ts[i], 'TTL end')
                        # Keep the pair only when the onset resolved; a missing
                        # offset is allowed (stored as NaN so the bout still counts).
                        if sf is not None:
                            start_frames.append(sf)
                            end_frames.append(ef if ef is not None else np.nan)
                    # Long form with paired __start / __end behaviors.  The
                    # downstream groupby + _parse_boutframes_dataframe machinery
                    # turns these into aligned start/end boutframes columns.
                    boutframes_df = pd.DataFrame({
                        'Behavior': (['TTL__start'] * len(start_frames)
                                     + ['TTL__end'] * len(end_frames)),
                        'Frame': start_frames + end_frames,
                    })
                    self.log_message(
                        f"Successfully converted {len(start_frames)} TTL bout(s) "
                        f"with start & end frames")
                else:
                    # 'single' = every row is a bout onset; 'pairs_start' = legacy
                    # onset/offset pairs, keep onsets only (rows 0, 2, 4 ...).
                    if ttl_format == 'single':
                        bout_timestamps = ttl_timestamps
                        self.log_message(
                            f"Found {len(bout_timestamps)} TTL events in file "
                            f"(one row per bout)")
                    else:
                        bout_timestamps = ttl_timestamps[::2]
                        self.log_message(
                            f"Found {len(bout_timestamps)} TTL events in file "
                            f"(onset/offset pairs, onsets only)")

                    bout_frames = []
                    for ttl_ts in bout_timestamps:
                        frame = _ts_to_frame(ttl_ts)
                        if frame is not None:
                            bout_frames.append(frame)

                    boutframes_df = pd.DataFrame({
                        'Behavior': ['TTL'] * len(bout_frames),
                        'Frame': bout_frames
                    })
                    self.log_message(
                        f"Successfully converted {len(bout_frames)} TTL events to bout frames")
            
            return boutframes_df
            
        except Exception as e:
            self.log_message(f"Error converting TTL/DigitalIOs file: {str(e)}")
            import traceback
            self.log_message(traceback.format_exc())
            return None
    
    # ── Session-aware boutframes lookup ──────────────────────────────────
    #
    # A subject ID is one *recording* (`CAB01_Alcohol`), and a multi-session
    # project holds several recordings per animal.  The boutframes workbook may
    # therefore be laid out either way round:
    #
    #   per-recording  one sheet named `CAB01_Alcohol`  -- read whole
    #   per-animal     one sheet named `CAB01` carrying a `Session` column
    #                  -- read the rows whose Session is this recording's
    #
    # The per-animal form is what tools/combine_sessions.py writes, because one
    # sheet per animal keeps "everything scored for CAB01" together and does not
    # multiply the sheet count by the number of days.  Single-session projects
    # have neither a session label nor a Session column and are unaffected.

    def _boutframes_sheet_index(self, path):
        """``{lowercased sheet name: real sheet name}`` for *path*, cached.

        Cached on (path, mtime) because bout extraction resolves a sheet once
        per recording per behaviour, and opening the workbook just to list its
        sheets is far more expensive than reading one.
        """
        try:
            key = (os.path.abspath(path), os.path.getmtime(path))
        except OSError:
            return {}
        cached = getattr(self, '_bf_sheet_cache', None)
        if cached is not None and cached[0] == key:
            return cached[1]
        try:
            wb = load_workbook(path, read_only=True)
            try:
                index = {str(s).strip().lower(): s for s in wb.sheetnames}
            finally:
                wb.close()
        except Exception:
            return {}
        self._bf_sheet_cache = (key, index)
        return index

    def resolve_boutframes_sheet(self, path, subject_id):
        """Which worksheet of *path* holds the bouts for recording *subject_id*.

        Returns ``(sheet_name, session_label)``.  ``sheet_name`` is None when
        nothing matches; ``session_label`` is the session the rows must be
        filtered to, or '' when the whole sheet belongs to this recording.
        """
        sid = str(subject_id)
        index = self._boutframes_sheet_index(path)
        if not index:
            return None, ''

        # A sheet named for the recording itself always wins: it is unambiguous,
        # and it is what the TTL merge writes.
        hit = index.get(sid.strip().lower())
        if hit is not None:
            return hit, ''

        animal, session = split_subject_id(sid, self._session_pattern())
        if session:
            hit = index.get(str(animal).strip().lower())
            if hit is not None:
                return hit, session
        return None, ''

    @classmethod
    def _session_column(cls, df):
        """The column tagging each row with its session, if the sheet has one."""
        for c in df.columns:
            if str(c).strip().lower() in cls.BOUTFRAMES_SESSION_COLUMNS:
                return c
        return None

    def read_boutframes_sheet(self, path, subject_id):
        """Bouts for one recording as a DataFrame, session-filtered.

        Raises the same way ``pd.read_excel`` did when there is no usable sheet,
        so callers that already guard bout reading with try/except keep working.
        """
        sheet, session = self.resolve_boutframes_sheet(path, subject_id)
        if sheet is None:
            raise ValueError(
                f"No boutframes sheet for '{subject_id}'. Expected a sheet named "
                f"'{subject_id}', or one named for its animal with a "
                f"'{self.BOUTFRAMES_SESSION_COLUMNS[0].title()}' column.")
        df = pd.read_excel(path, sheet_name=sheet)
        return self.filter_boutframes_rows(df, session)

    def _update_boutframes_layout_label(self):
        """Say, on the Processing tab, how the workbook maps onto this project.

        "31 sheets" tells the user nothing when they have 93 recordings; whether
        those sheets resolved is the thing worth showing, and it is the failure
        that would otherwise only surface as "no bouts" much later.
        """
        label = getattr(self, 'boutframes_layout_label', None)
        if label is None:
            return
        path = self.boutframes_path_var.get()
        if not path or not os.path.exists(path):
            label.config(
                text="One worksheet per subject.  Multi-session projects may instead "
                     "key sheets by animal and add a 'Session' column.",
                foreground='gray')
            return

        index = self._boutframes_sheet_index(path)
        subjects = list(self.processed_data)
        if not subjects:
            label.config(text=f"{len(index)} worksheet(s).  Process subjects to see "
                              f"how they map onto recordings.", foreground='gray')
            return

        by_session = sum(1 for s in subjects
                         if self.resolve_boutframes_sheet(path, s)[1])
        missing = [s for s in subjects
                   if self.resolve_boutframes_sheet(path, s)[0] is None]
        parts = [f"{len(index)} sheet(s) → {len(subjects) - len(missing)}/"
                 f"{len(subjects)} recording(s)"]
        if by_session:
            parts.append(f"{by_session} matched by animal + Session column")
        if missing:
            parts.append("no sheet for " + ", ".join(missing[:4])
                         + (f" (+{len(missing) - 4} more)" if len(missing) > 4 else ""))
        label.config(text="  |  ".join(parts),
                     foreground='red' if missing else 'gray')

    def boutframes_recording_for_sheet(self, path, sheet, behavior=None):
        """The processed recording a worksheet belongs to, or None.

        The Boutframes tab picks a *sheet*, but the per-subject shift, the
        photometry rate and the session length it previews against are
        properties of a *recording*.  With one sheet per animal that is a
        one-to-many map, so *behaviour* breaks the tie: the recording whose
        session actually scored it.
        """
        candidates = [sid for sid in self.processed_data
                      if self.resolve_boutframes_sheet(path, sid)[0] == sheet]
        if len(candidates) <= 1:
            return candidates[0] if candidates else None
        if behavior:
            for sid in sorted(candidates):
                try:
                    df = self.read_boutframes_sheet(path, sid)
                except Exception:
                    continue
                if behavior in df.columns and pd.to_numeric(
                        df[behavior], errors='coerce').notna().any():
                    return sid
        return sorted(candidates)[0]

    def boutframes_behavior_columns(self, path):
        """Every behaviour column name in the workbook, session tags excluded."""
        names = set()
        with pd.ExcelFile(path) as xl:
            for sheet in xl.sheet_names:
                names.update(
                    str(c) for c in xl.parse(sheet, nrows=0).columns
                    if str(c).strip().lower() not in self.BOUTFRAMES_SESSION_COLUMNS)
        return names

    def iter_boutframes_recordings(self, path):
        """Yield ``(label, subject_id_or_None, DataFrame)`` per recording in *path*.

        Reports that summarise a whole workbook (the exclusion preview) have to
        work one recording at a time, not one sheet at a time: a per-animal
        sheet holds several sessions, and rules like the proximity gap are
        meaningless applied across a boundary between two different days.

        Recording IDs come from the processed project when there is one, so the
        rows are attributed to real subjects.  With nothing processed yet the
        sheets are split on their session column and labelled for display only,
        which is enough for a preview.
        """
        index = self._boutframes_sheet_index(path)
        if not index:
            return

        resolved = {}       # real sheet name -> [(label, subject_id, session)]
        for sid in self.processed_data:
            sheet, session = self.resolve_boutframes_sheet(path, sid)
            if sheet is not None:
                resolved.setdefault(sheet, []).append((str(sid), str(sid), session))

        for sheet in index.values():
            try:
                df = pd.read_excel(path, sheet_name=sheet)
            except Exception:
                continue
            if sheet in resolved:
                for label, sid, session in sorted(resolved[sheet]):
                    yield label, sid, self.filter_boutframes_rows(df, session)
                continue
            col = self._session_column(df)
            if col is None:
                yield str(sheet), None, df
                continue
            for session in df[col].dropna().astype(str).str.strip().unique():
                yield (f"{sheet} [{session}]", None,
                       self.filter_boutframes_rows(df, session))

    def filter_boutframes_rows(self, df, session):
        """Keep the rows of an animal-level sheet scored in *session*.

        Sheets without a session column are returned unchanged -- that is the
        single-session layout, and every row of them belongs to the recording.
        """
        col = self._session_column(df)
        if col is None:
            return df
        if not session:
            # A recording whose ID carries no session cannot claim rows tagged
            # with one; fall back to the untagged rows, else the whole sheet.
            blank = df[col].isna() | (df[col].astype(str).str.strip() == '')
            return (df.loc[blank].drop(columns=[col]).reset_index(drop=True)
                    if blank.any() else df.drop(columns=[col]))
        want = str(session).strip().lower()
        keep = df[col].astype(str).str.strip().str.lower() == want
        return df.loc[keep].drop(columns=[col]).reset_index(drop=True)

    # ── Start/End boutframes helpers ─────────────────────────────────────
    @staticmethod
    def _boutframe_base_behavior(col):
        """Return the base behavior name for a boutframes column, stripping a
        trailing ``__start`` / ``__end`` suffix (matched case-insensitively)."""
        cl = str(col).lower()
        if cl.endswith('__start'):
            return str(col)[:-len('__start')]
        if cl.endswith('__end'):
            return str(col)[:-len('__end')]
        return str(col)

    @classmethod
    def _parse_boutframes_dataframe(cls, df):
        """Parse a boutframes sheet into behaviors with raw start/end frame arrays.

        Two formats are supported and may be mixed in the same sheet:
          * Start-only (legacy): one column per behavior, holding start frames.
          * Start/End: paired columns ``Behavior__start`` and ``Behavior__end``
            (double-underscore separator, matched case-insensitively).

        Returns
        -------
        behaviors : list of (name, start_array, end_array_or_None)
            ``start_array`` is float with NaN rows dropped.  ``end_array`` is
            float aligned row-wise to ``start_array`` (may contain NaN where an
            individual bout has no scored end), or ``None`` for start-only
            behaviors.
        has_end_any : bool
            True if at least one behavior carries end frames.
        """
        # A session tag is metadata about the row, not a behaviour scored in it;
        # without this it would come back as a behaviour called "Session" whose
        # frames are all NaN, and show up in every behaviour dropdown.
        cols = [c for c in df.columns
                if str(c).strip().lower() not in cls.BOUTFRAMES_SESSION_COLUMNS]
        end_map = {}      # base_name_lower -> end column
        for c in cols:
            cl = str(c).lower()
            if cl.endswith('__end'):
                end_map[cl[:-len('__end')]] = c

        behaviors = []
        has_end_any = False
        seen_bases = set()
        for c in cols:
            cl = str(c).lower()
            if cl.endswith('__end'):
                continue  # handled via its matching __start column
            if cl.endswith('__start'):
                base = cl[:-len('__start')]
                if base in seen_bases:
                    continue
                seen_bases.add(base)
                name = str(c)[:-len('__start')]
                start_arr = pd.to_numeric(df[c], errors='coerce').to_numpy(dtype=float)
                end_col = end_map.get(base)
                if end_col is not None:
                    end_arr = pd.to_numeric(df[end_col], errors='coerce').to_numpy(dtype=float)
                    has_end_any = True
                else:
                    end_arr = None
                mask = ~np.isnan(start_arr)
                start_arr = start_arr[mask]
                if end_arr is not None:
                    end_arr = end_arr[mask]
                behaviors.append((name, start_arr, end_arr))
            else:
                # Legacy start-only behavior column
                start_arr = pd.to_numeric(df[c], errors='coerce').to_numpy(dtype=float)
                start_arr = start_arr[~np.isnan(start_arr)]
                behaviors.append((str(c), start_arr, None))
        return behaviors, has_end_any

    def _transform_boutframe_values(self, frames, subject_id, as_int=True):
        """Apply FPS scaling, manual shift, per-subject shift, and precut correction
        to a boutframe array (same order/logic used for start frames historically).

        Used for both start and end frames so they stay consistent.  When
        *as_int* is False the result is rounded but kept as float so NaN (a
        missing per-bout end) is preserved.
        """
        frames = np.asarray(frames, dtype=float)
        if frames.size == 0:
            return frames.astype(int) if as_int else frames
        subject_data = self.processed_data.get(subject_id, {})

        # FPS scaling
        if self.params.get('auto_scale_boutframes', False):
            vfps = float(self.params.get('boutframes_video_fps', 30))
            pfps = subject_data.get('photometry_fps', getattr(self, 'detected_photometry_fps', None))
            if pfps and vfps > 0 and abs(pfps - vfps) > 0.1:
                frames = np.round(frames * (pfps / vfps))

        # Manual + per-subject shift
        ms = int(self.params.get('boutframe_manual_shift', 0))
        if ms:
            frames = frames + ms
        ps = self._get_per_subject_shift(subject_id)
        if ps:
            frames = frames + ps

        # Precut correction
        if self.params.get('precut_correct_boutframes', True):
            pc = int(self.params.get('precut', 0))
            nl = int(subject_data.get('n_led_states', 1))
            off = pc // max(1, nl)
            if off > 0:
                frames = frames - off

        if as_int:
            return frames.astype(int)
        return np.round(frames)

    def _inverse_transform_boutframe_values(self, frames, subject_id, as_int=True):
        """Inverse of :meth:`_transform_boutframe_values`.

        Maps photometry-frame numbers back into raw boutframe (video-frame)
        coordinates, undoing precut correction, the per-subject + manual shift,
        and FPS scaling **in reverse order**.  The random-shuffle generator
        places bouts in photometry-frame space (where the extraction window is
        defined) and stores them as raw frames, so it needs this inverse.
        """
        frames = np.asarray(frames, dtype=float)
        if frames.size == 0:
            return frames.astype(int) if as_int else frames
        subject_data = self.processed_data.get(subject_id, {})

        # Undo precut correction (forward subtracted the offset)
        if self.params.get('precut_correct_boutframes', True):
            pc = int(self.params.get('precut', 0))
            nl = int(subject_data.get('n_led_states', 1))
            off = pc // max(1, nl)
            if off > 0:
                frames = frames + off

        # Undo per-subject + manual shift
        ps = self._get_per_subject_shift(subject_id)
        if ps:
            frames = frames - ps
        ms = int(self.params.get('boutframe_manual_shift', 0))
        if ms:
            frames = frames - ms

        # Undo FPS scaling
        if self.params.get('auto_scale_boutframes', False):
            vfps = float(self.params.get('boutframes_video_fps', 30))
            pfps = subject_data.get('photometry_fps', getattr(self, 'detected_photometry_fps', None))
            if pfps and vfps > 0 and abs(pfps - vfps) > 0.1:
                frames = frames * (vfps / pfps)

        if as_int:
            return np.round(frames).astype(int)
        return np.round(frames)

    @staticmethod
    def _feasible_bout_count(span, min_spacing):
        """Maximum number of starts that fit in *span* frames at *min_spacing*
        apart using the jittered-grid layout (each of N bins must be at least
        min_spacing wide)."""
        if span <= 0 or min_spacing <= 0:
            return 0
        return max(0, int(span // min_spacing))

    @staticmethod
    def _generate_jittered_starts(lo, hi, n, min_spacing, rng):
        """Place *n* start frames pseudo-randomly in ``[lo, hi]`` so they span the
        range yet never overlap.

        Uses a *jittered grid*: the range is split into ``n`` equal bins and one
        start is drawn per bin, jittered by a bounded amount so that two adjacent
        starts can never come closer than *min_spacing*.  This guarantees both
        properties the user asked for — the bouts are spread across the whole
        session (one per bin) and are non-overlapping (bounded jitter).

        Returns a float array of length ``min(n, feasible_max)`` sorted ascending.
        """
        lo = float(lo); hi = float(hi)
        span = hi - lo
        if n < 1 or span <= 0 or min_spacing <= 0:
            return np.array([], dtype=float)
        n = min(int(n), max(1, int(span // min_spacing)))
        if n == 1:
            return np.array([lo + span / 2.0])
        bin_w = span / n
        # Bounded jitter: consecutive bin centres are bin_w apart and each moves
        # by at most j, so the closest two starts can be is bin_w - 2j = min_spacing.
        j = max(0.0, (bin_w - min_spacing) / 2.0)
        centers = lo + bin_w * (np.arange(n) + 0.5)
        jit = rng.uniform(-j, j, size=n) if j > 0 else np.zeros(n)
        return centers + jit

    def _apply_bout_exclusions(self, start_frames, end_frames):
        """Apply the duration / proximity exclusion filter (frames; 0 = rule off).

        Rules (only when ``bout_exclude_enabled``):
          * duration: drop bouts whose (end - start) is < min or > max (needs end).
          * proximity: drop a bout that begins fewer than ``min_gap`` frames after
            the previous *kept* bout's end (or its start, for start-only files —
            i.e. a minimum time between bout starts).

        Returns (start_kept, end_kept_or_None, n_excluded).  Inputs/outputs are
        sorted by start frame.
        """
        start = np.asarray(start_frames)
        end = None if end_frames is None else np.asarray(end_frames, dtype=float)
        n0 = len(start)
        if not self.params.get('bout_exclude_enabled', False) or n0 == 0:
            return start, end, 0

        # Sort by start frame, keeping start/end paired
        order = np.argsort(start, kind='stable')
        start = start[order]
        if end is not None:
            end = end[order]

        keep = np.ones(n0, dtype=bool)
        min_dur = int(self.params.get('bout_exclude_min_duration', 0) or 0)
        max_dur = int(self.params.get('bout_exclude_max_duration', 0) or 0)
        min_gap = int(self.params.get('bout_exclude_min_gap', 0) or 0)

        # Duration rules (require end frames; NaN ends are left untouched)
        if end is not None and (min_dur > 0 or max_dur > 0):
            dur = end - start
            valid = ~np.isnan(dur)
            if min_dur > 0:
                keep &= ~(valid & (dur < min_dur))
            if max_dur > 0:
                keep &= ~(valid & (dur > max_dur))

        # Proximity rule (sequential over kept bouts)
        if min_gap > 0:
            last_ref = None
            for i in range(n0):
                if not keep[i]:
                    continue
                if last_ref is None:
                    last_ref = self._bout_ref_end(start[i], end, i)
                    continue
                if (start[i] - last_ref) < min_gap:
                    keep[i] = False  # too close; drop and keep previous reference
                else:
                    last_ref = self._bout_ref_end(start[i], end, i)

        start_k = start[keep]
        end_k = None if end is None else end[keep]
        return start_k, end_k, int(n0 - int(keep.sum()))

    @staticmethod
    def _bout_ref_end(start_val, end_array, i):
        """Reference frame for proximity gaps: the bout's end, or its start when no
        end is available/scored."""
        if end_array is None:
            return start_val
        e = end_array[i]
        if e is None or (isinstance(e, float) and np.isnan(e)):
            return start_val
        return e

    def _bout_channel_column(self, data, channel):
        """Map a channel label ('G0'/'G1'/'Ch0'/...) to its beh_synced column index."""
        beh = data.get('beh_synced')
        if beh is None:
            return None
        stored_nch = data.get('num_photometry_channels')
        if stored_nch and stored_nch > 0:
            phot_cols = list(range(6, 6 + stored_nch))
        else:
            guess = beh.shape[1] - 6 - len(self.BEH_KIN_FIELDS)
            phot_cols = list(range(6, 6 + guess)) if guess > 0 else (
                list(range(6, beh.shape[1])) if beh.shape[1] > 6 else [])
        if not phot_cols:
            return None
        # Prefer the subject's actual channel designation (e.g. a subject whose
        # single channel is 'G1' maps to the first photometry column, not the 2nd).
        names = data.get('channel_names')
        if isinstance(names, list) and channel in names:
            idx = names.index(channel)
        else:
            idx = 0
            digits = ''.join(ch for ch in str(channel) if ch.isdigit())
            if digits:
                idx = int(digits)
        if idx >= len(phot_cols):
            return None
        return phot_cols[idx]

    def _original_bout_index(self, entry, channel, bout_idx, n_frames):
        """Map a *channel trace-list* index back to its row in onset_frames.

        A bout is rejected per channel (all-NaN, or `_is_valid_bout` failing),
        so a channel's trace list can be shorter than -- and no longer parallel
        to -- onset_frames/end_frames, and the two can differ between channels
        of the same subject. Extraction records the surviving bout numbers in
        ``_kept_indices``; this resolves through them.

        Returns ``None`` when the mapping cannot be trusted, so the caller falls
        back to the onset-aligned slice rather than reading some other bout's
        window. That includes bout stores extracted before ``_kept_indices``
        existed *and* showing a length mismatch: the skew is detectable but not
        recoverable, and those projects need a re-extract to use whole/offset
        styles safely.
        """
        if bout_idx is None or bout_idx < 0:
            return None
        kept = entry.get('_kept_indices') if isinstance(entry, dict) else None
        seq = kept.get(str(channel)) if isinstance(kept, dict) else None
        if seq is not None:
            if not (0 <= bout_idx < len(seq)):
                return None
            idx = int(seq[bout_idx])
            return idx if 0 <= idx < n_frames else None

        # Legacy store: direct indexing is sound only if nothing was dropped.
        traces = entry.get(str(channel)) if isinstance(entry, dict) else None
        if isinstance(traces, list) and len(traces) != n_frames:
            return None
        return bout_idx if bout_idx < n_frames else None

    def _bout_analysis_segment(self, subject, behavior, channel, bout_idx, stored_bout,
                               window_start_frame, window_end_frame):
        """Return the 1-D signal array to compute a bout metric over, honoring the
        current start/end processing style.

          'onset'  : slice the stored onset-aligned segment [onset+ws : onset+we]
                     (legacy behavior; always used when no end frames exist).
          'whole'  : the full bout (start -> end), pulled from beh_synced.
          'offset' : window relative to the bout END, pulled from beh_synced.

        Falls back to the 'onset' slice whenever end-frame data is unavailable or
        cannot be aligned to this bout.  Returns ``None`` for an empty window.
        """
        prebout = self.params.get('preboutframes', 90)
        onset_idx = prebout

        # Realign the stored onset-aligned trace onto the current window so the
        # onset index above is valid even when this bout was extracted with a
        # different pre/post (identity when the windows already match).
        _entry = self.processed_data.get(subject, {}).get('bouts', {}).get(behavior, {})
        onset_bout = self._realign_bout_trace(stored_bout, self._entry_prebout(_entry))

        def _onset_slice():
            a = max(0, onset_idx + window_start_frame)
            b = min(len(onset_bout), onset_idx + window_end_frame)
            if b <= a:
                return None
            return onset_bout[a:b]

        if hasattr(self, 'boutframe_processing_style_var'):
            style = self.boutframe_processing_style_var.get()
        else:
            style = self.params.get('boutframe_processing_style', 'onset')
        if style not in ('whole', 'offset'):
            return _onset_slice()

        data = self.processed_data.get(subject, {})
        bouts_beh = data.get('bouts', {}).get(behavior, {})
        starts = bouts_beh.get('onset_frames')
        ends = bouts_beh.get('end_frames')
        beh_synced = data.get('beh_synced')
        if (ends is None or starts is None or beh_synced is None
                or len(starts) != len(ends)):
            return _onset_slice()
        # bout_idx indexes the CHANNEL'S trace list, which skips bouts rejected
        # as all-NaN or invalid; onset_frames/end_frames keep every bout. Map
        # across before indexing, or every bout after the first rejection is
        # measured over its neighbour's window.
        frame_idx = self._original_bout_index(bouts_beh, channel, bout_idx,
                                              len(starts))
        if frame_idx is None:
            return _onset_slice()
        start_f = starts[frame_idx]
        end_f = ends[frame_idx]
        if end_f is None or (isinstance(end_f, float) and np.isnan(end_f)):
            return _onset_slice()

        col = self._bout_channel_column(data, channel)
        if col is None:
            return _onset_slice()

        start_f = int(round(start_f))
        end_f = int(round(end_f))
        if style == 'whole':
            a, b = start_f, end_f
        else:  # offset
            a = end_f + window_start_frame
            b = end_f + window_end_frame
        a = max(0, a)
        b = min(beh_synced.shape[0], b)
        if b <= a:
            return None
        seg = np.asarray(beh_synced[a:b, col], dtype=float)
        if seg.size == 0 or np.all(np.isnan(seg)):
            return None

        # Baseline-correct against the pre-bout window before the START frame so
        # metrics stay referenced to the same baseline regardless of style.
        if self.params.get('baseline_correct_bouts', False):
            bf = int(self.params.get('baseline_frames', 45))
            bstart = max(0, start_f - bf)
            if bstart < start_f:
                base = np.asarray(beh_synced[bstart:start_f, col], dtype=float)
                base = base[~np.isnan(base)]
                if base.size:
                    seg = seg - np.mean(base)
        return seg

    def extract_bouts(self, subject_id, beh_synced, boutframes_file):
        """Extract bout-aligned data"""
        try:
            # Load boutframes for this recording (session-filtered when the
            # workbook keys sheets by animal -- see resolve_boutframes_sheet).
            df = self.read_boutframes_sheet(boutframes_file, subject_id)
            
            bout_data = {}
            prebout = self.params['preboutframes']
            postbout = self.params['postboutframes']
            exclude_before = self.params['exclude_frames_before']
            baseline_correct = self.params['baseline_correct_bouts']
            baseline_frames = self.params['baseline_frames']

            # ── Boutframes FPS scaling ──
            # If the checkbox is enabled, re-map all boutframe numbers from the
            # source video frame rate to the photometry sampling rate so that
            # the extracted windows align correctly.
            _scale_factor = 1.0
            if self.params.get('auto_scale_boutframes', False):
                _video_fps = float(self.params.get('boutframes_video_fps', 30))
                _photo_fps = getattr(self, 'detected_photometry_fps', None)
                # Allow per-subject override stored during processing
                _photo_fps = self.processed_data.get(subject_id, {}).get('photometry_fps', _photo_fps)
                if _photo_fps is not None and _video_fps > 0 and abs(_photo_fps - _video_fps) > 0.1:
                    _scale_factor = _photo_fps / _video_fps
                    self.log_message(
                        f"    Boutframe scaling: {_video_fps} fps (video) → "
                        f"{_photo_fps:.3f} Hz (photometry) | factor={_scale_factor:.4f}")
            
            # Photometry channels occupy cols 6 .. 6+N-1; the kinematics block
            # (elapsed/velocity/distance/center) follows AFTER them. Use the stored
            # channel count so kinematics columns are never mistaken for channels.
            subject_data = self.processed_data.get(subject_id, {})
            stored_nch = subject_data.get('num_photometry_channels')
            if stored_nch is not None and stored_nch > 0:
                phot_cols = list(range(6, 6 + stored_nch))
            else:
                # Fallback: derive count by removing the trailing kinematics block.
                guess = beh_synced.shape[1] - 6 - len(self.BEH_KIN_FIELDS)
                phot_cols = list(range(6, 6 + guess)) if guess > 0 else (
                    list(range(6, beh_synced.shape[1])) if beh_synced.shape[1] > 6 else [])
            num_channels = len(phot_cols)

            
            # Parse the sheet into behaviors.  Supports legacy start-only columns
            # and the start/end format (paired 'Behavior__start' / 'Behavior__end').
            behaviors, _has_end = self._parse_boutframes_dataframe(df)

            # Process each behavior
            for behavior, raw_start, raw_end in behaviors:
                if len(raw_start) == 0:
                    continue

                # Apply scaling / manual shift / per-subject shift / precut correction.
                # Start frames index the signal (int); end frames keep float so a
                # missing per-bout end stays NaN.
                frames = self._transform_boutframe_values(raw_start, subject_id, as_int=True)
                end_frames = None
                if raw_end is not None:
                    end_frames = self._transform_boutframe_values(raw_end, subject_id, as_int=False)

                # Log precut correction once per behavior (transform already applied it)
                if self.params.get('precut_correct_boutframes', True):
                    _precut = int(self.params.get('precut', 0))
                    _n_led = int(subject_data.get('n_led_states', 1))
                    _precut_offset = _precut // max(1, _n_led)
                    if _precut_offset > 0:
                        self.log_message(
                            f"    Precut boutframe correction: -{_precut_offset} frames "
                            f"(precut={_precut} raw rows \u00f7 {_n_led} LED states) for {behavior}")

                # Filter frames based on exclude_frames_before (keep start/end paired)
                _keep = frames >= exclude_before
                frames = frames[_keep]
                if end_frames is not None:
                    end_frames = end_frames[_keep]

                # Apply duration / proximity exclusion filter (non-destructive)
                frames, end_frames, _n_excl = self._apply_bout_exclusions(frames, end_frames)
                if _n_excl > 0:
                    self.log_message(
                        f"    Bout exclusion filter removed {_n_excl} bout(s) for {behavior}")

                # Prepare per-channel containers
                behavior_bouts = {f'Ch{ch}': [] for ch in range(num_channels)}
                # A bout can be rejected on one channel and kept on another, so a
                # channel's trace list is NOT parallel to `frames`. Record which
                # original bout each kept trace came from, or every consumer that
                # pairs a trace with onset_frames[i]/end_frames[i] silently reads
                # the wrong bout's window from the first rejection onwards.
                behavior_kept = {f'Ch{ch}': [] for ch in range(num_channels)}

                # Visualization/extraction is always aligned to the bout START frame.
                for bout_i, frame in enumerate(frames):
                    start_idx = max(0, frame - prebout)
                    end_idx = min(len(beh_synced), frame + postbout)

                    # Extract bout data for each photometry column detected
                    for ch, col_idx in enumerate(phot_cols):
                        bout_ch = beh_synced[start_idx:end_idx, col_idx]
                        if not np.all(np.isnan(bout_ch)):
                            # Apply baseline correction if enabled
                            if baseline_correct:
                                bout_ch = self.apply_baseline_correction(bout_ch, frame, start_idx, prebout, baseline_frames)

                            # Validate bout quality
                            if self._is_valid_bout(bout_ch):
                                behavior_bouts[f'Ch{ch}'].append(bout_ch)
                                behavior_kept[f'Ch{ch}'].append(bout_i)
                            else:
                                self.log_message(f"    Warning: Skipping invalid bout at frame {frame} for {behavior} (constant or zero variance) on Ch{ch}")

                # Store each channel under both its positional Ch{n} key (used by
                # index-based consumers like visualization) and its real designation
                # (G0/G1/R4/…) so name-based consumers work for any channel count.
                behavior_entry = {}
                kept_indices = {}
                for ch in range(num_channels):
                    behavior_entry[f'Ch{ch}'] = behavior_bouts.get(f'Ch{ch}', [])
                    kept_indices[f'Ch{ch}'] = behavior_kept.get(f'Ch{ch}', [])
                for ch in range(num_channels):
                    real = self.get_channel_name(subject_data, ch)
                    if real not in behavior_entry:
                        behavior_entry[real] = behavior_entry[f'Ch{ch}']
                        kept_indices[real] = kept_indices[f'Ch{ch}']
                # Keep explicit G0/G1 aliases for backward compatibility.
                if num_channels >= 1:
                    behavior_entry.setdefault('G0', behavior_entry.get('Ch0', []))
                    kept_indices.setdefault('G0', kept_indices.get('Ch0', []))
                if num_channels >= 2:
                    behavior_entry.setdefault('G1', behavior_entry.get('Ch1', []))
                    kept_indices.setdefault('G1', kept_indices.get('Ch1', []))
                # Keyed the same way as the trace lists, so a consumer holding a
                # channel key can map its trace index back to the original bout.
                # Underscore-prefixed because it is metadata, not signal:
                # _rescale_bout_store recurses into plain dict values and would
                # otherwise multiply these indices by the z-score scale factor.
                behavior_entry['_kept_indices'] = kept_indices

                # Store onset (start) frames so other analyses can use them without
                # re-reading the boutframes Excel file.  Also store end frames and
                # durations when available (start/end format) for the whole-bout
                # and offset-aligned processing styles.
                behavior_entry['onset_frames'] = frames.tolist()
                if end_frames is not None:
                    behavior_entry['end_frames'] = end_frames.tolist()
                    behavior_entry['durations'] = (end_frames - frames.astype(float)).tolist()
                else:
                    behavior_entry['end_frames'] = None
                    behavior_entry['durations'] = None

                # Record the pre/post window these traces were extracted with so
                # visualization can re-align them onto the *current* window even
                # when the user later changes preboutframes/postboutframes (or
                # only some subjects were reprocessed).  Without this, the stored
                # arrays carry no record of where their onset sits and plots
                # silently assume the live param applies to every subject.
                behavior_entry['_prebout'] = int(prebout)
                behavior_entry['_postbout'] = int(postbout)

                bout_data[behavior] = behavior_entry

            # Generate offset-derived behaviors if any offsets are defined.
            # Each offset creates a copy of every original behavior with shifted onsets.
            if self.bout_offsets:
                original_behaviors = list(bout_data.keys())
                for offset_def in self.bout_offsets:
                    offset_val = offset_def['offset_frames']
                    suffix = offset_def['label']
                    for src_behavior in original_behaviors:
                        src_entry = bout_data[src_behavior]
                        src_frames = np.array(src_entry.get('onset_frames', []))
                        if len(src_frames) == 0:
                            continue
                        src_ends = src_entry.get('end_frames')
                        src_ends = (np.array(src_ends, dtype=float)
                                    if src_ends is not None else None)
                        shifted_all = src_frames + offset_val
                        # Filter: keep only frames within valid range (end frames paired)
                        _mask = ((shifted_all >= exclude_before) &
                                 (shifted_all >= 0) &
                                 (shifted_all < len(beh_synced)))
                        shifted_frames = shifted_all[_mask]
                        shifted_ends = ((src_ends + offset_val)[_mask]
                                        if src_ends is not None else None)
                        if len(shifted_frames) == 0:
                            continue
                        # Extract bouts for offset frames
                        offset_bouts = {f'Ch{ch}': [] for ch in range(num_channels)}
                        offset_kept = {f'Ch{ch}': [] for ch in range(num_channels)}
                        for bout_i, frame in enumerate(shifted_frames):
                            start_idx = max(0, frame - prebout)
                            end_idx = min(len(beh_synced), frame + postbout)
                            for ch, col_idx in enumerate(phot_cols):
                                bout_ch = beh_synced[start_idx:end_idx, col_idx]
                                if not np.all(np.isnan(bout_ch)):
                                    if baseline_correct:
                                        bout_ch = self.apply_baseline_correction(
                                            bout_ch, frame, start_idx, prebout, baseline_frames)
                                    if self._is_valid_bout(bout_ch):
                                        offset_bouts[f'Ch{ch}'].append(bout_ch)
                                        offset_kept[f'Ch{ch}'].append(bout_i)
                        offset_entry = {}
                        offset_indices = {}
                        for ch in range(num_channels):
                            offset_entry[f'Ch{ch}'] = offset_bouts.get(f'Ch{ch}', [])
                            offset_indices[f'Ch{ch}'] = offset_kept.get(f'Ch{ch}', [])
                        for ch in range(num_channels):
                            real = self.get_channel_name(subject_data, ch)
                            if real not in offset_entry:
                                offset_entry[real] = offset_entry[f'Ch{ch}']
                                offset_indices[real] = offset_indices[f'Ch{ch}']
                        if num_channels >= 1:
                            offset_entry.setdefault('G0', offset_entry.get('Ch0', []))
                            offset_indices.setdefault('G0', offset_indices.get('Ch0', []))
                        if num_channels >= 2:
                            offset_entry.setdefault('G1', offset_entry.get('Ch1', []))
                            offset_indices.setdefault('G1', offset_indices.get('Ch1', []))
                        # Same skew as the base extraction above -- see _kept_indices there.
                        offset_entry['_kept_indices'] = offset_indices
                        offset_entry['onset_frames'] = shifted_frames.tolist()
                        if shifted_ends is not None:
                            offset_entry['end_frames'] = shifted_ends.tolist()
                            offset_entry['durations'] = (
                                shifted_ends - shifted_frames.astype(float)).tolist()
                        else:
                            offset_entry['end_frames'] = None
                            offset_entry['durations'] = None
                        offset_entry['_prebout'] = int(prebout)
                        offset_entry['_postbout'] = int(postbout)
                        offset_name = f"{src_behavior}_{suffix}"
                        bout_data[offset_name] = offset_entry
                        self.log_message(
                            f"    Created offset behavior '{offset_name}' "
                            f"({len(shifted_frames)} bouts, offset {offset_val} frames)")
            
            return bout_data
            
        except Exception as e:
            self.log_message(f"    Warning: Could not extract bouts for {subject_id}: {str(e)}")
            return {}

    # ── Bout window normalization for visualization ──────────────────
    # Stored bouts carry the pre/post window they were extracted with
    # ('_prebout'/'_postbout', added by extract_bouts).  The plotters all assume
    # a single global window (onset at self.params['preboutframes'], total length
    # pre+post).  When the live params differ from a stored bout's window — the
    # user changed pre/post without re-extracting, or only some subjects were
    # reprocessed — that assumption silently misaligns traces and pulls in the
    # wrong samples.  These helpers re-position each stored trace so its onset
    # lands on the *current* window, padding with NaN where the stored window
    # doesn't reach and cropping where it overruns.

    def _entry_prebout(self, entry):
        """Prebout a bout entry was extracted with (falls back to current param)."""
        if isinstance(entry, dict):
            v = entry.get('_prebout')
            if v is not None:
                return int(v)
        return int(self.params.get('preboutframes', 90))

    def _realign_bout_trace(self, trace, src_prebout, dst_prebout=None, dst_total=None):
        """Reposition one trace so its onset (at src_prebout) sits at dst_prebout
        on an axis of length dst_total, NaN-padding/cropping as needed."""
        if dst_prebout is None:
            dst_prebout = int(self.params.get('preboutframes', 90))
        if dst_total is None:
            dst_total = dst_prebout + int(self.params.get('postboutframes', 90))
        tr = np.asarray(trace, dtype=float)
        out = np.full(dst_total, np.nan)
        shift = dst_prebout - int(src_prebout)  # source idx s -> dst idx s + shift
        dst_lo = max(0, shift)
        dst_hi = min(dst_total, shift + len(tr))
        if dst_hi > dst_lo:
            out[dst_lo:dst_hi] = tr[dst_lo - shift:dst_hi - shift]
        return out

    def _realign_bouts(self, traces, src_prebout):
        """Realign a list of stored traces onto the current window.  A no-op in
        the common case where the stored window already matches the live params
        (identity within floating tolerance), so it is safe to call everywhere."""
        if not traces:
            return []
        dst_prebout = int(self.params.get('preboutframes', 90))
        dst_total = dst_prebout + int(self.params.get('postboutframes', 90))
        # Fast path: window already matches what the plotters expect.
        if int(src_prebout) == dst_prebout and all(len(t) == dst_total for t in traces):
            return list(traces)
        return [self._realign_bout_trace(t, src_prebout, dst_prebout, dst_total)
                for t in traces]

    def _entry_channel_bouts(self, entry, channel_key, max_bouts=None):
        """Fetch a channel's bouts from a behavior entry, realigned to the current
        window.  Use this anywhere bouts are pulled for visualization so plots stay
        correct across mixed extraction windows.  Returns [] when absent/empty."""
        if not isinstance(entry, dict):
            return []
        bouts = entry.get(channel_key)
        if not bouts:
            return []
        if max_bouts is not None:
            bouts = bouts[:max_bouts]
        return self._realign_bouts(bouts, self._entry_prebout(entry))

    def _stored_bout_trace_length(self, data):
        """Length (in frames) of a subject's stored bout traces, or None.

        Returns the *maximum* trace length across the subject's behaviors/bouts.
        This is the raw extraction length before realignment, so it reflects the
        pre/post window the bouts were extracted with; the max (rather than the
        first trace) avoids being fooled by bouts clipped at the recording edge,
        which are shorter than the full window."""
        if not isinstance(data, dict):
            return None
        bouts = data.get('bouts')
        if not bouts:
            return None
        best = None
        for entry in bouts.values():
            if not isinstance(entry, dict):
                continue
            for ch in ('G0', 'G1'):
                for tr in entry.get(ch) or []:
                    try:
                        L = len(tr)
                    except TypeError:
                        continue
                    if best is None or L > best:
                        best = L
        return best

    def _warn_if_mixed_bout_windows(self, subjects):
        """Warn when the selected subjects' stored bouts span more than one
        extraction window, or were extracted with a window different from the
        current pre/post settings.

        Either case means the bout plots realign (NaN-pad / crop) some subjects
        onto the current axis, so they silently show truncated / blank regions —
        the classic "zero data" symptom of a partial reprocess.  Logged every
        time; the modal popup is shown only when the situation changes so it
        doesn't nag on every plot."""
        cur_total = (int(self.params.get('preboutframes', 90))
                     + int(self.params.get('postboutframes', 90)))
        lengths = {}  # trace length -> [subjects]
        for s in subjects:
            L = self._stored_bout_trace_length(self.processed_data.get(s, {}))
            if L is not None:
                lengths.setdefault(L, []).append(s)

        if not lengths:
            return  # no stored bouts to compare

        distinct = sorted(lengths)
        # Consistent iff a single window that matches the current settings.
        if len(distinct) == 1 and distinct[0] == cur_total:
            self._mixed_window_warn_sig = None
            return

        short = [s for L in distinct if L < cur_total for s in lengths[L]]
        lines = [f"{L} frames: {', '.join(lengths[L])}" for L in distinct]
        msg = (
            "The selected subjects' bouts were not all extracted with the "
            "current pre/post window (prebout + postbout = "
            f"{cur_total} frames).\n\n"
            "Windows found:\n  " + "\n  ".join(lines) + "\n\n"
            "Subjects with a shorter window appear truncated (blank) at the "
            "edges of the plot, and mixed windows can misalign the average. "
            "Set the desired pre/post window and click "
            "“⟲ Apply Settings & Re-extract Bouts”, then re-plot.")
        self.log_message("  Warning: mixed bout-extraction windows — " + "; ".join(lines))

        sig = tuple((L, tuple(sorted(lengths[L]))) for L in distinct) + (cur_total,)
        if getattr(self, '_mixed_window_warn_sig', None) != sig:
            self._mixed_window_warn_sig = sig
            messagebox.showwarning("Mixed Bout Windows", msg)

    def extract_entry_bouts(self, beh_synced, entry_frames_dict, num_photometry_channels=None, fps=None):
        """Extract photometry traces aligned to zone entries
        
        Similar to extract_bouts but triggered by zone entry events.
        Uses maze-specific entry keys (EPM/EPM_Complex or OFT).
        
        Uses the same entry detection logic as the behavior metrics to ensure consistent alignment.
        
        Args:
            beh_synced: Synchronized behavior array
            entry_frames_dict: Dictionary mapping entry_key -> list of frame indices
            num_photometry_channels: Explicit channel count (avoids counting non-photometry columns)
            
        Returns:
            Dictionary with zone-entry aligned photometry traces
        """
        entry_bout_data = {}
        prebout = self.params['preboutframes']
        postbout = self.params['postboutframes']
        baseline_correct = self.params['baseline_correct_bouts']
        baseline_frames = self.params['baseline_frames']
        fps = fps if fps is not None else self.get_fps()
        
        # Detect available photometry columns (columns 6+ contain per-channel z-scores).
        # Use stored channel count when available to avoid counting non-photometry columns.
        if num_photometry_channels is not None and num_photometry_channels > 0:
            phot_cols = list(range(6, 6 + num_photometry_channels))
        else:
            guess = beh_synced.shape[1] - 6 - len(self.BEH_KIN_FIELDS)
            phot_cols = list(range(6, 6 + guess)) if guess > 0 else (
                list(range(6, beh_synced.shape[1])) if beh_synced.shape[1] > 6 else [])
        num_channels = len(phot_cols)

        self.log_message(f"  Extracting entry bouts...")
        self.log_message(f"    Available channels: num_channels={num_channels}")
        
        # Use the same maze-specific entry keys detected by detect_zone_entries().
        zone_types = {}
        for _, (entry_key, display_key) in self._get_zone_entry_type_map().items():
            zone_types[entry_key] = (display_key, entry_frames_dict.get(entry_key, []))
        
        for entry_type, (display_name, detected_frames) in zone_types.items():
            entry_bout_data[entry_type] = {}
            zones_data = detected_frames
            
            self.log_message(f"    Found {len(zones_data)} {entry_type} entries (using consistent detection logic)")
            
            if len(zones_data) > 0:
                # Prepare per-channel lists
                zone_bouts = {f'Ch{ch}': [] for ch in range(num_channels)}
                
                for frame in zones_data:
                    # Check if we have enough data for full pre and post bout window
                    if frame - prebout < 0 or frame + postbout > len(beh_synced):
                        continue  # Skip this bout - not enough data at beginning or end
                    
                    start_idx = frame - prebout
                    end_idx = frame + postbout
                    
                    # Extract bout data for each photometry channel
                    for ch, col_idx in enumerate(phot_cols):
                        bout_ch = beh_synced[start_idx:end_idx, col_idx]
                        # Only keep bouts with complete data (no NaN values)
                        if not np.any(np.isnan(bout_ch)):
                            # Apply baseline correction if enabled
                            if baseline_correct:
                                bout_ch = self.apply_baseline_correction(bout_ch, frame, start_idx, prebout, baseline_frames)

                            # Validate bout quality
                            if self._is_valid_bout(bout_ch):
                                zone_bouts[f'Ch{ch}'].append(bout_ch)
                            else:
                                self.log_message(f"    Warning: Skipping invalid {entry_type} bout at frame {frame} for Ch{ch} (constant or zero variance)")
                
                # Pack per-channel results and provide backward-compatible keys.
                # Always expose both 'G0' and 'G1' (defaulting to []) so single-channel
                # subjects don't raise KeyError in the G0/G1-keyed plotting/consumer code.
                packed = {}
                for ch in range(num_channels):
                    packed[f'Ch{ch}'] = zone_bouts.get(f'Ch{ch}', [])
                packed['G0'] = packed.get('Ch0', [])
                packed['G1'] = packed.get('Ch1', [])
                packed['_prebout'] = int(prebout)
                packed['_postbout'] = int(postbout)

                entry_bout_data[entry_type][display_name] = packed
                # Count only the per-channel trace lists (Ch0..ChN); packed also
                # holds scalar window metadata (_prebout/_postbout) and the G0/G1
                # aliases of Ch0/Ch1, neither of which should be len()'d/summed.
                _n_extracted = sum(len(packed.get(f'Ch{ch}', []))
                                   for ch in range(num_channels))
                self.log_message(f"    Extracted {_n_extracted} total bouts for {entry_type}")
            else:
                self.log_message(f"    No {entry_type} entries to extract")
                entry_bout_data[entry_type][display_name] = {
                    'G0': [],
                    'G1': []
                }
        
        return entry_bout_data
    
    # ======================== Boutframes Editor ========================
    
    def update_bout_subjects(self):
        """Update subject list in boutframes editor. Returns True if populated."""
        boutframes_file = self.boutframes_path_var.get()
        if not (boutframes_file and os.path.exists(boutframes_file)):
            return False
        wb = load_workbook(boutframes_file, read_only=True)
        try:
            subjects = wb.sheetnames
        finally:
            wb.close()
        self.bout_subject_combo['values'] = subjects
        if subjects:
            self.bout_subject_combo.current(0)
            self.load_bout_subject()
            self._populate_preview_behavior_combo()
            self.refresh_scaled_preview()
            return True
        return False

    def reload_boutframes(self):
        """Reload boutframes from file (editor 'Reload from File' button)."""
        boutframes_file = self.boutframes_path_var.get()
        if not boutframes_file:
            messagebox.showwarning(
                "No Boutframes File",
                "No boutframes file is set.\n\nUse the 'Browse' button next to "
                "'Boutframes File' on the Processing tab to select one.")
            return
        if not os.path.exists(boutframes_file):
            messagebox.showerror(
                "File Not Found",
                f"The boutframes file could not be found:\n\n{boutframes_file}\n\n"
                "It may have moved or been renamed since the project was saved. "
                "Use 'Browse' to locate it again.")
            return
        try:
            populated = self.update_bout_subjects()
            self._populate_preview_behavior_combo()
            self.refresh_scaled_preview()
        except Exception as e:
            messagebox.showerror("Reload Error",
                                 f"Could not read the boutframes file:\n\n{e}")
            return
        if not populated:
            messagebox.showwarning(
                "No Sheets Found",
                "The boutframes file was opened but contains no worksheets.")
    
    def load_bout_subject(self, event=None):
        """Load boutframes for selected subject"""
        subject = self.bout_subject_var.get()
        boutframes_file = self.boutframes_path_var.get()
        
        if not subject or not boutframes_file or not os.path.exists(boutframes_file):
            return
        
        try:
            # Load data
            df = pd.read_excel(boutframes_file, sheet_name=subject)
            
            # Clear existing treeview
            for item in self.bout_tree.get_children():
                self.bout_tree.delete(item)
            
            # Configure columns
            columns = list(df.columns)
            self.bout_tree['columns'] = columns
            self.bout_tree.heading('#0', text='Row')
            
            for col in columns:
                self.bout_tree.heading(col, text=col)
                self.bout_tree.column(col, width=100)
            
            # Add data
            for idx, row in df.iterrows():
                values = [row[col] if pd.notna(row[col]) else '' for col in columns]
                self.bout_tree.insert('', 'end', text=str(idx), values=values)
            
            self.current_bout_df = df

            # Detect start/end format so the exclusion proximity-rule label can
            # adapt its wording ("after previous end" vs "between starts").
            _, self._boutframes_has_end = self._parse_boutframes_dataframe(df)
            if hasattr(self, '_excl_gap_label'):
                self._update_bout_exclusion_hints()

        except Exception as e:
            messagebox.showerror("Error", f"Failed to load boutframes:\n{str(e)}")
    
    def edit_bout_cell(self, event):
        """Edit a cell in the boutframes table"""
        item = self.bout_tree.selection()[0]
        column = self.bout_tree.identify_column(event.x)
        
        if column == '#0':  # Can't edit row numbers
            return
        
        # Get column index
        col_idx = int(column.replace('#', '')) - 1
        col_name = self.bout_tree['columns'][col_idx]
        
        # Get current value
        current_value = self.bout_tree.item(item)['values'][col_idx]
        
        # Create entry widget for editing
        x, y, width, height = self.bout_tree.bbox(item, column)
        
        edit_var = tk.StringVar(value=str(current_value) if current_value else '')
        edit_entry = ttk.Entry(self.bout_tree, textvariable=edit_var)
        edit_entry.place(x=x, y=y, width=width, height=height)
        edit_entry.focus()
        edit_entry.select_range(0, tk.END)
        
        def save_edit(event=None):
            new_value = edit_var.get()
            values = list(self.bout_tree.item(item)['values'])
            values[col_idx] = new_value
            self.bout_tree.item(item, values=values)
            edit_entry.destroy()
        
        def cancel_edit(event=None):
            edit_entry.destroy()
        
        edit_entry.bind('<Return>', save_edit)
        edit_entry.bind('<Escape>', cancel_edit)
        edit_entry.bind('<FocusOut>', save_edit)
    
    def save_boutframes(self):
        """Save modified boutframes to file"""
        subject = self.bout_subject_var.get()
        boutframes_file = self.boutframes_path_var.get()
        
        if not subject or not boutframes_file:
            messagebox.showerror("Error", "No boutframes file loaded")
            return
        
        try:
            # Extract data from treeview
            data = []
            for item in self.bout_tree.get_children():
                values = self.bout_tree.item(item)['values']
                data.append([v if v != '' else np.nan for v in values])
            
            columns = self.bout_tree['columns']
            df = pd.DataFrame(data, columns=columns)
            
            # Load workbook and update sheet
            if os.path.exists(boutframes_file):
                wb = load_workbook(boutframes_file)
                if subject in wb.sheetnames:
                    del wb[subject]
            else:
                wb = Workbook()
                if 'Sheet' in wb.sheetnames:
                    del wb['Sheet']
            
            ws = wb.create_sheet(subject)
            
            # Write headers
            for col_idx, col_name in enumerate(df.columns, 1):
                ws.cell(1, col_idx, col_name)
            
            # Write data
            for row_idx, row in enumerate(df.values, 2):
                for col_idx, value in enumerate(row, 1):
                    if pd.notna(value):
                        ws.cell(row_idx, col_idx, value)
            
            wb.save(boutframes_file)
            
        except Exception as e:
            messagebox.showerror("Error", f"Failed to save boutframes:\n{str(e)}")
    
    def add_behavior_column(self):
        """Add a new behavior column"""
        behavior_name = tk.simpledialog.askstring("New Behavior", "Enter behavior name:")
        if behavior_name:
            # Add column to treeview
            current_columns = list(self.bout_tree['columns'])
            current_columns.append(behavior_name)
            self.bout_tree['columns'] = current_columns
            self.bout_tree.heading(behavior_name, text=behavior_name)
            self.bout_tree.column(behavior_name, width=100)
            
            # Update all rows with empty value
            for item in self.bout_tree.get_children():
                values = list(self.bout_tree.item(item)['values'])
                values.append('')
                self.bout_tree.item(item, values=values)

    # ── Random-shuffle (null / control) behavior generator ───────────

    def open_random_shuffle_dialog(self):
        """Dialog to generate a set of pseudo-random, non-overlapping bouts for
        every processed subject — a control/"null" behavior for the FLMM analysis.

        Bouts are placed in photometry-frame space (where the extraction window
        lives), kept clear of the session edges by the pre/post window, spread
        across the whole session, and written back as raw frames into the
        boutframes file(s) with a ``.bak`` backup.
        """
        bf = self.boutframes_path_var.get()
        if not bf or not os.path.exists(bf):
            messagebox.showwarning(
                "No Boutframes File",
                "No boutframes file is loaded.\n\nSet one on the Processing tab, "
                "then reload it here before generating random bouts.")
            return

        subjects = [sid for sid, d in self.processed_data.items()
                    if isinstance(d, dict) and d.get('beh_synced') is not None]
        if not subjects:
            messagebox.showwarning(
                "No Signal Data",
                "Random shuffle needs each subject's synchronized signal so it "
                "knows the session length.\n\nRun the analysis (or click "
                "'Apply Settings & Re-extract Bouts') first, then try again.")
            return

        # Pre-scan the file for the start/end format and a sensible default
        # duration (median of the real scored bouts, in raw frames).
        has_end = False
        durations = []
        for sid in subjects:
            try:
                df = self.read_boutframes_sheet(bf, sid)
            except Exception:
                continue
            behs, he = self._parse_boutframes_dataframe(df)
            has_end = has_end or he
            for _name, s, e in behs:
                if e is not None and len(e):
                    d = np.asarray(e, float) - np.asarray(s, float)
                    d = d[np.isfinite(d) & (d > 0)]
                    if d.size:
                        durations.append(d)

        prebout = int(self.params.get('preboutframes', 150))
        postbout = int(self.params.get('postboutframes', 150))
        min_gap = int(self.params.get('bout_exclude_min_gap', 0) or 0)
        min_dur = int(self.params.get('bout_exclude_min_duration', 0) or 0)

        # Default duration RANGE from the real scored bouts (p10–p90 of the
        # empirical distribution), so generated control bouts have a realistic
        # spread of lengths rather than all being identical.  Clamped to the
        # exclusion minimum so they survive extraction.
        if durations:
            all_dur = np.concatenate(durations)
            dur_lo_def = int(round(float(np.percentile(all_dur, 10))))
            dur_hi_def = int(round(float(np.percentile(all_dur, 90))))
            med_dur = int(round(float(np.median(all_dur))))
        else:
            dur_lo_def = dur_hi_def = med_dur = prebout
        dur_lo_def = max(dur_lo_def, min_dur, 1)
        dur_hi_def = max(dur_hi_def, dur_lo_def)

        # ── Build the dialog ─────────────────────────────────────────────
        dlg = tk.Toplevel(self.root)
        dlg.title("Generate Random Bouts")
        dlg.transient(self.root)
        dlg.grab_set()
        dlg.resizable(False, False)

        intro = ("Generates non-overlapping, session-spanning random bouts for all "
                 f"{len(subjects)} processed subject(s) — a control 'null' behavior "
                 "for the FLMM comparison.  Bouts are kept clear of the session edges "
                 "by the pre/post window.")
        ttk.Label(dlg, text=intro, wraplength=self.ui_px(420), justify='left',
                  foreground='gray').pack(anchor='w', padx=14, pady=(12, 6))

        form = ttk.Frame(dlg)
        form.pack(fill='x', padx=14, pady=2)

        n_var = tk.StringVar(value="30")
        name_var = tk.StringVar(value="Random")
        durmin_var = tk.StringVar(value=str(dur_lo_def))
        durmax_var = tk.StringVar(value=str(dur_hi_def))
        spacing_var = tk.StringVar(value=str(prebout + postbout))
        margin_var = tk.StringVar(value="0")
        seed_var = tk.StringVar(value="0")
        reextract_var = tk.BooleanVar(value=True)

        def _row(r, label, var, hint):
            ttk.Label(form, text=label).grid(row=r, column=0, sticky='w', padx=(0, 8), pady=3)
            ttk.Entry(form, textvariable=var, width=12).grid(row=r, column=1, sticky='w', pady=3)
            ttk.Label(form, text=hint, foreground='gray',
                      font=('Segoe UI', 8)).grid(row=r, column=2, sticky='w', padx=(8, 0))

        _row(0, "Bouts per subject:", n_var, "count (capped to what fits)")
        _row(1, "Behavior name:", name_var, "new column name")
        r = 2
        if has_end:
            # Duration range: each bout gets a random length in [min, max] so the
            # control behavior spans a realistic spread rather than a fixed length.
            drow = ttk.Frame(form)
            drow.grid(row=r, column=0, columnspan=3, sticky='w', pady=3)
            ttk.Label(drow, text="Duration range:").pack(side='left', padx=(0, 8))
            ttk.Entry(drow, textvariable=durmin_var, width=8).pack(side='left')
            ttk.Label(drow, text="to").pack(side='left', padx=6)
            ttk.Entry(drow, textvariable=durmax_var, width=8).pack(side='left')
            ttk.Label(drow, text=f"frames  (real p10–p90 = {dur_lo_def}–{dur_hi_def}, "
                                 f"median {med_dur})",
                      foreground='gray', font=('Segoe UI', 8)).pack(side='left', padx=(8, 0))
            r += 1
        _row(r, "Min spacing:", spacing_var, "frames between bout starts"); r += 1
        _row(r, "Edge margin:", margin_var, "extra frames from session ends"); r += 1
        _row(r, "Random seed:", seed_var, "same seed → same bouts"); r += 1

        ttk.Checkbutton(form, text="Re-extract bouts after generating",
                        variable=reextract_var).grid(row=r, column=0, columnspan=3,
                                                      sticky='w', pady=(6, 0))

        note = ("The behavior is written to the boutframes file (a .bak backup is "
                "made first). Existing columns with this name are replaced.")
        ttk.Label(dlg, text=note, wraplength=self.ui_px(420), justify='left',
                  foreground='gray', font=('Segoe UI', 8)).pack(anchor='w', padx=14, pady=(8, 4))

        btn_row = ttk.Frame(dlg)
        btn_row.pack(fill='x', padx=14, pady=(4, 12))

        def _on_generate():
            try:
                n = int(float(n_var.get()))
                name = name_var.get().strip()
                dur_min = int(float(durmin_var.get())) if has_end else 0
                dur_max = int(float(durmax_var.get())) if has_end else 0
                user_spacing = int(float(spacing_var.get()))
                margin = int(float(margin_var.get()))
                seed = int(float(seed_var.get()))
            except ValueError:
                messagebox.showerror("Invalid Input",
                                     "Counts, duration, spacing, margin and seed "
                                     "must be numbers.", parent=dlg)
                return
            if n < 1:
                messagebox.showerror("Invalid Input", "Need at least 1 bout.", parent=dlg)
                return
            if not name:
                messagebox.showerror("Invalid Input", "Enter a behavior name.", parent=dlg)
                return
            if has_end:
                if dur_min <= 0 or dur_max <= 0:
                    messagebox.showerror("Invalid Input", "Durations must be > 0.", parent=dlg)
                    return
                if dur_max < dur_min:
                    messagebox.showerror("Invalid Input",
                                         "Duration max must be ≥ min.", parent=dlg)
                    return
                if min_dur and dur_min < min_dur:
                    if not messagebox.askyesno(
                            "Short Duration",
                            f"Minimum duration {dur_min} is below the exclusion "
                            f"minimum ({min_dur} frames), so the shortest bouts "
                            "would be dropped on extraction.\n\nGenerate anyway?",
                            parent=dlg):
                        return
            dlg.destroy()
            self._generate_random_bouts(
                subjects, name, n, dur_min, dur_max, user_spacing, margin, seed,
                has_end, prebout, postbout, min_gap, reextract_var.get())

        ttk.Button(btn_row, text="Generate", command=_on_generate).pack(side='right')
        ttk.Button(btn_row, text="Cancel", command=dlg.destroy).pack(side='right', padx=(0, 8))

        dlg.update_idletasks()
        # Centre over the main window
        try:
            x = self.root.winfo_rootx() + (self.root.winfo_width() - dlg.winfo_width()) // 2
            y = self.root.winfo_rooty() + (self.root.winfo_height() - dlg.winfo_height()) // 3
            dlg.geometry(f"+{max(0, x)}+{max(0, y)}")
        except Exception:
            pass

    def _generate_random_bouts(self, subjects, name, n_req, dur_min, dur_max,
                               user_spacing, margin, seed, has_end, prebout,
                               postbout, min_gap, reextract):
        """Do the actual generation + write for :meth:`open_random_shuffle_dialog`.

        Each bout is given a random length in ``[dur_min, dur_max]`` (end-format
        only).  Spacing and the edge margin are computed from ``dur_max`` — the
        longest a bout can be — so the non-overlap, exclusion-survival, and
        no-truncation guarantees hold no matter which length each bout draws.
        """
        import shutil

        rng = np.random.default_rng(seed)

        # Spacing that both spans the session and survives the exclusion filter:
        # the next start must clear the previous bout's (longest possible) end by
        # min_gap.  Using dur_max keeps every consecutive pair safe.
        req_spacing = (dur_max + min_gap) if has_end else min_gap
        min_spacing = max(1, int(user_spacing), int(req_spacing))
        edge = max(postbout, dur_max)  # trailing space a start needs

        # Feasible count per subject, then a common N so the design is balanced.
        feasible = {}
        for sid in subjects:
            sess_len = int(self.processed_data[sid]['beh_synced'].shape[0])
            lo = prebout + margin
            hi = sess_len - edge - margin
            feasible[sid] = self._feasible_bout_count(hi - lo, min_spacing)

        n_feasible = min(feasible.values()) if feasible else 0
        if n_feasible < 1:
            worst = min(feasible, key=feasible.get)
            messagebox.showerror(
                "Session Too Short",
                "No random bouts fit given the current window/spacing settings "
                f"(subject '{worst}' has no room).\n\nReduce the min spacing, "
                "max duration, or edge margin and try again.")
            return
        n_final = min(int(n_req), n_feasible)

        # ── Generate raw start/end frames per subject ────────────────────
        per_subject = {}
        for sid in subjects:
            sess_len = int(self.processed_data[sid]['beh_synced'].shape[0])
            lo = prebout + margin
            hi = sess_len - edge - margin
            starts_ph = self._generate_jittered_starts(lo, hi, n_final, min_spacing, rng)
            starts_ph = np.sort(starts_ph)
            starts_raw = self._inverse_transform_boutframe_values(starts_ph, sid, as_int=True)
            ends_raw = None
            if has_end:
                # Random per-bout length in [dur_min, dur_max] (inclusive).
                if dur_max > dur_min:
                    durs = rng.integers(dur_min, dur_max + 1, size=len(starts_ph))
                else:
                    durs = np.full(len(starts_ph), dur_min)
                ends_raw = self._inverse_transform_boutframe_values(
                    starts_ph + durs, sid, as_int=True)
            per_subject[sid] = (starts_raw, ends_raw)

        # ── Group subjects by the boutframes file they extract from ──────
        global_bf = self.boutframes_path_var.get()

        def _resolve(sid):
            per = self.processed_data.get(sid, {}).get('boutframes_file')
            if per and os.path.exists(per):
                return per
            return global_bf

        files = {}
        for sid in subjects:
            files.setdefault(_resolve(sid), []).append(sid)

        # ── Confirm ──────────────────────────────────────────────────────
        cols = f"{name}__start / {name}__end" if has_end else name
        msg = (f"Write {n_final} random bout(s) per subject as '{cols}' to:\n\n" +
               "\n".join(f"  • {os.path.basename(f)}  ({len(s)} subj)"
                         for f, s in files.items()) +
               f"\n\nMin spacing: {min_spacing} frames" +
               (f"\nDuration: random {dur_min}–{dur_max} frames"
                if has_end and dur_max > dur_min
                else (f"\nDuration: {dur_min} frames" if has_end else "")) +
               "\n\nA .bak backup of each file is made first, and any existing "
               f"'{name}' column is replaced.")
        if n_final < n_req:
            msg += (f"\n\nNote: requested {n_req} but only {n_final} fit every "
                    "session at this spacing — using the common maximum.")
        if not messagebox.askyesno("Confirm Random Bouts", msg):
            return

        # ── Write ────────────────────────────────────────────────────────
        base_start = f"{name}__start"
        base_end = f"{name}__end"
        drop_names = {name.lower(), base_start.lower(), base_end.lower()}
        written = 0
        try:
            for path, sids in files.items():
                shutil.copy2(path, path + ".bak")
                wb = load_workbook(path)
                # Several recordings can share one worksheet (a per-animal
                # workbook), so update each sheet once with all of its sessions
                # -- writing them one at a time would replace the sheet and
                # discard the sibling sessions' bouts.
                by_sheet = {}
                for sid in sids:
                    sheet, session = self.resolve_boutframes_sheet(path, sid)
                    if sheet is None:
                        sheet, session = sid, ''
                    by_sheet.setdefault(sheet, []).append((sid, session))

                for sheet, members in by_sheet.items():
                    session_header, blocks = self._read_sheet_columns_by_session(
                        wb, sheet, drop_names)
                    for sid, session in members:
                        starts_raw, ends_raw = per_subject[sid]
                        block = blocks.setdefault(session, {})
                        block[base_start] = list(starts_raw)
                        if has_end:
                            block[base_end] = list(ends_raw)
                        written += 1
                    if session_header is None:
                        self._rewrite_sheet_columns(wb, sheet, blocks.get('', {}))
                    else:
                        self._rewrite_sheet_columns_by_session(
                            wb, sheet, session_header, blocks)
                wb.save(path)
        except Exception as exc:
            messagebox.showerror("Write Failed",
                                 f"Could not write random bouts:\n\n{exc}\n\n"
                                 "The .bak backup(s) are unchanged.")
            return

        self.log_message(
            f"Random shuffle: wrote {n_final} '{name}' bout(s) for {written} "
            f"subject(s) across {len(files)} file(s).")

        # ── Refresh editor + optional re-extract ─────────────────────────
        try:
            self.update_bout_subjects()
            self._on_bout_subject_selected()
        except Exception:
            pass

        if reextract:
            self._reextract_bouts_from_processed_data()
        else:
            messagebox.showinfo(
                "Random Bouts Generated",
                f"Wrote {n_final} '{name}' bout(s) for {written} subject(s).\n\n"
                "Click 'Apply Settings & Re-extract Bouts' to make them available "
                "to the analysis.")

    @staticmethod
    def _read_sheet_columns(wb, sheet, drop_names=None):
        """Read a worksheet into an ordered {header: [values]} dict, dropping any
        header whose lowercase name is in *drop_names*.  Ragged columns are kept
        as-is (blank cells become None)."""
        drop_names = drop_names or set()
        columns = {}
        if sheet not in wb.sheetnames:
            return columns
        ws = wb[sheet]
        rows = list(ws.iter_rows(values_only=True))
        if not rows:
            return columns
        headers = [("" if h is None else str(h)) for h in rows[0]]
        keep = [h for h in headers if h and h.lower() not in drop_names]
        idx = {h: i for i, h in enumerate(headers)}
        for h in keep:
            i = idx[h]
            col = [(r[i] if i < len(r) else None) for r in rows[1:]]
            # Trim trailing all-None padding
            while col and col[-1] is None:
                col.pop()
            columns[h] = col
        return columns

    def _read_sheet_columns_by_session(self, wb, sheet, drop_names=None):
        """Split a worksheet into one ``{header: [values]}`` dict per session.

        Returns ``(session_header, {session_label: columns})``.  ``session_header``
        is None for a sheet with no session column, in which case the single
        block is keyed ''.  This is the row-preserving counterpart of
        :meth:`_read_sheet_columns`: a per-animal sheet interleaves several
        recordings, so a writer has to keep the other sessions' rows intact.
        """
        drop_names = {str(d).lower() for d in (drop_names or set())}
        if sheet not in wb.sheetnames:
            return None, {}
        rows = list(wb[sheet].iter_rows(values_only=True))
        if not rows:
            return None, {}

        headers = [("" if h is None else str(h)) for h in rows[0]]
        session_idx = next((i for i, h in enumerate(headers)
                            if h.strip().lower() in self.BOUTFRAMES_SESSION_COLUMNS), None)
        if session_idx is None:
            return None, {'': self._read_sheet_columns(wb, sheet, drop_names)}

        session_header = headers[session_idx]
        keep = [(i, h) for i, h in enumerate(headers)
                if h and i != session_idx and h.lower() not in drop_names]

        blocks = {}
        for row in rows[1:]:
            raw = row[session_idx] if session_idx < len(row) else None
            label = '' if raw is None else str(raw).strip()
            block = blocks.setdefault(label, {h: [] for _i, h in keep})
            for i, h in keep:
                block[h].append(row[i] if i < len(row) else None)
        for block in blocks.values():
            for col in block.values():
                while col and col[-1] is None:
                    col.pop()
        return session_header, blocks

    def _rewrite_sheet_columns_by_session(self, wb, sheet, session_header, blocks):
        """Replace *sheet* with per-session blocks, session column first."""
        headers = []
        for block in blocks.values():
            for h in block:
                if h not in headers:
                    headers.append(h)

        if sheet in wb.sheetnames:
            del wb[sheet]
        ws = wb.create_sheet(sheet)
        ws.cell(1, 1, session_header)
        for ci, h in enumerate(headers, 2):
            ws.cell(1, ci, h)

        row_idx = 2
        for label, block in blocks.items():
            n = max((len(v) for v in block.values()), default=0)
            for r in range(n):
                ws.cell(row_idx, 1, label)
                for ci, h in enumerate(headers, 2):
                    values = block.get(h) or []
                    v = values[r] if r < len(values) else None
                    if v is None or (isinstance(v, float) and np.isnan(v)):
                        continue
                    ws.cell(row_idx, ci, v)
                row_idx += 1

    @staticmethod
    def _rewrite_sheet_columns(wb, sheet, columns):
        """Replace *sheet* with the ordered {header: [values]} *columns* dict.
        Columns may be ragged; NaN/None cells are left blank."""
        if sheet in wb.sheetnames:
            del wb[sheet]
        ws = wb.create_sheet(sheet)
        for ci, (header, values) in enumerate(columns.items(), 1):
            ws.cell(1, ci, header)
            for ri, v in enumerate(values, 2):
                if v is None:
                    continue
                if isinstance(v, float) and np.isnan(v):
                    continue
                ws.cell(ri, ci, v)

    def _on_bout_subject_selected(self, event=None):
        """Called when subject changes in the boutframes editor — refresh both subtabs."""
        self.load_bout_subject(event)
        self._populate_preview_behavior_combo()
        self.refresh_scaled_preview()

    # ── Re-extract bouts from stored processed data ──────────────────

    def _reextract_bouts_from_processed_data(self):
        """Re-run extract_bouts() for every subject using the FP signal already in
        processed_data.  This lets the user update boutframe settings (shifts, scaling,
        precut correction, pre/post windows, etc.) and immediately regenerate the
        bout-aligned traces without reprocessing the full photometry pipeline.
        """
        import threading

        if not self.processed_data:
            messagebox.showwarning(
                "No Processed Data",
                "No processed data found.\n\n"
                "Run the full analysis first so FP signals are loaded, "
                "then you can re-extract bouts with updated settings.")
            return

        global_bf = self.boutframes_path_var.get()

        def _resolve_boutframes(sid):
            """Boutframes file to re-extract this subject from: the one its bouts
            were originally extracted from (recorded during processing — this is
            the merged/TTL-derived file when a TTL source was used), falling back
            to the path configured in the UI."""
            per = self.processed_data.get(sid, {}).get('boutframes_file')
            if per and os.path.exists(per):
                return per
            if global_bf and os.path.exists(global_bf):
                return global_bf
            return None

        # Snapshot the current GUI state into self.params before extracting
        self.sync_ui_to_params()

        subjects_with_data = [
            sid for sid, data in self.processed_data.items()
            if isinstance(data, dict) and data.get('beh_synced') is not None
        ]

        if not subjects_with_data:
            messagebox.showwarning(
                "No Signal Data",
                "Processed data found but no synchronized signal matrices are stored.\n"
                "Please re-run the full analysis first.")
            return

        if not any(_resolve_boutframes(sid) for sid in subjects_with_data):
            messagebox.showwarning(
                "No Boutframes File",
                "No boutframes file is available to re-extract from.\n"
                "Load a boutframes file in the workspace settings, or re-run the "
                "full analysis so the TTL-derived boutframes file is regenerated.")
            return

        n_total = len(subjects_with_data)
        if hasattr(self, '_reextract_status_var'):
            self._reextract_status_var.set(f"Working\u2026 (0/{n_total})")
        self.root.update_idletasks()

        def _run():
            n_ok = 0
            n_fail = 0
            errors = []
            ok_subjects = []
            for i, sid in enumerate(subjects_with_data):
                self.root.after(0, lambda i=i: (
                    self._reextract_status_var.set(f"Working\u2026 ({i}/{n_total})")
                    if hasattr(self, '_reextract_status_var') else None
                ))
                try:
                    bf = _resolve_boutframes(sid)
                    if not bf:
                        raise FileNotFoundError(
                            "no boutframes file available for this subject")
                    beh_synced = self.processed_data[sid]['beh_synced']
                    bout_data = self.extract_bouts(sid, beh_synced, bf)
                    self.processed_data[sid]['bouts'] = bout_data
                    n_ok += 1
                    ok_subjects.append(sid)
                except Exception as exc:
                    n_fail += 1
                    errors.append(f"{sid}: {exc}")
                    self.log_message(f"  Re-extract error for {sid}: {exc}")

            def _finish():
                status = f"Bouts re-extracted for {n_ok}/{n_total} subjects."
                if n_fail:
                    status += f"  {n_fail} failed."
                self.log_message(status)

                # Persist the re-extracted bouts to disk (overwriting the old
                # window's CSVs + _bout_windows.json) so the new window survives a
                # reload instead of living only in memory.
                if ok_subjects and self.current_project:
                    try:
                        self.save_project(quiet=False, subjects=ok_subjects,
                                          show_completion=False)
                        self.log_message(
                            f"  Saved re-extracted bouts for {len(ok_subjects)} "
                            f"subject(s) to disk.")
                    except Exception as save_exc:
                        self.log_message(
                            f"  Warning: could not save re-extracted bouts: {save_exc}")

                # Refresh the behavior selectors on the other tabs so behaviors
                # added since the last selection (e.g. a random-shuffle control,
                # or any newly-scored column) become selectable immediately —
                # without the user having to reopen the project or re-pick a
                # subject.  These read live from processed_data but only rebuild
                # their value lists when explicitly refreshed.
                try:
                    if hasattr(self, 'bout_analysis_behavior_combo'):
                        self.update_bout_analysis_behaviors()
                    if hasattr(self, 'behavior_combo'):
                        self.update_behavior_list()
                except Exception as refresh_exc:
                    self.log_message(
                        f"  Note: could not refresh behavior lists: {refresh_exc}")

                if hasattr(self, '_reextract_status_var'):
                    self._reextract_status_var.set(status)
                if n_fail == 0:
                    messagebox.showinfo("Re-extract Complete", status)
                else:
                    messagebox.showwarning(
                        "Re-extract Partial",
                        status + "\n\nErrors:\n" + "\n".join(errors[:5]))

            self.root.after(0, _finish)

        threading.Thread(target=_run, daemon=True).start()

    # ── Per-subject boutframe shift helpers ──────────────────────────

    def _get_per_subject_shift(self, subject):
        """Return the per-subject boutframe shift for *subject* (0 if not configured)."""
        return int(self.per_subject_boutframe_shifts.get(str(subject), 0))

    def _refresh_per_subject_shifts_list(self):
        """Repopulate the Per-Subject Shifts treeview from self.per_subject_boutframe_shifts."""
        if not hasattr(self, 'per_subject_shifts_tree'):
            return
        self._close_shifts_inline_entry(save=False)
        for item in self.per_subject_shifts_tree.get_children():
            self.per_subject_shifts_tree.delete(item)
        for subj, shift in sorted(self.per_subject_boutframe_shifts.items()):
            self.per_subject_shifts_tree.insert('', 'end', values=(subj, f'{int(shift):+d}'))

    def _populate_per_subject_from_boutframes(self):
        """Add all subjects from the boutframes file (or processed data) with shift=0 if not already set."""
        # Shifts are per RECORDING, so the processed subjects are the right list
        # whenever there is one -- a per-animal boutframes workbook names its
        # sheets after animals, which would key the shifts one level too high.
        subjects = list(self.processed_data.keys())
        boutframes_file = self.boutframes_path_var.get()
        if not subjects and boutframes_file and os.path.exists(boutframes_file):
            try:
                wb = load_workbook(boutframes_file, read_only=True)
                subjects = wb.sheetnames
            except Exception:
                pass
        if not subjects:
            messagebox.showinfo("Per-Subject Shifts",
                                "No subjects found. Load a boutframes file or process subjects first.")
            return
        for s in subjects:
            if str(s) not in self.per_subject_boutframe_shifts:
                self.per_subject_boutframe_shifts[str(s)] = 0
        self._refresh_per_subject_shifts_list()

    # ── Inline cell editing ──────────────────────────────────────────

    def _on_shifts_cell_double_click(self, event):
        """Double-click the Shift column → open a small inline entry on that cell."""
        tree = self.per_subject_shifts_tree
        if tree.identify_region(event.x, event.y) != 'cell':
            return
        if tree.identify_column(event.x) != '#2':
            return
        item = tree.identify_row(event.y)
        if not item:
            return
        self._close_shifts_inline_entry(save=True)
        self._open_shifts_inline_entry(item)

    def _open_shifts_inline_entry(self, item):
        """Place an Entry widget over the Shift cell of *item*."""
        tree = self.per_subject_shifts_tree
        bbox = tree.bbox(item, '#2')
        if not bbox:
            return
        x, y, w, h = bbox
        subject = tree.item(item, 'values')[0]
        current = self.per_subject_boutframe_shifts.get(str(subject), 0)

        var = tk.StringVar(value=str(current))
        entry = tk.Entry(tree, textvariable=var, justify='center',
                         font=('Segoe UI', 9), relief='flat',
                         highlightthickness=1, highlightbackground='#0078d7')
        entry.place(x=x, y=y, width=w, height=h)
        entry.select_range(0, 'end')
        entry.focus_set()
        self._shifts_inline_entry = (entry, var, item)

        all_rows = tree.get_children()

        def _commit(advance=False):
            self._close_shifts_inline_entry(save=True)
            if advance:
                idx = list(all_rows).index(item) if item in all_rows else -1
                if 0 <= idx < len(all_rows) - 1:
                    nxt = all_rows[idx + 1]
                    tree.selection_set(nxt)
                    tree.see(nxt)
                    self._open_shifts_inline_entry(nxt)

        entry.bind('<Return>', lambda e: _commit(advance=False))
        entry.bind('<Tab>',    lambda e: (_commit(advance=True), 'break')[1])
        entry.bind('<Escape>', lambda e: self._close_shifts_inline_entry(save=False))

    def _close_shifts_inline_entry(self, save=True):
        """Destroy the active inline entry, optionally saving its value."""
        rec = getattr(self, '_shifts_inline_entry', None)
        if not rec:
            return
        entry, var, item = rec
        self._shifts_inline_entry = None
        if save and hasattr(self, 'per_subject_shifts_tree') \
                and self.per_subject_shifts_tree.exists(item):
            try:
                val = int(float(var.get()))
                subject = self.per_subject_shifts_tree.item(item, 'values')[0]
                self.per_subject_boutframe_shifts[str(subject)] = val
                self.per_subject_shifts_tree.item(item, values=(subject, f'{val:+d}'))
            except ValueError:
                pass
        try:
            entry.destroy()
        except Exception:
            pass

    def _paste_shifts_column_from_clipboard(self):
        """Read the clipboard and distribute one value per line to consecutive rows.

        Works with a single column copied from Excel (newline-separated values).
        If two columns are present (Subject\\tShift), the shift (second column) is used.
        Distribution starts from the currently selected row, or row 0 if none selected.
        """
        self._close_shifts_inline_entry(save=True)
        try:
            raw = self.root.clipboard_get()
        except Exception:
            messagebox.showwarning("Paste", "Clipboard is empty or unreadable.")
            return

        # Parse: one value per line; handle both single-column and two-column Excel copies
        values = []
        for line in raw.splitlines():
            line = line.strip()
            if not line:
                continue
            parts = line.split('\t')
            # Two columns: Subject[tab]Shift → take the shift (second column)
            # One column: just the shift value
            token = parts[1].strip() if len(parts) >= 2 else parts[0].strip()
            try:
                values.append(int(float(token)))
            except ValueError:
                values.append(None)   # placeholder to keep row alignment

        if not any(v is not None for v in values):
            messagebox.showwarning("Paste",
                                   "No numeric values found in clipboard.\n"
                                   "Copy a column of shift values from Excel and try again.")
            return

        tree = self.per_subject_shifts_tree
        all_rows = tree.get_children()
        if not all_rows:
            messagebox.showinfo("Paste", "No subjects in the list. Click 'Populate Subjects' first.")
            return

        sel = tree.selection()
        start_idx = list(all_rows).index(sel[0]) if sel else 0

        applied = 0
        for i, val in enumerate(values):
            row_idx = start_idx + i
            if row_idx >= len(all_rows):
                break
            if val is None:
                continue
            row_item = all_rows[row_idx]
            subject = tree.item(row_item, 'values')[0]
            self.per_subject_boutframe_shifts[str(subject)] = val
            tree.item(row_item, values=(subject, f'{val:+d}'))
            applied += 1

        # Select last written row so user can see where paste ended
        if applied:
            last = all_rows[min(start_idx + len(values) - 1, len(all_rows) - 1)]
            tree.selection_set(last)
            tree.see(last)
            tree.focus_set()

    def _copy_shifts_to_clipboard(self):
        """Copy current subject/shift table to clipboard as tab-separated text."""
        lines = '\n'.join(
            f'{subj}\t{int(shift)}'
            for subj, shift in sorted(self.per_subject_boutframe_shifts.items())
        )
        self.root.clipboard_clear()
        self.root.clipboard_append(lines)

    def _remove_per_subject_shift_entry(self):
        """Remove the selected subject from per_subject_boutframe_shifts."""
        if not hasattr(self, 'per_subject_shifts_tree'):
            return
        sel = self.per_subject_shifts_tree.selection()
        if not sel:
            return
        subject = self.per_subject_shifts_tree.item(sel[0], 'values')[0]
        self.per_subject_boutframe_shifts.pop(str(subject), None)
        self._refresh_per_subject_shifts_list()

    def _clear_per_subject_shifts(self):
        """Remove all per-subject shift entries."""
        if not messagebox.askyesno("Clear All", "Remove all per-subject boutframe shifts?"):
            return
        self.per_subject_boutframe_shifts.clear()
        self._refresh_per_subject_shifts_list()

    def _populate_preview_behavior_combo(self):
        """Fill the behavior dropdown in the Scaled Preview subtab."""
        if not hasattr(self, 'preview_behavior_combo'):
            return
        subject = self.bout_subject_var.get()
        boutframes_file = self.boutframes_path_var.get()
        if not subject or not boutframes_file or not os.path.exists(boutframes_file):
            self.preview_behavior_combo['values'] = []
            return
        try:
            df = pd.read_excel(boutframes_file, sheet_name=subject)
            behaviors = [str(c) for c in df.columns
                         if str(c).strip().lower() not in self.BOUTFRAMES_SESSION_COLUMNS]
            self.preview_behavior_combo['values'] = behaviors
            if behaviors:
                self.preview_behavior_combo.current(0)
        except Exception:
            self.preview_behavior_combo['values'] = []

    def refresh_scaled_preview(self):
        """Populate the Scaled Preview subtab for the selected subject/behavior."""
        if not hasattr(self, 'preview_tree'):
            return

        sheet = self.bout_subject_var.get()
        behavior = self.preview_behavior_var.get()
        boutframes_file = self.boutframes_path_var.get()

        # Clear existing rows
        for item in self.preview_tree.get_children():
            self.preview_tree.delete(item)

        if not sheet or not behavior or not boutframes_file or not os.path.exists(boutframes_file):
            self.preview_info_label.config(text="No data loaded.", foreground='gray')
            self._draw_scaled_preview_plot([], [], 0)
            return

        # The combo lists worksheets; the rate, shift and session length below
        # belong to the recording that sheet holds this behaviour for.
        subject = self.boutframes_recording_for_sheet(
            boutframes_file, sheet, behavior) or sheet

        # ── Compute scale factor ──────────────────────────────────────
        video_fps = float(self.params.get('boutframes_video_fps', 30))
        photo_fps = getattr(self, 'detected_photometry_fps', None)
        # Also look in processed_data in case it was saved there
        if photo_fps is None:
            for subj_data in self.processed_data.values():
                if 'photometry_fps' in subj_data:
                    photo_fps = subj_data['photometry_fps']
                    break
        photo_fps_subj = self.processed_data.get(subject, {}).get('photometry_fps', photo_fps)
        if photo_fps_subj is not None:
            photo_fps = photo_fps_subj

        scale_enabled = self.params.get('auto_scale_boutframes', False)
        if scale_enabled and photo_fps is not None and video_fps > 0 and abs(photo_fps - video_fps) > 0.1:
            scale_factor = photo_fps / video_fps
        else:
            scale_factor = 1.0

        # ── Load raw frames ───────────────────────────────────────────
        try:
            df = pd.read_excel(boutframes_file, sheet_name=sheet)
            df = self.filter_boutframes_rows(
                df, self.resolve_boutframes_sheet(boutframes_file, subject)[1])
            if behavior not in df.columns:
                self.preview_info_label.config(text=f"Behavior '{behavior}' not found.", foreground='red')
                return
            raw_frames = pd.to_numeric(df[behavior], errors='coerce').dropna().to_numpy(dtype=float)
        except Exception as e:
            self.preview_info_label.config(text=f"Error: {e}", foreground='red')
            return

        scaled_frames = np.round(raw_frames * scale_factor).astype(int) if scale_factor != 1.0 else raw_frames.astype(int)

        # Apply manual boutframe shift
        _manual_shift = int(self.params.get('boutframe_manual_shift', 0))
        if _manual_shift != 0:
            scaled_frames = scaled_frames + _manual_shift

        # Apply per-subject boutframe shift
        _per_subj_shift = self._get_per_subject_shift(subject)
        if _per_subj_shift != 0:
            scaled_frames = scaled_frames + _per_subj_shift

        # ── Populate table ────────────────────────────────────────────
        for raw, scaled in zip(raw_frames.astype(int), scaled_frames):
            self.preview_tree.insert('', 'end', values=(raw, scaled))

        # ── Session length for coverage calculation ───────────────────
        session_len = 0
        subj_data = self.processed_data.get(subject, {})
        beh_synced = subj_data.get('beh_synced')
        if beh_synced is not None:
            session_len = len(beh_synced)

        # ── Info label ────────────────────────────────────────────────
        if scale_factor != 1.0:
            info = (f"Scale factor: {scale_factor:.4f}  "
                    f"({video_fps:.1f} fps video → {photo_fps:.3f} Hz photometry)  |  "
                    f"{len(raw_frames)} bouts")
            info_color = 'green'
        else:
            reason = "scaling disabled" if not scale_enabled else f"fps equal ({video_fps:.1f})"
            info = f"No scaling applied ({reason})  |  {len(raw_frames)} bouts"
            info_color = 'gray'

        if subject != sheet:
            info = f"{subject}  |  " + info

        if _manual_shift != 0:
            info += f"  |  Manual shift: {_manual_shift:+d} frames"
            if info_color == 'gray':
                info_color = 'blue'

        if _per_subj_shift != 0:
            info += f"  |  Per-subject shift: {_per_subj_shift:+d} frames"
            if info_color == 'gray':
                info_color = 'blue'

        if session_len > 0:
            pct_raw = 100 * raw_frames.max() / session_len if len(raw_frames) > 0 else 0
            pct_scaled = 100 * scaled_frames.max() / session_len if len(scaled_frames) > 0 else 0
            info += f"  |  Session: {session_len} frames — last raw bout at {pct_raw:.1f}%, last scaled at {pct_scaled:.1f}%"

        self.preview_info_label.config(text=info, foreground=info_color)

        # ── Draw session coverage plot ────────────────────────────────
        self._draw_scaled_preview_plot(raw_frames.astype(int), scaled_frames, session_len)

    def _draw_scaled_preview_plot(self, raw_frames, scaled_frames, session_len):
        """Draw the session-coverage plot in the Scaled Preview subtab."""
        if not hasattr(self, 'preview_fig'):
            return

        self.preview_fig.clf()
        ax = self.preview_fig.add_subplot(1, 1, 1)

        n_raw = len(raw_frames)
        n_scaled = len(scaled_frames)

        # Session bar extents
        xmax = max(session_len, max(scaled_frames, default=1), max(raw_frames, default=1)) * 1.02
        xmax = max(xmax, 1)

        # Draw session-length marker
        if session_len > 0:
            ax.axvline(session_len, color='black', linewidth=1.5, linestyle='--', label=f'Session end ({session_len})')

        # Raw frames — row 1 (top)
        if n_raw > 0:
            ax.eventplot(raw_frames, lineoffsets=1.0, linelengths=0.6,
                         colors='steelblue', linewidths=1.2, label=f'Raw ({n_raw} bouts)')

        # Scaled frames — row 0 (bottom)
        if n_scaled > 0:
            ax.eventplot(scaled_frames, lineoffsets=0.0, linelengths=0.6,
                         colors='tomato', linewidths=1.2, label=f'Scaled ({n_scaled} bouts)')

        ax.set_xlim(0, xmax)
        ax.set_ylim(-0.6, 1.6)
        ax.set_yticks([0, 1])
        ax.set_yticklabels(['Scaled', 'Raw'])
        ax.set_xlabel('Frame index (photometry space)')
        ax.set_title('Bout onset distribution across session')
        ax.legend(loc='upper right', fontsize=8)
        ax.grid(axis='x', alpha=0.3)

        self.preview_fig.tight_layout()
        self.preview_canvas.draw()

    # ======================== Groups ========================
    # Groups are the levels of the Group factor, assigned on the Factors tab.
    # The graphing tabs no longer select groups directly: they select a pool of
    # subjects and a facet column splits it, so a group is a facet of the pool
    # rather than the unit of selection.  What survives here is the fan-out that
    # pushes a change to those pool listboxes.

    def fill_group_listbox(self, listbox):
        """Repopulate a tab's pool listbox with every subject, keeping the selection.

        Plotting "by group" means choosing which subjects are in play and
        letting the facet column decide how they divide into series.  The
        listbox therefore lists subjects, not group names: a group is one facet
        of the pool, so restricting a plot to some members of a group has to be
        possible without editing the design on the Factors tab.

        Refreshing is non-destructive -- factors are edited on another tab while
        a graphing tab sits there with a selection, and a change elsewhere must
        not silently empty the plot about to be drawn.  With nothing chosen yet
        the whole pool is selected, so the tab draws something the first time it
        is opened instead of presenting an empty list and no way forward.
        """
        if listbox is None:
            return
        chosen = {listbox.get(i) for i in listbox.curselection()}
        listbox.delete(0, 'end')
        for i, name in enumerate(sorted(str(s) for s in self.processed_data.keys())):
            listbox.insert('end', name)
            if not chosen or name in chosen:
                listbox.selection_set(i)

    # Attribute names of the group-mode listboxes. They hold the subject pool a
    # tab plots from, one per graphing tab; the "group" in the name is historical.
    POOL_LISTBOXES = ('viz_group_listbox', 'behav_group_listbox',
                      'bout_analysis_group_listbox', 'dec_prob_group_listbox',
                      'kin_group_listbox')

    def refresh_pool_listboxes(self):
        """Re-list the subjects in every tab's group-mode pool listbox."""
        for attr in self.POOL_LISTBOXES:
            self.fill_group_listbox(getattr(self, attr, None))

    def update_groups_ui(self):
        """Refresh every listbox and facet column that shows the Group levels."""
        names = list(self.groups.keys())
        self.log_message(f"Groups (levels of the Group factor): {names or 'none assigned'}")

        # Group is a factor, so editing groups changes the facet columns' levels.
        self.refresh_facet_controls()
        self.refresh_pool_listboxes()
        # Coherence and Spike fill their pools per selection mode rather than
        # through fill_group_listbox, so they need telling separately.
        self._refresh_group_name_lists()

    # ======================== Configuration Presets ========================
    
    def save_config_preset(self):
        """Save current processing parameters and settings as a preset"""
        # Ask for preset name
        preset_name = tk.simpledialog.askstring(
            "Save Preset",
            "Enter a name for this configuration preset:",
            parent=self.root
        )
        
        if not preset_name:
            return
        
        # Collect all configuration parameters
        config = {
            'preset_name': preset_name,
            'created_date': pd.Timestamp.now().strftime('%Y-%m-%d %H:%M:%S'),
            'params': {
                'baseline_window': self.params.get('baseline_window', 10.0),
                'pre_event_baseline': self.params.get('pre_event_baseline', 10.0),
                'post_event_window': self.params.get('post_event_window', 30.0),
                'sampling_rate': self.params.get('sampling_rate', 1017.25),
                'bout_min_duration': self.params.get('bout_min_duration', 1.0),
                'bout_max_gap': self.params.get('bout_max_gap', 0.5),
                'z_score_baseline': self.params.get('z_score_baseline', True),
                'baseline_method': self.params.get('baseline_method', 'median'),
                'smoothing_window': self.params.get('smoothing_window', 5),
                'spike_threshold': self.params.get('spike_threshold', 2.0),
                'spike_min_duration': self.params.get('spike_min_duration', 0.5),
                'maze_type': self.params.get('maze_type', 'EPM'),
                'maze_width_cm': self.params.get('maze_width_cm', 76)
            },
            'zones': self.zones.copy()
        }
        
        # Ask for save location
        filepath = filedialog.asksaveasfilename(
            title="Save Configuration Preset",
            defaultextension=".preset",
            filetypes=[("Tracy Preset Files", "*.preset"), ("JSON Files", "*.json"), ("All Files", "*.*")],
            initialdir=self.project_dir if self.project_dir else str(Path.home()),
            initialfile=f"{preset_name}.preset"
        )
        
        if not filepath:
            return
        
        try:
            with open(filepath, 'w') as f:
                json.dump(config, f, indent=2)
            
            messagebox.showinfo("Success", f"Configuration preset saved to:\\n{filepath}")
            self.log_message(f"Saved configuration preset: {preset_name}")
            
        except Exception as e:
            messagebox.showerror("Error", f"Failed to save preset:\\n{str(e)}")
    
    def load_config_preset(self):
        """Load processing parameters and settings from a preset"""
        filepath = filedialog.askopenfilename(
            title="Load Configuration Preset",
            filetypes=[("Tracy Preset Files", "*.preset"), ("JSON Files", "*.json"), ("All Files", "*.*")],
            initialdir=self.project_dir if self.project_dir else str(Path.home())
        )
        
        if not filepath:
            return
        
        try:
            with open(filepath, 'r') as f:
                config = json.load(f)
            
            preset_name = config.get('preset_name', 'Unknown')
            
            # Confirm load
            msg = f"Load configuration preset '{preset_name}'?\\n\\n"
            msg += "This will update:\\n"
            msg += "- Processing parameters\\n"
            msg += "- Zone definitions\\n"
            msg += "- Other settings\\n\\n"
            msg += "Continue?"
            
            if not messagebox.askyesno("Load Preset", msg):
                return
            
            # Load parameters
            if 'params' in config:
                loaded_params = config['params']
                for key, value in loaded_params.items():
                    if key in self.params:
                        self.params[key] = value
            
            # Load zones
            if 'zones' in config:
                self.zones = config['zones'].copy()
            
            # Update UI elements if they exist
            try:
                # Update any visible parameter fields
                if hasattr(self, 'baseline_window_var'):
                    self.baseline_window_var.set(self.params.get('baseline_window', 10.0))
                if hasattr(self, 'post_event_window_var'):
                    self.post_event_window_var.set(self.params.get('post_event_window', 30.0))
                if hasattr(self, 'sampling_rate_var'):
                    self.sampling_rate_var.set(self.params.get('sampling_rate', 1017.25))
                if hasattr(self, 'bout_min_duration_var'):
                    self.bout_min_duration_var.set(self.params.get('bout_min_duration', 1.0))
                if hasattr(self, 'spike_threshold_var'):
                    self.spike_threshold_var.set(self.params.get('spike_threshold', 2.0))
            except:
                pass
            
            messagebox.showinfo("Success", f"Configuration preset '{preset_name}' loaded successfully!")
            self.log_message(f"Loaded configuration preset: {preset_name}")
            
        except json.JSONDecodeError:
            messagebox.showerror("Error", "The selected file is not a valid preset file.")
        except Exception as e:
            messagebox.showerror("Error", f"Failed to load preset:\\n{str(e)}")
    
    # ======================== Visualization ========================
    
    # NOTE: superseded by the definition further down this class, which is the
    # one Python actually binds. Kept only so the older name still resolves.
    def _toggle_subject_group_mode_legacy(self):
        """Toggle between subject and group selection mode in visualization"""
        self.toggle_subject_group_mode()

    def update_viz_groups(self):
        """Update group list in visualization tab"""
        self.fill_group_listbox(self.viz_group_listbox)
    
    def update_viz_subjects(self):
        """Update subject list in visualization tab"""
        # Save current selections
        selected_indices = self.viz_subject_listbox.curselection()
        selected_subjects = [self.viz_subject_listbox.get(i) for i in selected_indices]
        
        # Update list
        self.viz_subject_listbox.delete(0, 'end')
        sorted_subjects = sorted(self.processed_data.keys())
        for subject in sorted_subjects:
            self.viz_subject_listbox.insert('end', subject)
        
        # Restore selections
        for i, subject in enumerate(sorted_subjects):
            if subject in selected_subjects:
                self.viz_subject_listbox.selection_set(i)

        # The group-mode listboxes are subject pools too, so they go stale the
        # moment the loaded set changes -- not only when factors are edited.
        self.refresh_pool_listboxes()

    def update_behav_subjects(self):
        """Update subject list in behavioral data tab"""
        # Save current selections
        selected_indices = self.behav_subject_listbox.curselection()
        selected_subjects = [self.behav_subject_listbox.get(i) for i in selected_indices]
        
        # Update list
        self.behav_subject_listbox.delete(0, 'end')
        valid_subjects = []
        for subject in sorted(self.processed_data.keys()):
            # Only include subjects with position data
            data = self.processed_data[subject]
            if data.get('has_position', False):
                self.behav_subject_listbox.insert('end', subject)
                valid_subjects.append(subject)
        
        # Restore selections (only if subject is still in the list)
        for i, subject in enumerate(valid_subjects):
            if subject in selected_subjects:
                self.behav_subject_listbox.selection_set(i)
    
    # ======================== Exclusions Management ========================

    def apply_integrity_threshold_to_exclusions(self):
        """
        Evaluate the integrity score of the channels belonging to the *currently
        selected subjects* on the Visualization tab and add any combination
        whose overall score is below the user-specified threshold to the Exclusions
        tab.  Existing exclusions are preserved; this only ever *adds* new ones.
        """
        # See generate_plot: a scoring pass pumps the event loop, so the button
        # that started it can be clicked again while it runs.
        if getattr(self, '_integrity_busy', False):
            self.log_message("Still scoring — ignoring.")
            return
        # Validate threshold
        try:
            threshold = float(self.integrity_threshold_var.get())
        except ValueError:
            messagebox.showerror("Invalid Threshold",
                                 "Please enter a numeric value for the minimum integrity score.")
            return

        if not self.processed_data:
            messagebox.showwarning("No Data", "No subjects are loaded. Please process data first.")
            return

        # Restrict the evaluation to the groups/subjects currently selected on the
        # Visualization tab rather than the entire loaded dataset.
        selected_subjects = self._get_selected_viz_subjects()
        if not selected_subjects:
            messagebox.showwarning(
                "No Selection",
                "Auto-exclude only evaluates the currently selected subjects.\n\n"
                "Please select one or more subjects on the Visualization tab first.")
            return

        target_subjects = [s for s in selected_subjects if s in self.processed_data]
        if not target_subjects:
            messagebox.showwarning(
                "No Data",
                "None of the selected groups/subjects have processed data.")
            return

        # Collect every evaluated subject/channel with its score, rather than
        # silently excluding.  The user then reviews the scores in a confirmation
        # window and decides per channel whether to honor or ignore the
        # auto-exclude — useful when group n is small and a poorer channel is
        # worth keeping.
        candidates = []  # (subject, channel, score, already_excluded)
        for subject in self._integrity_progress(target_subjects, 'Auto-exclude'):
            data = self.processed_data[subject]
            channel_metrics_list = self.signal_integrity_metrics(subject, data)
            if not channel_metrics_list:
                continue
            for metrics in channel_metrics_list:
                channel = metrics.get('channel', 'G0')
                score = float(metrics.get('overall_score', 0) or 0)
                already = channel in self.exclusions.get(subject, [])
                candidates.append((subject, channel, score, already))

        if not candidates:
            messagebox.showwarning(
                "No Data",
                "Could not compute integrity scores for the selected groups/subjects.")
            return

        self._show_auto_exclude_confirmation(candidates, threshold, len(target_subjects))

    def _show_auto_exclude_confirmation(self, candidates, threshold, n_subjects):
        """Confirmation window for signal-integrity auto-exclude.

        Shows every evaluated subject/channel with its integrity score; channels
        below ``threshold`` are pre-ticked for exclusion but the user can untick
        any to keep it (e.g. to preserve n in a small group), or tick an
        above-threshold channel to exclude it anyway.  Only the boxes left ticked
        (and not already excluded) are added to the Exclusions tab on Apply."""
        dlg = tk.Toplevel(self.root)
        dlg.title("Confirm Signal-Integrity Auto-Exclude")
        dlg.transient(self.root)
        self.fit_toplevel(dlg, 560, 620)
        dlg.grab_set()

        # Bottom-pinned action row (survives short-screen clamping).
        btn_row = ttk.Frame(dlg, padding=(14, 6, 14, 12))
        btn_row.pack(side='bottom', fill='x')

        header = ttk.Frame(dlg, padding=(14, 12, 14, 4))
        header.pack(side='top', fill='x')
        n_below = sum(1 for _, _, s, a in candidates if s < threshold and not a)
        ttk.Label(header, font=('Segoe UI', 11, 'bold'),
                  text="Review channels flagged for auto-exclude").pack(anchor='w')
        ttk.Label(header, foreground='#666', font=('Segoe UI', 9), justify='left',
                  text=(f"Threshold: score < {threshold:.1f}   |   "
                        f"{n_below} channel(s) flagged across {n_subjects} subject(s).\n"
                        "Ticked = will be excluded. Untick to keep a channel; "
                        "tick an OK channel to exclude it anyway.")).pack(anchor='w', pady=(2, 0))

        # Scrollable body of one checkbox row per channel.
        body_outer = ttk.Frame(dlg)
        body_outer.pack(side='top', fill='both', expand=True, padx=6, pady=4)
        body = self.make_scrollable(body_outer)

        cols = ttk.Frame(body)
        cols.pack(fill='x', pady=(2, 4))
        ttk.Label(cols, text="Exclude", font=('Segoe UI', 9, 'bold'), width=8).grid(row=0, column=0)
        ttk.Label(cols, text="Subject", font=('Segoe UI', 9, 'bold'), width=18).grid(row=0, column=1, sticky='w')
        ttk.Label(cols, text="Channel", font=('Segoe UI', 9, 'bold'), width=8).grid(row=0, column=2, sticky='w')
        ttk.Label(cols, text="Score", font=('Segoe UI', 9, 'bold'), width=8).grid(row=0, column=3, sticky='w')
        ttk.Label(cols, text="Status", font=('Segoe UI', 9, 'bold'), width=16).grid(row=0, column=4, sticky='w')

        row_vars = []  # (subject, channel, score, tk.BooleanVar, already)
        ordered = sorted(candidates, key=lambda c: (c[3], c[2]))  # not-already first, low score first
        for r, (subject, channel, score, already) in enumerate(ordered, 1):
            var = tk.BooleanVar(value=(score < threshold) and not already)
            cb = ttk.Checkbutton(cols, variable=var)
            cb.grid(row=r, column=0)
            if already:
                cb.state(['disabled'])
                var.set(True)
            flagged = score < threshold
            fg = '#c0392b' if flagged else '#2e7d32'
            ttk.Label(cols, text=subject, width=18).grid(row=r, column=1, sticky='w')
            ttk.Label(cols, text=channel, width=8).grid(row=r, column=2, sticky='w')
            ttk.Label(cols, text=f"{score:.1f}", width=8, foreground=fg).grid(row=r, column=3, sticky='w')
            status = "already excluded" if already else ("below threshold" if flagged else "OK")
            ttk.Label(cols, text=status, width=16, foreground='#888' if already else fg).grid(
                row=r, column=4, sticky='w')
            row_vars.append((subject, channel, score, var, already))

        def _set_all(flagged_only, value):
            for subject, channel, score, var, already in row_vars:
                if already or (flagged_only and score >= threshold):
                    continue
                var.set(value)

        quick = ttk.Frame(header)
        quick.pack(anchor='w', pady=(6, 0))
        ttk.Button(quick, text="Select flagged", style='Compact.TButton',
                   command=lambda: _set_all(True, True)).pack(side='left', padx=(0, 4))
        ttk.Button(quick, text="Deselect all", style='Compact.TButton',
                   command=lambda: _set_all(False, False)).pack(side='left')

        def on_apply():
            added = []
            for subject, channel, score, var, already in row_vars:
                if already or not var.get():
                    continue
                self.exclusions.setdefault(subject, [])
                if channel not in self.exclusions[subject]:
                    self.exclusions[subject].append(channel)
                    added.append((subject, channel))
            dlg.destroy()
            self.refresh_exclusions_list()
            if added:
                lines = [f"  • {s} – {c}" for s, c in sorted(added)]
                messagebox.showinfo("Exclusions Updated",
                                    f"{len(added)} channel(s) added to the Exclusions tab:\n\n"
                                    + "\n".join(lines))
            else:
                messagebox.showinfo("No New Exclusions",
                                    "No channels were added to the Exclusions tab.")

        ttk.Button(btn_row, text="Apply Selected Exclusions", command=on_apply).pack(side='left')
        ttk.Button(btn_row, text="Cancel", command=dlg.destroy).pack(side='left', padx=6)

    def refresh_exclusions_list(self):
        """Refresh the exclusions list with current subjects and their channels"""
        # Clear existing widgets
        for widget in self.exclusions_frame.winfo_children():
            widget.destroy()
        
        self.exclusion_vars = {}
        
        if not self.processed_data:
            no_data_label = ttk.Label(self.exclusions_frame, 
                                     text="No subjects loaded. Please process data first.",
                                     font=('Segoe UI', 10), foreground='gray')
            no_data_label.pack(pady=20)
            return
        
        # Header row
        header_frame = ttk.Frame(self.exclusions_frame)
        header_frame.pack(fill='x', padx=5, pady=(5, 10))
        
        ttk.Label(header_frame, text="Subject", font=('Segoe UI', 10, 'bold'), 
                 width=15).grid(row=0, column=0, sticky='w', padx=5)
        ttk.Label(header_frame, text="Exclude Channels (check to exclude):", 
                 font=('Segoe UI', 10, 'bold')).grid(row=0, column=1, sticky='w', padx=20)
        ttk.Label(header_frame, text="Behavioral Data:", 
                 font=('Segoe UI', 10, 'bold')).grid(row=0, column=2, sticky='w', padx=20)
        
        # A valid channel designation is a G/R prefix followed by a region index
        # (e.g. G0, G1, R2, R4, R5). Validate by shape rather than a fixed list so
        # higher-numbered red channels (R3/R4/R5...) are not silently dropped.
        import re
        _is_channel = lambda ch: bool(re.match(r'^[GR]\d+$', str(ch)))

        # Create row for each subject
        for subject in sorted(self.processed_data.keys()):
            data = self.processed_data[subject]

            # Determine available channels for this subject
            available_channels = []
            channel_names = data.get('channel_names') or data.get('channel_name_map', {})

            if isinstance(channel_names, list):
                available_channels = [ch for ch in channel_names if _is_channel(ch)]
            elif isinstance(channel_names, dict):
                # channel_name_map is keyed by column index; preserve column order.
                try:
                    ordered = [channel_names[k] for k in sorted(channel_names, key=lambda x: int(x))]
                except (ValueError, TypeError):
                    ordered = list(channel_names.values())
                available_channels = [ch for ch in ordered if _is_channel(ch)]
            else:
                # Fallback: assume G0 and G1 if has wavelengths
                if data.get('has_470'):
                    available_channels.append('G0')
                if data.get('has_570'):
                    available_channels.append('R0')
                # Try to detect more channels from data shape
                if 'data' in data:
                    n_cols = data['data'].shape[1]
                    n_channels = (n_cols - 2) // 2
                    if n_channels > 1:
                        if data.get('has_470'):
                            for i in range(n_channels):
                                ch_name = f'G{i}'
                                if ch_name not in available_channels:
                                    available_channels.append(ch_name)
                        if data.get('has_570'):
                            for i in range(n_channels):
                                ch_name = f'R{i}'
                                if ch_name not in available_channels:
                                    available_channels.append(ch_name)
            
            if not available_channels:
                # Default fallback
                available_channels = ['G0', 'G1']
            
            # Create row frame
            row_frame = ttk.Frame(self.exclusions_frame)
            row_frame.pack(fill='x', padx=5, pady=2)
            
            # Subject label
            ttk.Label(row_frame, text=subject, font=('Segoe UI', 9), 
                     width=15).grid(row=0, column=0, sticky='w', padx=5)
            
            # Channel checkboxes
            checkbox_frame = ttk.Frame(row_frame)
            checkbox_frame.grid(row=0, column=1, sticky='w', padx=20)
            
            self.exclusion_vars[subject] = {}
            
            for idx, channel in enumerate(available_channels):
                # Check if this channel is currently excluded
                is_excluded = channel in self.exclusions.get(subject, [])
                var = tk.BooleanVar(value=is_excluded)
                self.exclusion_vars[subject][channel] = var
                
                cb = ttk.Checkbutton(checkbox_frame, text=channel, variable=var,
                                    command=lambda s=subject, c=channel: self.toggle_exclusion(s, c))
                cb.grid(row=0, column=idx, padx=10, sticky='w')
            
            # Behavioral data checkbox
            behavioral_frame = ttk.Frame(row_frame)
            behavioral_frame.grid(row=0, column=2, sticky='w', padx=20)
            
            is_behavior_excluded = 'Behavior' in self.exclusions.get(subject, [])
            behavior_var = tk.BooleanVar(value=is_behavior_excluded)
            self.exclusion_vars[subject]['Behavior'] = behavior_var
            
            behavior_cb = ttk.Checkbutton(behavioral_frame, text="Exclude", variable=behavior_var,
                                command=lambda s=subject: self.toggle_exclusion(s, 'Behavior'))
            behavior_cb.pack(side='left')
    
    def toggle_exclusion(self, subject, channel):
        """Toggle exclusion state for a subject/channel combination"""
        is_excluded = self.exclusion_vars[subject][channel].get()
        
        if subject not in self.exclusions:
            self.exclusions[subject] = []
        
        if is_excluded and channel not in self.exclusions[subject]:
            self.exclusions[subject].append(channel)
        elif not is_excluded and channel in self.exclusions[subject]:
            self.exclusions[subject].remove(channel)
        
        # Clean up empty entries
        if subject in self.exclusions and not self.exclusions[subject]:
            del self.exclusions[subject]
    
    def exclusions_select_all(self):
        """Select all channels for exclusion"""
        for subject in self.exclusion_vars:
            for channel in self.exclusion_vars[subject]:
                self.exclusion_vars[subject][channel].set(True)
                self.toggle_exclusion(subject, channel)
    
    def exclusions_deselect_all(self):
        """Deselect all channels (no exclusions)"""
        for subject in self.exclusion_vars:
            for channel in self.exclusion_vars[subject]:
                self.exclusion_vars[subject][channel].set(False)
                self.toggle_exclusion(subject, channel)
    
    def save_exclusions(self):
        """Save exclusions to project"""
        if not self.current_project:
            messagebox.showwarning("No Project", "Please create or load a project first.")
            return
        
        self.save_project()
        messagebox.showinfo("Saved", "Exclusions saved to project.")
    
    def is_subject_channel_excluded(self, subject, channel):
        """Check if a specific subject/channel combination is excluded"""
        return channel in self.exclusions.get(subject, [])
    
    def get_included_subjects_for_channel(self, subjects, channel):
        """Filter subject list to only include those not excluded for given channel"""
        return [s for s in subjects if not self.is_subject_channel_excluded(s, channel)]

    def channel_exclusion_key(self, subject, ch_index, data=None):
        """Exclusion key for one subject's channel *slot index* (0-based).

        The Exclusions tab keys every checkbox by the subject's real channel
        designation (``G0``, ``G1``, ``R2``, ``R4``...), but the plotting and
        export code works in positional slots, because the bout/entry stores are
        keyed ``Ch0``/``Ch1`` with ``G0``/``G1`` kept only as positional aliases.
        Those call sites used to ask about the literal ``'G0'``/``'G1'``, so on a
        recording designated ``R4``/``R5`` the lookup could never match and the
        excluded trace was still drawn.  Resolving the slot per subject here also
        fixes mixed cohorts, where subject A is ``G0``/``G1`` and subject B is
        ``R4``/``R5``.

        Subjects whose channels carry no G/R designation resolve to positional
        ``Ch#`` names; those fall back to ``G0``/``G1``, which is what the tab
        labels their checkboxes and what this code asked for before.
        """
        if data is None:
            data = self.processed_data.get(subject) or {}
        name = str(self.get_channel_name(data, ch_index))
        if re.match(r'^[GR]\d+$', name):
            return name
        return f'G{ch_index}'

    def channel_slot_index(self, channel, default=0):
        """Slot index behind a ``Ch{n}`` key (or a plain int); ``default`` if unparseable."""
        if isinstance(channel, int):
            return channel
        m = re.match(r'^Ch(\d+)$', str(channel))
        return int(m.group(1)) if m else default

    def is_channel_slot_excluded(self, subject, ch_index, data=None):
        """True when the subject's channel at slot ``ch_index`` is excluded."""
        return self.is_subject_channel_excluded(
            subject, self.channel_exclusion_key(subject, ch_index, data))

    def get_included_subjects_for_slot(self, subjects, ch_index):
        """Filter subjects by exclusion on a channel slot index.

        Unlike :meth:`get_included_subjects_for_channel`, each subject is tested
        against its own channel designation rather than one shared literal.
        """
        return [s for s in subjects if not self.is_channel_slot_excluded(s, ch_index)]

    def included_subjects_for_slot_key(self, subjects, ch_key):
        """Filter subjects by the slot named by a ``Ch{n}`` bout key.

        ``_viz_bout_channel_slots`` returns ``(key, label)`` pairs whose label is
        read off the *first* subject that has data.  Filtering on that shared
        label mis-filtered a mixed cohort; filtering on the key's slot index
        resolves each subject's own designation.  ``None`` means the slot is
        unused, so nothing is filtered out.
        """
        if ch_key is None:
            return subjects
        return self.get_included_subjects_for_slot(subjects, self.channel_slot_index(ch_key))

    BEHAVIOR_EXCLUSION_KEY = 'Behavior'

    def is_behavior_excluded(self, subject, use_exclusions=None):
        """True when *subject*'s behavioral data is excluded.

        Behavioral metrics are not per-photometry-channel, so the Exclusions tab
        gives them one pseudo-channel checkbox.  This is the single definition
        of "excluded" for the Behavioral Data tab: the table, the plots and the
        CSV each used to apply a different one, so they could disagree about n.
        In particular the export dropped any subject with *any* non-empty
        exclusion list, so ticking an unrelated photometry channel silently
        deleted that animal's behavioral row.
        """
        if use_exclusions is None:
            var = getattr(self, 'use_exclusions_behavioral', None)
            use_exclusions = bool(var.get()) if var is not None else False
        if not use_exclusions:
            return False
        return self.is_subject_channel_excluded(subject, self.BEHAVIOR_EXCLUSION_KEY)

    def included_behavioral_results(self, results=None, use_exclusions=None):
        """`behavioral_results` rows whose subject is not excluded.

        Applied at every read site rather than only when the metrics are
        computed, because the toggle can be flipped after a calculation and the
        stored rows would otherwise keep the old answer.
        """
        if results is None:
            results = getattr(self, 'behavioral_results', None) or []
        if not self.exclusions:
            return list(results)
        return [r for r in results
                if not self.is_behavior_excluded(r.get('Subject'), use_exclusions)]

    # ======================== End Exclusions Management ========================
    
    def update_bin_entry_state(self):
        """Enable/disable time bin entry based on checkbox"""
        if self.use_time_bins.get():
            self.time_bin_entry.config(state='normal')
        else:
            self.time_bin_entry.config(state='disabled')

    def _get_zone_entry_type_map(self):
        """Return UI label -> (entry_key, display_zone_key) for current maze type."""
        maze_type = self.params.get('maze_type', 'EPM')

        if maze_type == 'OFT':
            return {
                "Center Entry": ("transition_to_center", "center"),
                "Corner Entry": ("transition_to_corner", "corner"),
                "Edge Entry": ("transition_to_edge", "edge")
            }

        if maze_type in ('EPM', 'EPM_Complex'):
            # Default EPM-compatible entry types
            return {
                "Open Arm Entry": ("transition_to_open", "open_arm"),
                "Open Distal Entry": ("transition_to_open_distal", "open_distal"),
                "Center-to-Open Entry": ("center_to_open", "center_to_open"),
                "Explore Decision": ("explore_decision", "explore_decision"),
                "Avoid Decision": ("avoid_decision", "avoid_decision")
            }

        # Custom / generic arena: generate one entry type per defined zone
        result = {}
        for zone_name in self.zones.keys():
            label = f"Transition to {zone_name}"
            key = f"transition_to_{zone_name}"
            result[label] = (key, zone_name)
        return result if result else {"(No zones defined)": ("no_entries", "none")}

    def _dec_prob_base_categories(self):
        """Distinct base zone categories for the Decision Probability From/To
        selectors.  Proximal/distal sub-categories collapse to their base (so
        'open' covers open_proximal + open_distal), giving a clean generic
        selector that works for EPM, OFT, or any custom arena."""
        bases = []
        for zone, info in self.zones.items():
            cat = (info.get('category', zone) if isinstance(info, dict) else zone) or zone
            for suf in ('_proximal', '_distal'):
                if cat.endswith(suf):
                    cat = cat[:-len(suf)]
            if cat not in bases:
                bases.append(cat)
        return bases

    def _dec_prob_zones_for_base(self, base):
        """Zone names whose (base) category matches ``base``."""
        out = []
        for zone, info in self.zones.items():
            cat = (info.get('category', zone) if isinstance(info, dict) else zone) or zone
            for suf in ('_proximal', '_distal'):
                if cat.endswith(suf):
                    cat = cat[:-len(suf)]
            if cat == base:
                out.append(zone)
        return out

    def _update_dec_prob_outcome_labels(self):
        """Refresh the Decision Probability outcome checkbox text and the display
        labels used in plots/exports to match the chosen From/To zones."""
        frm = self.dec_prob_from_var.get() or "from"
        to = self.dec_prob_to_var.get() or "to"
        self._dec_prob_outcome_labels = {
            'explore': f"{frm}→{to}",
            'retreat': f"{to}→{frm}",
        }
        try:
            self._dec_prob_explore_cb.configure(text=f"Forward  ({frm} → {to})")
            self._dec_prob_retreat_cb.configure(text=f"Reverse  ({to} → {frm})")
        except Exception:
            pass

    def _dec_prob_label(self, key):
        """User-facing label for an outcome slot ('explore'/'retreat')."""
        return getattr(self, '_dec_prob_outcome_labels', {}).get(
            key, 'Explore' if key == 'explore' else 'Retreat')

    def _get_default_entry_frames_dict(self):
        """Return empty entry frame lists for all configured entry types."""
        return {entry_key: [] for entry_key, _ in self._get_zone_entry_type_map().values()}
    
    def update_behavior_list(self, *args):
        """Update behavior dropdown based on selected subject and plot type"""
        plot_type = self.plot_type_var.get()
        
        # Save current behavior selection
        current_behavior = self.behavior_var.get()
        
        # Save current subject/group selections
        saved_groups = None
        saved_subjects = None
        if self.plot_by_var.get() == "Group":
            saved_group_indices = list(self.viz_group_listbox.curselection())
            # Selection save/restore, not a plotted series: these must be the
            # listbox's own entries or _restore_group_selections cannot match them.
            saved_groups = [self.viz_group_listbox.get(i) for i in saved_group_indices]
        else:
            saved_subject_indices = list(self.viz_subject_listbox.curselection())
            saved_subjects = [self.viz_subject_listbox.get(i) for i in saved_subject_indices]
        
        # Enable behavior selection for bout-related plots
        if plot_type in ("Bouts Overlay", "Extracted Bouts", "Bout Length Bins", "Compare Across Bouts"):
            self.behavior_combo['state'] = 'readonly'

            behaviors = self._get_behavior_options_for_current_selection()
            self.behavior_combo['values'] = behaviors

            if current_behavior in behaviors:
                self.behavior_var.set(current_behavior)
            elif behaviors:
                self.behavior_var.set(behaviors[0])
            else:
                self.behavior_var.set("")
        else:
            self.behavior_combo['state'] = 'disabled'
        
        # Enable zone entry type selector for Zone Entry Bouts
        if plot_type == "Zone Entry Bouts":
            zone_entry_types = list(self._get_zone_entry_type_map().keys())
            self.zone_entry_type_combo['values'] = zone_entry_types
            if zone_entry_types and self.zone_entry_type_var.get() not in zone_entry_types:
                self.zone_entry_type_var.set(zone_entry_types[0])
            self.zone_entry_type_combo['state'] = 'readonly'
        else:
            self.zone_entry_type_combo['state'] = 'disabled'
        
        # Enable channel and bin size selection for Position Heatmap
        if plot_type == "Position Heatmap":
            self.channel_combo['state'] = 'readonly'
            self.spatial_bin_entry['state'] = 'normal'
        else:
            self.spatial_bin_entry['state'] = 'disabled'
        
        # Enable Signal Integrity channel selector for single-subject Signal Integrity view
        if plot_type == "Signal Integrity":
            # Check if single subject is selected
            selected_indices = self.viz_subject_listbox.curselection()
            if len(selected_indices) == 1:
                # Enable channel selector for single-subject view
                self.integrity_channel_combo['state'] = 'readonly'
                # Update available channels based on the selected subject's data
                subject = self.viz_subject_listbox.get(selected_indices[0])
                if subject in self.processed_data:
                    data = self.processed_data[subject]
                    # Use the real channel designations (G0/G1/R4/…) in column
                    # order so every channel is selectable and labelled correctly.
                    available_channels = self._ordered_channel_names(data)

                    if available_channels:
                        self.integrity_channel_combo['values'] = available_channels
                        # Set to first available channel if current selection is invalid
                        if self.integrity_channel_var.get() not in available_channels:
                            self.integrity_channel_var.set(available_channels[0])
            else:
                # Disable for multi-subject view
                self.integrity_channel_combo['state'] = 'disabled'
            # Sensor mode applies to both single- and multi-subject integrity views
            self.integrity_sensor_check['state'] = 'normal'
        else:
            self.integrity_channel_combo['state'] = 'disabled'
            self.integrity_sensor_check['state'] = 'disabled'

        # Restore saved selections after a brief delay to ensure UI has updated
        if saved_groups is not None:
            self.root.after(10, lambda: self._restore_group_selections(saved_groups))
        elif saved_subjects is not None:
            self.root.after(10, lambda: self._restore_subject_selections(saved_subjects))

    def _get_behavior_options_for_current_selection(self):
        """Return sorted behavior names from currently selected subjects/groups."""
        subjects = []

        if self.plot_by_var.get() == "Group":
            selected_indices = self.viz_group_listbox.curselection()
            selected_groups = self.selected_series('visualization', self.viz_group_listbox)
            for group_name in selected_groups:
                subjects.extend(self._series_members(group_name))
        else:
            selected_indices = self.viz_subject_listbox.curselection()
            subjects = [self.viz_subject_listbox.get(i) for i in selected_indices]

        # Fallback: if nothing selected yet, include all currently loaded subjects
        if not subjects:
            subjects = list(self.processed_data.keys())

        behaviors = set()
        for subject in subjects:
            data = self.processed_data.get(subject, {})
            bouts = data.get('bouts', {})
            if bouts:
                behaviors.update(bouts.keys())

        return sorted(behaviors)
    
    def update_bout_number_selector(self, *args):
        """Update bout number dropdown based on plot type and available data"""
        plot_type = self.plot_type_var.get()
        
        if plot_type == "Compare Across Bouts":
            self.bout_number_combo['state'] = 'readonly'
            
            # Determine which subjects to check
            if self.plot_by_var.get() == "Group":
                selected_indices = self.viz_group_listbox.curselection()
                if not selected_indices:
                    self.bout_number_combo['values'] = ["All"]
                    self.bout_number_var.set("All")
                    return
                
                selected_groups = self.selected_series('visualization', self.viz_group_listbox)
                subjects = []
                for group_name in selected_groups:
                    subjects.extend(self._series_members(group_name))
                subjects = list(set(subjects))
            else:
                selected_indices = self.viz_subject_listbox.curselection()
                if not selected_indices:
                    self.bout_number_combo['values'] = ["All"]
                    self.bout_number_var.set("All")
                    return
                subjects = [self.viz_subject_listbox.get(i) for i in selected_indices]
            
            # Get behavior
            behavior = self.behavior_var.get()
            if not behavior:
                self.bout_number_combo['values'] = ["All"]
                self.bout_number_var.set("All")
                return
            
            # Find maximum bout number across selected subjects
            max_bout_num = 0
            for subject in subjects:
                if subject in self.processed_data:
                    data = self.processed_data[subject]
                    if 'bouts' in data and behavior in data['bouts']:
                        bout_data = data['bouts'][behavior]
                        for channel in ['G0', 'G1', 'Ch0', 'Ch1', 'Ch2', 'Ch3']:
                            if channel in bout_data and bout_data[channel]:
                                max_bout_num = max(max_bout_num, len(bout_data[channel]))
            
            # Create dropdown values: "All", "1", "2", "3", etc.
            if max_bout_num > 0:
                bout_options = ["All"] + [str(i) for i in range(1, max_bout_num + 1)]
                self.bout_number_combo['values'] = bout_options
            else:
                self.bout_number_combo['values'] = ["All"]
            
            # Reset to "All" if current selection is invalid
            current = self.bout_number_var.get()
            if current not in self.bout_number_combo['values']:
                self.bout_number_var.set("All")
        else:
            self.bout_number_combo['state'] = 'disabled'
            self.bout_number_var.set("All")
    
    def toggle_subject_group_mode(self):
        """Toggle between subject and group selection mode in visualization tab"""
        # The two selectors share one slot in the Selection zone, so exactly one
        # is packed at a time and the other leaves no gap behind.  Both list
        # subjects; what differs is what becomes a series -- one per subject, or
        # one per level of whatever the facet column splits on.
        if self.plot_by_var.get() == "Group":
            self.viz_subject_frame.pack_forget()
            self.viz_group_frame.pack(fill='both', expand=True)
            self.fill_group_listbox(self.viz_group_listbox)
            self.refresh_facet_controls()
            tip = ("Tip: these subjects are the pool; 'Split series by' below "
                   "decides how they divide into series. Deselect a subject to "
                   "drop it without changing its factors.")
        else:
            self.viz_group_frame.pack_forget()
            self.viz_subject_frame.pack(fill='both', expand=True)
            tip = ("Tip: hold Ctrl to select several. Channels and wavelengths "
                   "overlay.")
        if getattr(self, 'viz_info_label', None) is not None:
            self.viz_info_label.config(text=tip)

        # Keep selectors synchronized when mode changes.
        self.update_behavior_list()
        self.update_bout_number_selector()
    
    def _restore_subject_selections(self, subjects_to_restore):
        """Helper to restore subject listbox selections"""
        for i in range(self.viz_subject_listbox.size()):
            if self.viz_subject_listbox.get(i) in subjects_to_restore:
                self.viz_subject_listbox.selection_set(i)
    
    def _restore_group_selections(self, groups_to_restore):
        """Helper to restore group listbox selections"""
        for i in range(self.viz_group_listbox.size()):
            if self.viz_group_listbox.get(i) in groups_to_restore:
                self.viz_group_listbox.selection_set(i)
    
    def toggle_behav_subject_group_mode(self):
        """Toggle between subject and group selection mode in behavioral data tab"""
        # The two selectors share one slot in the Selection zone, so exactly one
        # is packed at a time and the other leaves no gap behind.
        if self.behav_plot_by_var.get() == "Group":
            self.behav_subject_frame.pack_forget()
            self.behav_group_frame.pack(fill='both', expand=True)
            self.fill_group_listbox(self.behav_group_listbox)
            self.refresh_facet_controls()
        else:
            self.behav_group_frame.pack_forget()
            self.behav_subject_frame.pack(fill='both', expand=True)
    
    def _open_bout_settings(self):
        """Modal dialog for Bout Analysis metrics, analysis window, and axis controls."""
        dlg = tk.Toplevel(self.root)
