        dlg.transient(self.root)
        dlg.grab_set()
        dlg.resizable(False, False)

        # ── Metrics to Calculate ─────────────────────────────────────────
        mf = ttk.LabelFrame(dlg, text="Metrics to Calculate", padding=8)
        mf.pack(fill='x', padx=12, pady=(12, 5))
        ttk.Checkbutton(mf, text="Average Post-Bout Z-Score",
                        variable=self.metric_avg_post).grid(row=0, column=0, sticky='w', padx=5, pady=2)
        ttk.Checkbutton(mf, text="Max Post-Bout Z-Score",
                        variable=self.metric_max_post).grid(row=0, column=1, sticky='w', padx=5, pady=2)
        ttk.Checkbutton(mf, text="Min Post-Bout Z-Score",
                        variable=self.metric_min_post).grid(row=0, column=2, sticky='w', padx=5, pady=2)
        ttk.Checkbutton(mf, text="First Derivative (Max Rate of Change)",
                        variable=self.metric_first_deriv).grid(row=1, column=0, sticky='w', padx=5, pady=2)
        ttk.Checkbutton(mf, text="Tau (Decay Constant)",
                        variable=self.metric_tau).grid(row=1, column=1, sticky='w', padx=5, pady=2)
        ttk.Checkbutton(mf, text="Area Under Curve",
                        variable=self.metric_auc).grid(row=1, column=2, sticky='w', padx=5, pady=2)
        ttk.Checkbutton(mf, text="Half-Decay Time (t½)",
                        variable=self.metric_t_half).grid(row=2, column=0, sticky='w', padx=5, pady=2)
        dec_row = ttk.Frame(mf)
        dec_row.grid(row=3, column=0, columnspan=3, sticky='w', padx=5, pady=(4, 0))
        ttk.Label(dec_row, text="Decay fit:").pack(side='left')
        self.decay_strictness_var = tk.StringVar(
            value=str(self.params.get('decay_strictness', 'balanced')).lower())
        dec_cb = ttk.Combobox(dec_row, textvariable=self.decay_strictness_var, width=12,
                              state='readonly',
                              values=['strict', 'balanced', 'permissive'])
        dec_cb.pack(side='left', padx=4)
        dec_cb.bind('<<ComboboxSelected>>',
                    lambda _e: self.params.__setitem__(
                        'decay_strictness', self.decay_strictness_var.get()))
        ttk.Label(mf, text="Tau/t½ report N/A when the window holds no measurable decay. "
                           "Stricter = fewer but more trustworthy values; set the analysis "
                           "window to bracket the transient.",
                  foreground='gray', font=('Segoe UI', 7)).grid(
            row=4, column=0, columnspan=3, sticky='w', padx=5, pady=(2, 0))
        auc_row = ttk.Frame(mf)
        auc_row.grid(row=2, column=2, sticky='w', padx=20, pady=2)
        ttk.Radiobutton(auc_row, text="All",   variable=self.metric_auc_mode, value="both").pack(side='left', padx=2)
        ttk.Radiobutton(auc_row, text="+Only", variable=self.metric_auc_mode, value="above").pack(side='left', padx=2)
        ttk.Radiobutton(auc_row, text="-Only", variable=self.metric_auc_mode, value="below").pack(side='left', padx=2)

        # ── Analysis Window ──────────────────────────────────────────────
        wf = ttk.LabelFrame(dlg, text="Analysis Window", padding=8)
        wf.pack(fill='x', padx=12, pady=5)
        win_row = ttk.Frame(wf)
        win_row.pack(fill='x')
        ttk.Label(win_row, text="Window Start Frame:").pack(side='left', padx=(0, 5))
        ttk.Entry(win_row, textvariable=self.frames_before_var, width=10).pack(side='left', padx=(0, 15))
        ttk.Label(win_row, text="Window End Frame:").pack(side='left', padx=(0, 5))
        ttk.Entry(win_row, textvariable=self.frames_after_var, width=10).pack(side='left')
        ttk.Label(wf, text="(frames relative to bout onset; negative=before, positive=after)",
                  foreground='gray', font=('Segoe UI', 8)).pack(anchor='w', pady=(3, 0))

