        dlg.update_idletasks()
        rx = self.root.winfo_rootx() + (self.root.winfo_width()  - dlg.winfo_width())  // 2
        ry = self.root.winfo_rooty() + (self.root.winfo_height() - dlg.winfo_height()) // 2
        dlg.geometry(f"+{rx}+{ry}")

