    def update_bout_analysis_groups(self):
        """Update group list in bout analysis tab"""
        self.fill_group_listbox(self.bout_analysis_group_listbox)
    
    def update_bout_analysis_subjects(self):
        """Update subject list in bout analysis tab"""
        selected_indices = self.bout_analysis_subject_listbox.curselection()
        selected_subjects = [self.bout_analysis_subject_listbox.get(i) for i in selected_indices]
        
        self.bout_analysis_subject_listbox.delete(0, 'end')
        sorted_subjects = sorted(self.processed_data.keys())
        for subject in sorted_subjects:
            self.bout_analysis_subject_listbox.insert('end', subject)
        
        # Restore selections
        for i, subject in enumerate(sorted_subjects):
            if subject in selected_subjects:
                self.bout_analysis_subject_listbox.selection_set(i)

        # Update behavior combo and channel radiobuttons
        self.update_bout_analysis_behaviors()
        self.refresh_bout_analysis_channels()
        # Keep the Signal Linkage tab's lists in sync with loaded data.
        if hasattr(self, 'refresh_signal_linkage_controls'):
            self.refresh_signal_linkage_controls()

    def refresh_bout_analysis_channels(self):
        """Rebuild the bout-analysis channel radiobuttons from the channels
        actually present across processed subjects (any count, G or R)."""
        frame = getattr(self, 'bout_analysis_channel_frame', None)
        if frame is None:
            return
        for w in frame.winfo_children():
            w.destroy()
        chans = self._all_channel_names()
        for idx, ch in enumerate(chans):
            ttk.Radiobutton(frame, text=ch, variable=self.bout_analysis_channel_var,
                            value=ch).pack(side='left', padx=(0 if idx == 0 else 6, 0))
        if self.bout_analysis_channel_var.get() not in chans:
            self.bout_analysis_channel_var.set(chans[0])

    def update_bout_analysis_behaviors(self):
        """Update behavior combo box in bout analysis tab"""
        behaviors = set()
        for subject in self.processed_data.keys():
            if 'bouts' in self.processed_data[subject]:
                behaviors.update(self.processed_data[subject]['bouts'].keys())
        
        self.bout_analysis_behavior_combo['values'] = sorted(list(behaviors))
        if behaviors and not self.bout_analysis_behavior_var.get():
            self.bout_analysis_behavior_var.set(sorted(list(behaviors))[0])
    
    def _on_bout_behavior_changed(self, event=None):
        """Handle behavior selection change in bout analysis - clear stale graphs and results"""
        # Clear stale graphs
        if hasattr(self, 'current_bout_canvas') and self.current_bout_canvas is not None:
            try:
                self.current_bout_canvas.get_tk_widget().destroy()
            except:
                pass
            self.current_bout_canvas = None
        
        if hasattr(self, 'current_bout_figure') and self.current_bout_figure is not None:
            try:
                plt.close(self.current_bout_figure)
            except:
                pass
            self.current_bout_figure = None
        
        # Clear the histogram frame
        if hasattr(self, 'bout_histogram_frame'):
            for widget in self.bout_histogram_frame.winfo_children():
                widget.destroy()
        
        # Clear the treeview
        if hasattr(self, 'bout_metrics_tree'):
            self.bout_metrics_tree.delete(*self.bout_metrics_tree.get_children())
        
        # Clear statistics results text if it exists
        if hasattr(self, 'bout_stats_text'):
            self.bout_stats_text.config(state='normal')
            self.bout_stats_text.delete('1.0', 'end')
            self.bout_stats_text.config(state='disabled')
    
    @staticmethod
    def _axis_grid_state(ax):
        """Return (x_grid_on, y_grid_on) for an axis as the plotting code left it.

        Reads the tick-keyword 'gridOn' flag matplotlib sets in ax.grid(), with a
        gridline-visibility fallback, so we can faithfully restore a plot's own
        grid choice (e.g. y-only bar grids) after the user toggles gridlines off
        and back on."""
        def _on(axis):
            kw = getattr(axis, '_major_tick_kw', None)
            if isinstance(kw, dict) and 'gridOn' in kw:
                return bool(kw['gridOn'])
            try:
                gl = axis.get_gridlines()
                return bool(gl) and any(l.get_visible() for l in gl)
            except Exception:
                return False
        return _on(ax.xaxis), _on(ax.yaxis)

    def _apply_gridlines_to_figure(self, fig, force=False):
        """Apply the global show-gridlines setting to every axis in `fig`.

        When gridlines are ON we leave each axis exactly as the plotting code
        styled it (preserving per-plot alpha / y-only grids), unless `force` is
        set (a live toggle back on), in which case we restore the captured state.
        When OFF we hide all grids. The original per-axis state is captured once
        so it survives repeated toggling."""
        try:
            show = bool(self.show_gridlines.get())
        except Exception:
            show = True
        for ax in fig.axes:
            if not hasattr(ax, '_tracy_grid_state'):
                ax._tracy_grid_state = self._axis_grid_state(ax)
            if show:
                if force:
                    xon, yon = ax._tracy_grid_state
                    ax.grid(xon, axis='x')
                    ax.grid(yon, axis='y')
                # else: leave the caller's grid styling untouched
            else:
                ax.grid(False)

    def _prune_plot_canvases(self):
        """Drop registered canvases whose Tk widget has been destroyed."""
        alive = []
        for c in self._active_plot_canvases:
            try:
                if c.get_tk_widget().winfo_exists():
                    alive.append(c)
            except Exception:
                pass
        self._active_plot_canvases = alive

    def _toggle_gridlines(self):
        """Re-apply the gridline setting to every live figure (all tabs + pop-outs)."""
        self._prune_plot_canvases()
        for canvas in list(self._active_plot_canvases):
            try:
                self._apply_gridlines_to_figure(canvas.figure, force=True)
                canvas.draw_idle()
            except Exception:
                pass

    def _add_grid_toolbar_button(self, toolbar):
        """Add a 'Grid' on/off checkbox to a matplotlib navigation toolbar so the
        gridline toggle is available on every plot, everywhere."""
        try:
            ttk.Checkbutton(toolbar, text="Grid", variable=self.show_gridlines,
                            command=self._toggle_gridlines,
                            takefocus=False).pack(side='left', padx=(8, 2))
        except Exception:
            pass

    def _available_plot_width_px(self, parent):
        """Best estimate of the on-screen width (px) available for a plot canvas.

        Prefers the realized width of the destination container, falling back to
        the main window and finally a fraction of the screen width when nothing
        is laid out yet. A small margin is reserved for the centering holder /
        scrollbars so the plot never butts right up against the window edge.
        """
        try:
            parent.update_idletasks()
        except Exception:
            pass
        candidates = []
        for w in (parent, getattr(self, 'root', None)):
            if w is None:
                continue
            try:
                px = w.winfo_width()
                if px and px > 1:
                    candidates.append(px)
            except Exception:
                pass
        if candidates:
            avail = min(candidates)
        else:
            try:
                avail = int(parent.winfo_screenwidth() * 0.9)
            except Exception:
                avail = 1200
        return max(320, avail - 24)

    def _embed_plot_canvas(self, fig, parent, manual_height=None, add_toolbar=True,
                           fit_width=True):
        """Embed a matplotlib figure (+ optional toolbar) in `parent`, rendered
        at a sensible, readable scale and centered horizontally so it does not
        stretch to fill the whole window.

        The figure is shown at its natural pixel size, except that its on-screen
        width is capped at MAX_PLOT_WIDTH_IN (figures wider than that are scaled
        down proportionally, preserving aspect ratio, so nothing balloons across
        a maximized monitor). The canvas sits in a centering container so wide
        windows get neutral margins instead of a left-anchored plot.

        manual_height: optional pixel height for the graphing area; when None
        the figure's natural height (figsize x dpi) is used.
        Returns the FigureCanvasTkAgg.
        """
        # Cap the figure width by scaling its dpi down (preserves layout/aspect
        # and shrinks fonts uniformly). Done before drawing so the Agg buffer is
        # rendered at the final size rather than clipped by the widget.
        #
        # Two caps are applied and the smaller wins:
        #   1. MAX_PLOT_WIDTH_IN — an absolute inch cap so fonts/layout stay sane
        #      on very large monitors.
        #   2. The actual available on-screen width in pixels — the inch cap is
        #      meaningless on a DPI-scaled or smaller display, where 13in x dpi
        #      can exceed the window and overflow (e.g. the multi-subject Signal
        #      Integrity dashboard). Converting the available pixels back to
        #      inches at the current dpi keeps the rendered plot inside the panel.
        dpi = fig.get_dpi()
        w_in, h_in = fig.get_size_inches()
        # Global plot-size scaling: shrink/grow every figure uniformly (dpi
        # scales rendered pixels AND fonts together, preserving layout/aspect).
        # PLOT_BASE_SCALE keeps defaults compact; self.plot_scale is the user
        # setting. Applied before the width cap so a large scale can't overflow.
        render_scale = PLOT_BASE_SCALE * float(getattr(self, 'plot_scale', 1.0) or 1.0)
        if abs(render_scale - 1.0) > 1e-3:
            dpi = max(20, dpi * render_scale)
            fig.set_dpi(dpi)
        # fit_width=False (used by the scrollable pop-out) keeps the figure at
        # its natural width so wide, many-panel plots (e.g. whole-session
        # coherence) render full-size and are reached by horizontal scrolling
        # instead of being shrunk to fit — the "can't zoom out / scroll to see
        # them all" case.
        if fit_width:
            avail_px = self._available_plot_width_px(parent)
            max_w_in = min(MAX_PLOT_WIDTH_IN, avail_px / float(dpi))
            if w_in > max_w_in:
                new_dpi = max(40, dpi * (max_w_in / float(w_in)))
                fig.set_dpi(new_dpi)
                dpi = new_dpi

        # Honour the global gridline toggle before drawing (and remember this
        # figure so the toggle can live-update it later).
        self._apply_gridlines_to_figure(fig)
        self._prune_plot_canvases()

        # Centering container: fills the parent so the canvas, packed without
        # fill, is centered horizontally with margins on wide windows.
        holder = ttk.Frame(parent)
        canvas = FigureCanvasTkAgg(fig, holder)
        self._active_plot_canvases.append(canvas)

        if add_toolbar:
            # Create the toolbar first so it reserves the bottom strip of the
            # parent; the holder then fills the space above it.
            toolbar = NavigationToolbar2Tk(canvas, parent)
            toolbar.update()
            self._add_grid_toolbar_button(toolbar)

        holder.pack(side='top', fill='both', expand=True)
        canvas.draw_idle()
        widget = canvas.get_tk_widget()

        w_px = int(w_in * dpi)
        h_px = int(h_in * dpi)
        if manual_height is not None:
            h_px = max(100, int(manual_height))
        widget.configure(width=w_px, height=h_px)
        # No fill/expand -> the canvas keeps its requested size; default top
        # packing centers it horizontally within the holder.
        widget.pack(anchor='n', pady=(0, 0))

        canvas.draw_idle()
        self._scroll_plot_zone_to_top(parent)
        return canvas

    def _scroll_plot_zone_to_top(self, widget):
        """Show the scrolling zone that holds *widget* from its top again.

        A newly generated plot is a new thing to look at and is drawn from the
        top down, but Tk keeps the viewport's pixel offset across the change of
        content. After a tall figure — the multi-subject Signal Integrity table
        runs past 20 inches — the zone is still scrolled a thousand pixels down
        when a shorter plot replaces it, so the plot renders perfectly into an
        area nobody is looking at and reads as Generate having done nothing.

        The stale scroll *region* has to be corrected here too. It is normally
        maintained by make_scrollable's <Configure> handler, but that never
        fires on this path: the canvas leaves its window item at the old height,
        so the inner frame is never reconfigured even though its requested size
        collapsed. bbox('all') does follow the new content, so measure from it.
        """
        node = widget
        while node is not None:
            parent = getattr(node, 'master', None)
            # The enclosing scroll viewport, not the plot's own Tk canvas: we
            # only ever walk upwards, and a figure canvas is never an ancestor.
            if isinstance(parent, tk.Canvas):
                try:
                    if parent.cget('scrollregion'):
                        # Re-fit the content to the viewport first: the window
                        # item's height is pinned, so the new plot's requested
                        # size raised no <Configure> and make_scrollable has not
                        # seen it yet. Measuring before this ran gave the *old*
                        # plot's extent.
                        resync = getattr(parent, '_resync_content', None)
                        if callable(resync):
                            resync()
                        bbox = parent.bbox('all')
                        if bbox:
                            parent.configure(scrollregion=bbox)
                        parent.yview_moveto(0.0)
                except Exception:
                    pass
                return
            node = parent

    def _embed_plot_window(self, fig, title, geometry=None):
        """Pop a matplotlib figure out into its own window, embedded in a
        vertically-scrollable, width-capped, centered canvas with a navigation
        toolbar. Replaces the repeated Toplevel + FigureCanvasTkAgg(fill=both,
        expand=True) + NavigationToolbar2Tk boilerplate so every pop-out behaves
        and looks the same. Returns (window, FigureCanvasTkAgg)."""
        win = tk.Toplevel(self.root)
        win.title(title)

        # Toolbar lives at the bottom of the window, outside the scroll area.
        toolbar_holder = ttk.Frame(win)
        toolbar_holder.pack(side='bottom', fill='x')

        outer = ttk.Frame(win)
        outer.pack(side='top', fill='both', expand=True)
        # Both scrollbars: wide many-panel figures (e.g. whole-session coherence)
        # need horizontal scrolling too, not just vertical.
        vscroll = ttk.Scrollbar(outer, orient='vertical')
        hscroll = ttk.Scrollbar(outer, orient='horizontal')
        sc_canvas = tk.Canvas(outer, highlightthickness=0,
                              yscrollcommand=vscroll.set,
                              xscrollcommand=hscroll.set)
        vscroll.config(command=sc_canvas.yview)
        hscroll.config(command=sc_canvas.xview)
        # Grid so the two scrollbars frame the canvas without overlapping.
        sc_canvas.grid(row=0, column=0, sticky='nsew')
        vscroll.grid(row=0, column=1, sticky='ns')
        hscroll.grid(row=1, column=0, sticky='ew')
        outer.rowconfigure(0, weight=1)
        outer.columnconfigure(0, weight=1)

        inner = ttk.Frame(sc_canvas)
        sc_canvas.create_window((0, 0), window=inner, anchor='nw')

        def _sync_scrollregion(_e=None):
            sc_canvas.configure(scrollregion=sc_canvas.bbox('all'))
        inner.bind('<Configure>', _sync_scrollregion)

        # Render at natural width (fit_width=False) so wide plots overflow into
        # the horizontal scroll region instead of being shrunk to fit; keep the
        # toolbar out of the scroll region.
        canvas = self._embed_plot_canvas(fig, inner, add_toolbar=False, fit_width=False)
        toolbar = NavigationToolbar2Tk(canvas, toolbar_holder)
        toolbar.update()
        self._add_grid_toolbar_button(toolbar)

        # Mouse-wheel scrolls the pop-out while the pointer is over it; Shift+wheel
        # scrolls horizontally (standard convention for wide content).
        def _wheel(event):
            try:
                sc_canvas.yview_scroll(int(-1 * (event.delta / 120)), 'units')
            except tk.TclError:
                pass
        def _wheel_h(event):
            try:
                sc_canvas.xview_scroll(int(-1 * (event.delta / 120)), 'units')
            except tk.TclError:
                pass
        def _bind_wheels(_e=None):
            sc_canvas.bind_all('<MouseWheel>', _wheel)
            sc_canvas.bind_all('<Shift-MouseWheel>', _wheel_h)
        def _unbind_wheels(_e=None):
            sc_canvas.unbind_all('<MouseWheel>')
            sc_canvas.unbind_all('<Shift-MouseWheel>')
        sc_canvas.bind('<Enter>', _bind_wheels)
        sc_canvas.bind('<Leave>', _unbind_wheels)

        # Size the window to the capped figure (plus toolbar / scrollbar) unless
        # the caller asked for a specific geometry.
        if geometry:
            win.geometry(geometry)
        else:
            dpi = fig.get_dpi()
            w_in, h_in = fig.get_size_inches()
            # Clamp the WINDOW to the screen; the figure keeps its natural size
            # inside and overflow is reached via the scrollbars. Without this a
            # very wide/tall figure would open a window larger than the display.
            try:
                scr_w = int(win.winfo_screenwidth() * 0.95)
                scr_h = int(win.winfo_screenheight() * 0.90)
            except Exception:
                scr_w, scr_h = 1400, 900
            w_px = min(scr_w, int(w_in * dpi) + 60)
            h_px = min(scr_h, int(h_in * dpi) + 90)
            win.geometry(f"{max(400, w_px)}x{max(300, h_px)}")
        return win, canvas

    def _bout_fig_width(self, n_items, per_item=0.9, base=3.5, minimum=5.5):
        """Content-aware figure width (inches) for the Bout Analysis plots.

        Grows modestly with the number of categories so few-category plots stay
        compact instead of stretching across the whole window, and is capped to
        the available canvas width so wide plots never need a horizontal scroll.
        """
        content = max(minimum, int(max(1, n_items)) * per_item + base)
        cap = 13.0
        try:
            cpx = self.bout_histogram_canvas.winfo_width()
            if cpx > 100:
                cap = (cpx - 24) / 100.0
        except Exception:
            pass
        return max(minimum, min(content, cap))

    def _auto_viz_figure_size(self, plot_type, n_subjects, subjects=None):
        """Content-aware default figure size for the Visualization tab's 'auto' mode.

        Chooses dimensions that suit the plot type and how much data is shown so
        simple single-subject plots stay compact instead of stretching to the
        full width of the window, while dense multi-subject / grid plots grow
        proportionally. Returns a (width, height) tuple in inches.
        """
        n = max(1, int(n_subjects or 1))
        subjects = list(subjects) if subjects else None

        # Sizes are kept deliberately compact so plots render at a readable
        # scale rather than filling the whole window; the canvas is shown at
        # this natural size (see _embed_plot_canvas).

        # Signal Integrity: a multi-panel dashboard for one subject, a table for
        # several.
        if "Signal Integrity" in plot_type:
            if n <= 1:
                return (min(13.0, 11.0 + (n - 1) * 0.5), 7.5)
            # The table draws one row per *channel* and lays them out in axes
            # fractions, so a fixed height silently shrinks the rows until they
            # overlap into an unreadable smear -- 62 subjects means 124 rows in
            # 7.5in, about 3 pixels each. Height therefore grows with the rows;
            # the output zone scrolls, so a tall figure stays reachable.
            rows = self._integrity_row_estimate(subjects) if subjects else n * 2
            return (min(13.0, 11.0 + (n - 1) * 0.5),
                    max(7.5, min(48.0, 1.8 + rows * 0.17)))

        # Position Heatmap renders one panel per subject (a true grid).
        # NOTE: "Extracted Bouts" and "Zone Entry Bouts" are deliberately NOT
        # grid-sized here — their multi/group plots collapse all subjects into a
        # fixed 1- or 2-row trace+heatmap layout, so they are sized by channel
        # count in generate_plot (see _viz_bout_channel_rows) instead.
        if "Position Heatmap" in plot_type:
            ncols = min(3, n)
            nrows = int(np.ceil(n / ncols))
            # Roughly square panels for spatial data.
            return (min(12.0, 3.5 * ncols + 1.0), min(9.0, 3.5 * nrows + 1.0))

        # Time-series / single-axis traces: wide and short.
        if plot_type in ("Raw Data", "Normalized (dF/F)", "Motion Corrected",
                         "Z-scored", "Bouts Overlay"):
            return (10.5, 4.5)

        # Bar / average style plots: these stack one subplot per visible
        # photometry channel (G0 / G1), so size by channel ROWS for height and
        # keep the width modest so a 2-category plot isn't wide-and-short.
        if any(t in plot_type for t in ("Zone Averages", "Distance from Center",
                                        "Out/Back", "Compare Across Bouts")):
            try:
                rows = (1 if self.show_g0.get() else 0) + (1 if self.show_g1.get() else 0)
            except Exception:
                rows = 2
            rows = max(1, rows)
            width = min(9.5, 6.5 + (n - 1) * 0.4)
            return (width, 3.2 * rows + 0.8)

        # Sensible default.
        return (9.0, 5.0)

    def _integrity_row_estimate(self, subjects):
        """Rows the multi-subject Signal Integrity table will draw.

        One per photometry channel per subject. Read off the stored channel
        count rather than by scoring anything, because this decides the figure
        size and must be cheap -- scoring is the expensive part it is sizing for.
        """
        rows = 0
        for s in subjects or []:
            d = self.processed_data.get(s)
            if not isinstance(d, dict):
                continue
            if not (d.get('has_470') or d.get('has_570')):
                continue
            rows += max(1, int(d.get('num_photometry_channels') or 1))
        return max(1, rows)

    def _viz_bout_channel_rows(self, subjects):
        """How many channel rows the bout trace+heatmap plots will draw (1 or 2).

        The Extracted Bouts and Zone Entry Bouts plots lay out one row of
        trace+heatmap per photometry channel that has data (G0 and/or G1), and
        do NOT add a panel per subject. Sizing therefore depends on channel
        count, not subject count. Returns 2 when any selected subject was
        recorded on two photometry channels (and both are visible), else 1.
        """
        two_channel = False
        for s in subjects:
            d = self.processed_data.get(s, {})
            if isinstance(d, dict) and d.get('num_photometry_channels', 1) and d['num_photometry_channels'] >= 2:
                two_channel = True
                break
        if not two_channel:
            return 1
        # Respect the G0/G1 visibility toggles (Zone Entry Bouts honors these);
        # if one channel is hidden only a single row is drawn.
        try:
            if not (self.show_g0.get() and self.show_g1.get()):
                return 1
        except Exception:
            pass
        return 2

    def _keep_legends_clear_of_data(self, fig):
        """Reposition every legend in the figure so it never sits on top of data.

        Time-series traces fill the whole axes, so a legend drawn over them hides
        the signal (e.g. the group bout-overlay plots). For each axis that has a
        legend we anchor it in the top-left corner and open matching headroom by
        extending the y-axis upward, so the legend box lands in clear space above
        the traces. Axes without a legend (heatmaps, colorbars) are left alone.
        """
        for ax in fig.get_axes():
            leg = ax.get_legend()
            if leg is None:
                continue
            handles, labels = ax.get_legend_handles_labels()
            if not handles:
                continue

            # Preserve the original legend's styling where we can.
            title_txt = leg.get_title().get_text() if leg.get_title() else None
            try:
                fontsize = leg.get_texts()[0].get_fontsize()
            except (IndexError, AttributeError):
                fontsize = 8
            ncol = getattr(leg, '_ncols', None) or getattr(leg, '_ncol', 1) or 1

            y0, y1 = ax.get_ylim()
            if not (np.isfinite(y0) and np.isfinite(y1) and y1 > y0):
                continue

            # Headroom scales with the number of legend rows so multi-entry
            # legends still clear the data.
            n_rows = int(np.ceil(len(labels) / max(1, ncol)))
            headroom = min(0.55, 0.16 + 0.07 * n_rows)
            ax.set_ylim(y0, y1 + (y1 - y0) * headroom)

            ax.legend(handles, labels, loc='upper left', fontsize=fontsize,
                      ncol=ncol, title=title_txt, framealpha=0.9)

    def _get_selected_viz_subjects(self):
        """Return the subjects currently selected on the Visualization tab.

        Honors Group vs Subject mode (in Group mode the members of the faceted
        series are expanded, de-duplicated, order preserved — which drops any
        subject the pool listbox has deselected). Returns an empty list if
        nothing is selected. Does not show error dialogs — callers that need
        user feedback handle the empty case themselves.
        """
        selected_subjects = []
        try:
            if self.plot_by_var.get() == "Group":
                selected_indices = self.viz_group_listbox.curselection()
                selected_groups = self.selected_series('visualization', self.viz_group_listbox)
                for group_name in selected_groups:
                    selected_subjects.extend(self._series_members(group_name))
                seen = set()
                selected_subjects = [s for s in selected_subjects
                                     if not (s in seen or seen.add(s))]
            else:
                selected_indices = self.viz_subject_listbox.curselection()
                selected_subjects = [self.viz_subject_listbox.get(i) for i in selected_indices]
        except Exception:
            return []
        return selected_subjects

    def _integrity_cache_signature(self, valid_subjects):
        """Build a lightweight fingerprint of everything that affects the
        Signal Integrity graph, so a cached figure can be safely reused.

        Includes the selection, the identity of each subject's data dict
        (reprocessing replaces the dict → new id → cache miss), the sensor-mode
        and channel settings, and the figure/canvas size settings.
        """
        try:
            sensor = bool(self.integrity_sensor_mode_var.get())
        except Exception:
            sensor = False
        channel = self.integrity_channel_var.get() if len(valid_subjects) == 1 else "<multi>"
        data_ids = tuple((s, id(self.processed_data.get(s))) for s in valid_subjects)
        sizes = (self.viz_fig_width_var.get(),
                 self.viz_fig_height_var.get(),
                 self.viz_canvas_height_var.get())
        return (self.plot_by_var.get(), tuple(valid_subjects), data_ids, sensor, channel, sizes)

    def generate_plot(self):
        """Generate selected plot type"""
        # A long integrity run pumps the event loop to stay responsive, which
        # also delivers any Generate clicks queued during it. Re-entering would
        # start a second scoring pass on top of the first.
        if getattr(self, '_integrity_busy', False):
            self.log_message("Still scoring the previous plot — ignoring.")
            return
        # Get selected subjects or groups
        if self.plot_by_var.get() == "Group":
            # Group mode - get selected groups and their members
            selected_indices = self.viz_group_listbox.curselection()
            if not selected_indices:
                messagebox.showerror("Error", "Please select at least one subject")
                return
            
            selected_groups = self.selected_series('visualization', self.viz_group_listbox)
            selected_subjects = []
            for group_name in selected_groups:
                selected_subjects.extend(self._series_members(group_name))
            
            # Remove duplicates while preserving order
            seen = set()
            selected_subjects = [s for s in selected_subjects if not (s in seen or seen.add(s))]
            
            if not selected_subjects:
                messagebox.showerror("Error", "Selected groups have no members")
                return
        else:
            # Subject mode - get selected subjects
            selected_indices = self.viz_subject_listbox.curselection()
            if not selected_indices:
                messagebox.showerror("Error", "Please select at least one subject")
                return
            
            selected_subjects = [self.viz_subject_listbox.get(i) for i in selected_indices]
        
        # Validate all subjects have data
        valid_subjects = [s for s in selected_subjects if s in self.processed_data]
        if not valid_subjects:
            messagebox.showerror("Error", "No valid subjects selected")
            return
        
        # Apply exclusions if enabled (note: channel-specific filtering happens in individual plot functions)
        # For now, we pass all valid_subjects and let each plot function handle exclusions based on channel
        # This is because different plots use different channels
        
        # Clear previous plot
        for widget in self.fig_frame.winfo_children():
            widget.destroy()

        plot_type = self.plot_type_var.get()

        # Signal Integrity is expensive to compute. Reuse a cached figure when
        # the selection and settings are unchanged so it can be revisited
        # instantly (e.g. after switching plot types and back).
        si_cache_sig = None
        if "Signal Integrity" in plot_type:
            si_cache_sig = self._integrity_cache_signature(valid_subjects)
            cached = self._integrity_plot_cache
            if cached and cached.get('sig') == si_cache_sig:
                fig = cached['fig']
                self.current_viz_figure = fig
                manual_height = None
                try:
                    ch_str = self.viz_canvas_height_var.get().strip().lower()
                    if ch_str not in ('', 'auto'):
                        manual_height = int(float(ch_str))
                except (ValueError, AttributeError):
                    manual_height = None
                canvas = self._embed_plot_canvas(fig, self.fig_frame, manual_height=manual_height)
                self.current_viz_canvas = canvas
                self.log_message("Signal Integrity: showing cached graph (no recompute).")
                return

        # Warn if the selected subjects' stored bouts span mismatched extraction
        # windows (a partial reprocess) — these plots realign onto the current
        # window, so otherwise some subjects silently show blank/truncated data.
        if any(t in plot_type for t in
               ("Extracted Bouts", "Compare Across Bouts", "Bouts Overlay")):
            try:
                self._warn_if_mixed_bout_windows(valid_subjects)
            except Exception as _e:
                self.log_message(f"Bout-window check skipped: {_e}")

        # Determine figure size – use user-set values or fall back to
        # content-aware, plot-type-specific defaults (scales with item count).
        # Group-mode grid plots draw one panel per *group*, not per subject, so
        # size by group count there to avoid an oversized, mostly-empty figure.
        size_count = len(valid_subjects)
        if (self.plot_by_var.get() == "Group"
                and "Position Heatmap" in plot_type):
            try:
                size_count = max(1, len(self.viz_group_listbox.curselection()))
            except Exception:
                pass

        if any(t in plot_type for t in ("Extracted Bouts", "Zone Entry Bouts")):
            # These collapse every selected subject into a fixed 1- or 2-row
            # trace+heatmap layout, so size by channel count, not subject count —
            # otherwise selecting many subjects inflates the figure until it
            # fills the screen.
            rows = self._viz_bout_channel_rows(valid_subjects)
            default_w, default_h = 11.0, 4.2 * rows + 0.6
        else:
            default_w, default_h = self._auto_viz_figure_size(
                plot_type, size_count, valid_subjects)
        try:
            w_str = self.viz_fig_width_var.get().strip().lower()
            fig_w = float(w_str) if w_str not in ('', 'auto') else default_w
            fig_w = max(3.0, fig_w)
        except (ValueError, AttributeError):
            fig_w = default_w
        try:
            h_str = self.viz_fig_height_var.get().strip().lower()
            fig_h = float(h_str) if h_str not in ('', 'auto') else default_h
            fig_h = max(2.0, fig_h)
        except (ValueError, AttributeError):
            fig_h = default_h

        fig = Figure(figsize=(fig_w, fig_h))
        
        # For single subject plots, use first selected subject
        # EXCEPT for Signal Integrity, which can handle multiple subjects
        plot_error = False
        try:
            if ("Signal Integrity" in plot_type and len(valid_subjects) > 1):
                # Multi-subject Signal Integrity summary
                self.plot_signal_integrity_multi(fig, valid_subjects)
            elif len(valid_subjects) == 1 or plot_type in ["Raw Data", "Normalized (dF/F)", "Motion Corrected", "Z-scored", "Signal Integrity"]:
                subject = valid_subjects[0]
                data = self.processed_data[subject]

                if "Raw" in plot_type:
                    self.plot_raw_data(fig, data)
                elif "Normalized" in plot_type:
                    self.plot_dff_data(fig, data)
                elif "Motion Corrected" in plot_type:
                    self.plot_corrected_data(fig, data)
                elif "Z-scored" in plot_type:
                    self.plot_zscore_data(fig, data)
                elif "Signal Integrity" in plot_type:
                    self.plot_signal_integrity(fig, data, subject)
                elif "Bouts Overlay" in plot_type:
                    self.plot_bouts_overlay(fig, data, subject)
                elif "Bout Length Bins" in plot_type:
                    self.plot_bout_length_bins(fig, data, subject)
                elif "Extracted Bouts" in plot_type:
                    self.plot_extracted_bouts(fig, data)
                elif "Compare Across Bouts" in plot_type:
                    self.plot_bout_comparison_single(fig, data, subject)
                elif "Position Heatmap" in plot_type:
                    self.plot_position_heatmap(fig, data, subject)
                elif "Zone Entry Bouts" in plot_type:
                    self.plot_zone_entry_bouts(fig, data, subject)
                elif "Zone Averages" in plot_type:
                    self.plot_zone_averages(fig, data, subject)
                elif "Distance from Center (Euclidean)" in plot_type:
                    self.plot_distance_from_center_euclidean(fig, data, subject)
                elif "Distance from Center" in plot_type:
                    self.plot_distance_from_center(fig, data, subject)
                elif "Out/Back" in plot_type:
                    self.plot_outback(fig, data, subject)
            else:
                # Multi-subject plots
                if "Position Heatmap" in plot_type:
                    # If comparing groups, plot heatmaps per group instead of flattening subjects
                    if self.plot_by_var.get() == "Group":
                        selected_indices = self.viz_group_listbox.curselection()
                        selected_groups = self.selected_series('visualization', self.viz_group_listbox)
                        self.plot_position_heatmap_by_group(fig, selected_groups)
                    else:
                        self.plot_position_heatmap_multi(fig, valid_subjects)
                elif "Zone Entry Bouts" in plot_type:
                    self.plot_zone_entry_bouts_multi(fig, valid_subjects)
                elif "Zone Averages" in plot_type:
                    self.plot_zone_averages_multi(fig, valid_subjects)
                elif "Distance from Center (Euclidean)" in plot_type:
                    self.plot_distance_from_center_euclidean_multi(fig, valid_subjects)
                elif "Distance from Center" in plot_type:
                    self.plot_distance_from_center_multi(fig, valid_subjects)
                elif "Out/Back" in plot_type:
                    self.plot_outback_multi(fig, valid_subjects)
                elif "Compare Across Bouts" in plot_type:
                    # Check if we're in group mode
                    if self.plot_by_var.get() == "Group":
                        selected_indices = self.viz_group_listbox.curselection()
                        selected_groups = self.selected_series('visualization', self.viz_group_listbox)
                        self.plot_bout_comparison_by_group(fig, selected_groups)
                    else:
                        self.plot_bout_comparison_multi(fig, valid_subjects)
                elif "Bout Length Bins" in plot_type:
                    self.plot_bout_length_bins_multi(fig, valid_subjects)
                elif "Extracted Bouts" in plot_type:
                    # Check if we're in group mode
                    if self.plot_by_var.get() == "Group":
                        # Get which groups were selected and create group-based plot
                        selected_indices = self.viz_group_listbox.curselection()
                        selected_groups = self.selected_series('visualization', self.viz_group_listbox)
                        self.plot_extracted_bouts_by_group(fig, selected_groups)
                    else:
                        self.plot_extracted_bouts_multi(fig, valid_subjects)
                else:
                    messagebox.showinfo("Info", "Multi-subject comparison only available for Position Heatmap and Extracted Bouts")
                    return
        except Exception as e:
            # Surface plotting failures in-panel instead of silently leaving a
            # blank graphing area (previously any exception here aborted before
            # the canvas was embedded, so "no graph" appeared with no feedback).
            import traceback
            tb = traceback.format_exc()
            plot_error = True
            self.log_message(f"Error generating '{plot_type}' plot: {e}")
            self.log_message(tb)
            fig.clear()
            fig.text(0.5, 0.5,
                     f"Could not generate '{plot_type}' plot:\n{e}\n\n"
                     f"See the log for details.",
                     ha='center', va='center', fontsize=11, color='firebrick', wrap=True)
        
        # _integrity_progress lowers this in its finally, but that only runs when
        # the generator is closed -- and if a plot raised mid-loop, that is left
        # to the collector. Clearing it here means a failed plot can never wedge
        # the button permanently.
        self._integrity_busy = False

        # Store figure and canvas for axis control
        self.current_viz_figure = fig

        # Cache the freshly-computed Signal Integrity figure so it can be
        # re-viewed without recomputing. Pin the source data dicts in 'refs' so
        # their object ids stay stable while cached (reprocessing replaces them).
        if si_cache_sig is not None and not plot_error:
            self._integrity_plot_cache = {
                'sig': si_cache_sig,
                'fig': fig,
                'refs': [self.processed_data.get(s) for s in valid_subjects],
            }

        # Keep legends from covering the plotted data across every graph type.
        try:
            self._keep_legends_clear_of_data(fig)
        except Exception as e:
            self.log_message(f"Legend repositioning skipped: {e}")

        # Tighten layout before embedding so labels aren't clipped.
        try:
            fig.tight_layout()
        except Exception:
            pass  # Some plots may not support tight_layout

        # Resolve optional manual graphing-area height (px); 'auto' uses the
        # figure's natural height.
        manual_height = None
        try:
            ch_str = self.viz_canvas_height_var.get().strip().lower()
            if ch_str not in ('', 'auto'):
                manual_height = int(float(ch_str))
        except (ValueError, AttributeError):
            manual_height = None

        # Embed at natural size so the plot doesn't stretch to fill the window.
        canvas = self._embed_plot_canvas(fig, self.fig_frame, manual_height=manual_height)
        self.current_viz_canvas = canvas
    
    def apply_viz_axis_limits(self):
        """Apply custom Y-axis limits to current visualization plot"""
        if self.current_viz_figure is None:
            messagebox.showwarning("No Plot", "Please generate a plot first")
            return
        
        try:
            ymin_str = self.viz_ymin_var.get().strip().lower()
            ymax_str = self.viz_ymax_var.get().strip().lower()
            
            # Get all axes in the figure
            for ax in self.current_viz_figure.get_axes():
                ylim = list(ax.get_ylim())
                
                # Update ymin if not auto
                if ymin_str != "auto" and ymin_str != "":
                    ylim[0] = float(ymin_str)
                
                # Update ymax if not auto
                if ymax_str != "auto" and ymax_str != "":
                    ylim[1] = float(ymax_str)
                
                ax.set_ylim(ylim)
            
            # Redraw with improved performance
            if self.current_viz_canvas:
                self.current_viz_canvas.draw_idle()
                self.current_viz_canvas.flush_events()
                
        except ValueError:
            messagebox.showerror("Invalid Input", "Please enter numeric values or 'auto' for axis limits")
    
    def reset_viz_axis_limits(self):
        """Reset Y-axis limits to auto-scale"""
        if self.current_viz_figure is None:
            messagebox.showwarning("No Plot", "Please generate a plot first")
            return
        
        # Reset entry fields
        self.viz_ymin_var.set("auto")
        self.viz_ymax_var.set("auto")
        
        # Auto-scale all axes
        for ax in self.current_viz_figure.get_axes():
            ax.relim()
            ax.autoscale_view()
        
        # Redraw with improved performance
        if self.current_viz_canvas:
            self.current_viz_canvas.draw_idle()
            self.current_viz_canvas.flush_events()
    
    def update_heatmap_custom_colors(self, *args):
        """Enable/disable custom color pickers based on colormap selection.

        The picker widgets only exist while the Advanced Graph Settings window
        is open, so each is guarded against being absent or destroyed.
        """
        is_custom = self.heatmap_cmap_var.get() == "custom"
        state = 'normal' if is_custom else 'disabled'

        for attr in ('heatmap_color_low_entry', 'heatmap_color_low_btn',
                     'heatmap_color_mid_entry', 'heatmap_color_mid_btn',
                     'heatmap_color_high_entry', 'heatmap_color_high_btn'):
            widget = getattr(self, attr, None)
            if widget is None:
                continue
            try:
                widget.config(state=state)
            except tk.TclError:
                pass  # widget destroyed (settings window closed)
    
    def pick_heatmap_color(self, position):
        """Open color picker for heatmap custom colors"""
        if position == 'low':
            current_color = self.heatmap_color_low_var.get()
            var = self.heatmap_color_low_var
        elif position == 'mid':
            current_color = self.heatmap_color_mid_var.get()
            var = self.heatmap_color_mid_var
        else:  # high
            current_color = self.heatmap_color_high_var.get()
            var = self.heatmap_color_high_var
        
        # Open color chooser
        color = colorchooser.askcolor(color=current_color, title=f"Choose {position.title()} Color")
        if color[1]:  # If a color was selected (not cancelled)
            var.set(color[1])
    
    def get_heatmap_colormap(self):
        """Get the colormap for heatmaps based on user settings"""
        cmap_name = self.heatmap_cmap_var.get()
        
        if cmap_name == "custom":
            # Create custom colormap from three colors
            try:
                low_color = self.heatmap_color_low_var.get()
                mid_color = self.heatmap_color_mid_var.get()
                high_color = self.heatmap_color_high_var.get()
                
                # Create custom colormap
                colors = [low_color, mid_color, high_color]
                n_bins = 256
                cmap = LinearSegmentedColormap.from_list('custom', colors, N=n_bins)
                return cmap
            except:
                # Fallback to default if custom colors are invalid
                return 'RdBu_r'
        else:
            return cmap_name
    
    def get_heatmap_range(self):
        """Get the vmin and vmax values for heatmaps"""
        try:
            vmin = float(self.heatmap_vmin_var.get())
            vmax = float(self.heatmap_vmax_var.get())
            return vmin, vmax
        except:
            # Return defaults if invalid
            return -3, 3
    
    def get_trace_styling(self):
        """Get trace styling parameters from user settings"""
        try:
            mean_width = float(self.mean_linewidth_var.get())
            mean_width = max(0.1, min(5.0, mean_width))  # Clamp between 0.1 and 5
        except (ValueError, AttributeError):
            mean_width = 1.5
        
        try:
            trace_width = float(self.trace_linewidth_var.get())
            trace_width = max(0.1, min(5.0, trace_width))  # Clamp between 0.1 and 5
        except (ValueError, AttributeError):
            trace_width = 0.3
        
        try:
            trace_alpha = float(self.trace_alpha_var.get())
            trace_alpha = max(0.0, min(1.0, trace_alpha))  # Clamp between 0 and 1
        except (ValueError, AttributeError):
            trace_alpha = 0.3
        
        return mean_width, trace_width, trace_alpha

    def _get_rolling_window_frames(self):
        """Visualization-time smoothing is disabled (handled in processing)."""
        return 1

    def _apply_visualizer_smoothing(self, signal):
        """Apply optional centered rolling-average smoothing to a 1D signal."""
        if signal is None:
            return signal

        window = self._get_rolling_window_frames()
        if window <= 1:
            return signal

        try:
            return pd.Series(signal).rolling(window=window, center=True, min_periods=1).mean().to_numpy()
        except Exception:
            return signal

    def _overlay_current_zones(self, ax):
        """Overlay current zone editor settings on position heatmaps."""
        if not getattr(self, 'show_zone_overlay_var', None) or not self.show_zone_overlay_var.get():
            return

        if not hasattr(self, 'zones') or not self.zones:
            return

        for zone_name, zone in self.zones.items():
            try:
                x_min = zone['x_min']
                x_max = zone['x_max']
                y_min = zone['y_min']
                y_max = zone['y_max']
                width = x_max - x_min
                height = y_max - y_min
                color = zone.get('color', '#FFFFFF')

                rect = Rectangle((x_min, y_min), width, height,
                                 linewidth=1.2, edgecolor=color, facecolor='none', alpha=0.9)
                ax.add_patch(rect)
                ax.text(x_min + width / 2, y_min + height / 2, zone_name,
                        ha='center', va='center', fontsize=7, color='black',
                        bbox=dict(boxstyle='round,pad=0.15', facecolor='white', alpha=0.6, edgecolor='none'))
            except Exception:
                continue

    def _update_zone_overlay_button_label(self):
        """Refresh visualization tab button text based on overlay visibility state."""
        if not hasattr(self, 'zone_overlay_button') or not hasattr(self, 'show_zone_overlay_var'):
            return
        self.zone_overlay_button.config(
            text="Hide Zone Overlay" if self.show_zone_overlay_var.get() else "Show Zone Overlay"
        )

    def toggle_zone_overlay(self):
        """Toggle zone overlay visibility for position heatmaps."""
        if not hasattr(self, 'show_zone_overlay_var'):
            return

        self.show_zone_overlay_var.set(not self.show_zone_overlay_var.get())
        self._update_zone_overlay_button_label()

        # Redraw current plot to reflect the updated overlay state.
        try:
            if hasattr(self, 'plot_type_var') and self.plot_type_var.get() == "Position Heatmap":
                self.generate_plot()
        except Exception:
            pass

    def _recompute_zone_entries_all(self):
        """Re-run zone-entry detection + entry-bout extraction for every processed
        subject that has position data, using the current duration / refractory
        params. Lets the transition thresholds be retuned from the Visualization
        tab without re-running the whole processing pipeline.

        Returns the number of subjects updated.
        """
        updated = 0
        for subject, data in self.processed_data.items():
            beh = data.get('beh_synced')
            if beh is None or 'entry_frames' not in data:
                continue  # no position data → nothing to detect
            try:
                beh, entry_frames = self.detect_zone_entries(beh)
                data['beh_synced'] = beh
                data['entry_frames'] = entry_frames
                data['entry_bouts'] = self.extract_entry_bouts(
                    beh, entry_frames,
                    num_photometry_channels=data.get('num_photometry_channels'))
                updated += 1
            except Exception as exc:
                self.log_message(f"  Zone-entry recompute failed for {subject}: {exc}")
        return updated

    def open_graph_settings_window(self):
        """Open an advanced graph settings window for visualization controls."""
        existing = getattr(self, 'graph_settings_window', None)
        if existing is not None:
            try:
                if existing.winfo_exists():
                    existing.lift()
                    existing.focus_force()
                    return
            except Exception:
                pass

        win = tk.Toplevel(self.root)
        win.title("Advanced Graph Settings")
        self.fit_toplevel(win, 650, 760)
        win.transient(self.root)
        self.graph_settings_window = win

        # This window asks for ~760 px of settings, more than a 768p screen can
        # show: pin the footer first, then scroll the body above it.
        footer = ttk.Frame(win, padding=(10, 6))
        footer.pack(side=tk.BOTTOM, fill='x')

        main = ttk.Frame(self.make_scrollable(win), padding=10)
        main.pack(fill='both', expand=True)

        trace_frame = ttk.LabelFrame(main, text="Trace Styling", padding=8)
        trace_frame.pack(fill='x', pady=(0, 8))
        ttk.Label(trace_frame, text="Mean Line Width:").grid(row=0, column=0, sticky='w', padx=5, pady=3)
        ttk.Entry(trace_frame, textvariable=self.mean_linewidth_var, width=10).grid(row=0, column=1, padx=5, pady=3)
        ttk.Label(trace_frame, text="Individual Trace Width:").grid(row=0, column=2, sticky='w', padx=15, pady=3)
        ttk.Entry(trace_frame, textvariable=self.trace_linewidth_var, width=10).grid(row=0, column=3, padx=5, pady=3)
        ttk.Label(trace_frame, text="Individual Trace Opacity:").grid(row=0, column=4, sticky='w', padx=15, pady=3)
        ttk.Entry(trace_frame, textvariable=self.trace_alpha_var, width=10).grid(row=0, column=5, padx=5, pady=3)
        # Global gridline toggle (also available as a "Grid" button on every
        # plot's navigation toolbar). Flipping it live-updates all open plots.
        ttk.Checkbutton(trace_frame, text="Show gridlines on graphs",
                        variable=self.show_gridlines,
                        command=self._toggle_gridlines).grid(
            row=1, column=0, columnspan=3, sticky='w', padx=5, pady=(6, 3))

        heatmap_frame = ttk.LabelFrame(main, text="Heatmap Styling", padding=8)
        heatmap_frame.pack(fill='x', pady=(0, 8))
        ttk.Label(heatmap_frame, text="Color Min:").grid(row=0, column=0, sticky='w', padx=5, pady=3)
        ttk.Entry(heatmap_frame, textvariable=self.heatmap_vmin_var, width=10).grid(row=0, column=1, padx=5, pady=3)
        ttk.Label(heatmap_frame, text="Color Max:").grid(row=0, column=2, sticky='w', padx=15, pady=3)
        ttk.Entry(heatmap_frame, textvariable=self.heatmap_vmax_var, width=10).grid(row=0, column=3, padx=5, pady=3)

        ttk.Label(heatmap_frame, text="Colormap:").grid(row=1, column=0, sticky='w', padx=5, pady=3)
        cmap_options = ["RdBu_r", "viridis", "plasma", "inferno", "magma", "cividis", "coolwarm", "seismic", "bwr", "rainbow", "jet", "custom"]
        ttk.Combobox(heatmap_frame, textvariable=self.heatmap_cmap_var,
                     values=cmap_options, width=15, state='readonly').grid(row=1, column=1, padx=5, pady=3, sticky='w')

        ttk.Checkbutton(heatmap_frame, text="Show zone overlay on heatmaps",
                        variable=self.show_zone_overlay_var, command=self._update_zone_overlay_button_label).grid(
            row=1, column=2, columnspan=2, sticky='w', padx=15, pady=3
        )

        # Custom colormap pickers (enabled only when Colormap == "custom")
        ttk.Label(heatmap_frame, text="Custom Colors:").grid(row=2, column=0, sticky='w', padx=5, pady=3)
        custom_color_frame = ttk.Frame(heatmap_frame)
        custom_color_frame.grid(row=2, column=1, columnspan=3, sticky='w', padx=5, pady=3)

        ttk.Label(custom_color_frame, text="Low:").pack(side='left', padx=(0, 4))
        self.heatmap_color_low_entry = ttk.Entry(custom_color_frame, textvariable=self.heatmap_color_low_var, width=10)
        self.heatmap_color_low_entry.pack(side='left', padx=(0, 4))
        self.heatmap_color_low_btn = tk.Button(custom_color_frame, text="Pick", width=5,
                                               command=lambda: self.pick_heatmap_color('low'))
        self.heatmap_color_low_btn.pack(side='left', padx=(0, 10))

        ttk.Label(custom_color_frame, text="Mid:").pack(side='left', padx=(0, 4))
        self.heatmap_color_mid_entry = ttk.Entry(custom_color_frame, textvariable=self.heatmap_color_mid_var, width=10)
        self.heatmap_color_mid_entry.pack(side='left', padx=(0, 4))
        self.heatmap_color_mid_btn = tk.Button(custom_color_frame, text="Pick", width=5,
                                               command=lambda: self.pick_heatmap_color('mid'))
        self.heatmap_color_mid_btn.pack(side='left', padx=(0, 10))

        ttk.Label(custom_color_frame, text="High:").pack(side='left', padx=(0, 4))
        self.heatmap_color_high_entry = ttk.Entry(custom_color_frame, textvariable=self.heatmap_color_high_var, width=10)
        self.heatmap_color_high_entry.pack(side='left', padx=(0, 4))
        self.heatmap_color_high_btn = tk.Button(custom_color_frame, text="Pick", width=5,
                                                command=lambda: self.pick_heatmap_color('high'))
        self.heatmap_color_high_btn.pack(side='left', padx=(0, 10))

        # Clear the widget references when the window closes so the colormap
        # trace doesn't poke destroyed widgets.
        def _clear_custom_color_refs():
            self.heatmap_color_low_entry = self.heatmap_color_low_btn = None
            self.heatmap_color_mid_entry = self.heatmap_color_mid_btn = None
            self.heatmap_color_high_entry = self.heatmap_color_high_btn = None
            win.destroy()
        win.protocol("WM_DELETE_WINDOW", _clear_custom_color_refs)

        # Set initial enabled/disabled state for the pickers.
        self.update_heatmap_custom_colors()

        axis_frame = ttk.LabelFrame(main, text="Visualization Axis", padding=8)
        axis_frame.pack(fill='x', pady=(0, 8))
        ttk.Label(axis_frame, text="Y Min:").grid(row=0, column=0, sticky='w', padx=5, pady=3)
        ttk.Entry(axis_frame, textvariable=self.viz_ymin_var, width=10).grid(row=0, column=1, padx=5, pady=3)
        ttk.Label(axis_frame, text="Y Max:").grid(row=0, column=2, sticky='w', padx=15, pady=3)
        ttk.Entry(axis_frame, textvariable=self.viz_ymax_var, width=10).grid(row=0, column=3, padx=5, pady=3)
        ttk.Button(axis_frame, text="Apply Limits", command=self.apply_viz_axis_limits).grid(row=0, column=4, padx=10, pady=3)
        ttk.Button(axis_frame, text="Reset Auto", command=self.reset_viz_axis_limits).grid(row=0, column=5, padx=5, pady=3)

        size_frame = ttk.LabelFrame(main, text="Graph Size", padding=8)
        size_frame.pack(fill='x', pady=(0, 8))
        ttk.Label(size_frame, text="Figure Width (in):").grid(row=0, column=0, sticky='w', padx=5, pady=3)
        ttk.Entry(size_frame, textvariable=self.viz_fig_width_var, width=10).grid(row=0, column=1, padx=5, pady=3)
        ttk.Label(size_frame, text="Figure Height (in):").grid(row=0, column=2, sticky='w', padx=15, pady=3)
        ttk.Entry(size_frame, textvariable=self.viz_fig_height_var, width=10).grid(row=0, column=3, padx=5, pady=3)
        ttk.Label(size_frame, text="Graphing Area Height (px):").grid(row=1, column=0, sticky='w', padx=5, pady=3)
        ttk.Entry(size_frame, textvariable=self.viz_canvas_height_var, width=10).grid(row=1, column=1, padx=5, pady=3)
        ttk.Label(size_frame, text='Enter "auto" or a number', foreground='gray',
                  font=('Segoe UI', 8)).grid(row=1, column=2, columnspan=2, sticky='w', padx=15, pady=3)
        ttk.Label(size_frame,
                  text='Figure size sets the rendered plot dimensions. Graphing area height sets the display frame size.',
                  foreground='gray', font=('Segoe UI', 8)).grid(row=2, column=0, columnspan=6, sticky='w', padx=5, pady=(0, 3))

        # ── Zone Entry Detection (transition thresholds) ──────────────────
        # These control how long the animal must stay in a zone for a transition
        # to count as a valid entry, and the refractory window that suppresses
        # rapid re-entries. They are applied at detection time, so changing them
        # here re-runs detection on already-processed subjects.
        entry_frame = ttk.LabelFrame(
            main, text="Zone Entry Detection  (transition thresholds)", padding=8)
        entry_frame.pack(fill='x', pady=(0, 8))

        ttk.Label(entry_frame,
                  text="Minimum time in the target zone for an entry to count, plus the "
                       "refractory window\nthat ignores rapid re-entries. Used by "
                       "'Zone Entry Bouts' plots.",
                  foreground='gray', font=('Segoe UI', 8), justify='left').grid(
            row=0, column=0, columnspan=4, sticky='w', padx=5, pady=(0, 6))

        # EPM thresholds
        ttk.Label(entry_frame, text="EPM — min duration in open arm (s):").grid(
            row=1, column=0, sticky='w', padx=5, pady=2)
        epm_dur_var = tk.StringVar(value=str(self.params.get('min_open_arm_duration', 2.0)))
        ttk.Spinbox(entry_frame, from_=0.1, to=10.0, increment=0.1, width=7,
                    textvariable=epm_dur_var, format='%.1f').grid(row=1, column=1, padx=5, pady=2, sticky='w')
        ttk.Label(entry_frame, text="EPM — min time between entries (s):").grid(
            row=1, column=2, sticky='w', padx=15, pady=2)
        epm_ref_var = tk.StringVar(value=str(self.params.get('min_time_between_entries', 3.0)))
        ttk.Spinbox(entry_frame, from_=0.1, to=30.0, increment=0.5, width=7,
                    textvariable=epm_ref_var, format='%.1f').grid(row=1, column=3, padx=5, pady=2, sticky='w')

        # OFT / Custom Arena thresholds
        ttk.Label(entry_frame, text="OFT / Custom — min duration in zone (s):").grid(
            row=2, column=0, sticky='w', padx=5, pady=2)
        oft_dur_var = tk.StringVar(value=str(self.params.get('oft_min_entry_duration', 0.5)))
        ttk.Spinbox(entry_frame, from_=0.1, to=10.0, increment=0.1, width=7,
                    textvariable=oft_dur_var, format='%.1f').grid(row=2, column=1, padx=5, pady=2, sticky='w')
        ttk.Label(entry_frame, text="OFT / Custom — min time between entries (s):").grid(
            row=2, column=2, sticky='w', padx=15, pady=2)
        oft_ref_var = tk.StringVar(value=str(self.params.get('oft_min_time_between_entries', 1.0)))
        ttk.Spinbox(entry_frame, from_=0.1, to=30.0, increment=0.5, width=7,
                    textvariable=oft_ref_var, format='%.1f').grid(row=2, column=3, padx=5, pady=2, sticky='w')

        def _apply_entry_detection():
            try:
                self.params['min_open_arm_duration'] = float(epm_dur_var.get())
                self.params['min_time_between_entries'] = float(epm_ref_var.get())
                self.params['oft_min_entry_duration'] = float(oft_dur_var.get())
                self.params['oft_min_time_between_entries'] = float(oft_ref_var.get())
            except ValueError:
                messagebox.showerror(
                    "Invalid Value",
                    "Duration / refractory fields must be numeric.", parent=win)
                return
            n = self._recompute_zone_entries_all()
            self.log_message(
                f"Recomputed zone entries for {n} subject(s) with updated thresholds "
                f"(EPM {self.params['min_open_arm_duration']}s/"
                f"{self.params['min_time_between_entries']}s, "
                f"OFT {self.params['oft_min_entry_duration']}s/"
                f"{self.params['oft_min_time_between_entries']}s)")
            if self.current_viz_figure is not None:
                self.generate_plot()
            messagebox.showinfo(
                "Entries Recomputed",
                f"Zone-entry detection re-run for {n} subject(s) with position data.\n"
                "'Zone Entry Bouts' plots now reflect the new thresholds.",
                parent=win)

        ttk.Button(entry_frame, text="Apply & Recompute Entries",
                   command=_apply_entry_detection).grid(
            row=3, column=0, columnspan=2, sticky='w', padx=5, pady=(6, 0))
        ttk.Label(entry_frame,
                  text="Re-runs entry detection on processed subjects (no full reprocess needed).",
                  foreground='gray', font=('Segoe UI', 8)).grid(
            row=3, column=2, columnspan=2, sticky='w', padx=5, pady=(6, 0))

        # (footer is already pinned to the bottom of the window above)
        def _apply_and_refresh():
            try:
                self.get_trace_styling()
                self.get_heatmap_range()
                self._update_zone_overlay_button_label()
                if self.current_viz_figure is not None:
                    self.generate_plot()
            except Exception as exc:
                messagebox.showerror("Settings Error", f"Unable to apply graph settings:\n{exc}")

        ttk.Button(footer, text="Apply & Refresh Plot", command=_apply_and_refresh).pack(side='left', padx=5)
        ttk.Button(footer, text="Close", command=_clear_custom_color_refs).pack(side='left', padx=5)

    # -------------------- Channel selection helpers --------------------
    def on_viz_subject_selected(self, event=None):
        """Build dynamic channel checkboxes when a subject is selected in visualization tab"""
        try:
            selection = self.viz_subject_listbox.curselection()
            if not selection:
                return
            subject = self.viz_subject_listbox.get(selection[0])
            self.build_viz_channel_checkboxes(subject)
            # Update Signal Integrity channel selector availability
            self.update_integrity_channel_selector()
            # Keep behavior/bout selectors synchronized with current selection.
            self.update_behavior_list()
            self.update_bout_number_selector()
        except Exception:
            return

    def update_integrity_channel_selector(self):
        """Update Signal Integrity channel selector based on current plot type and selection"""
        plot_type = self.plot_type_var.get()
        
        # Only enable for single-subject Signal Integrity view
        if plot_type == "Signal Integrity":
            # Sensor mode applies to both single- and multi-subject integrity views
            self.integrity_sensor_check['state'] = 'normal'
            selected_indices = self.viz_subject_listbox.curselection()
            if len(selected_indices) == 1:
                # Enable channel selector
                self.integrity_channel_combo['state'] = 'readonly'
                # Update available channels
                subject = self.viz_subject_listbox.get(selected_indices[0])
                if subject in self.processed_data:
                    data = self.processed_data[subject]
                    # Use the real channel designations (G0/G1/R4/…) in column order.
                    available_channels = self._ordered_channel_names(data)

                    if available_channels:
                        self.integrity_channel_combo['values'] = available_channels
                        # Set to first available channel if current selection is invalid
                        if self.integrity_channel_var.get() not in available_channels:
                            self.integrity_channel_var.set(available_channels[0])
                return
            self.integrity_channel_combo['state'] = 'disabled'
            return

        # Disable for all other cases
        self.integrity_channel_combo['state'] = 'disabled'
        self.integrity_sensor_check['state'] = 'disabled'

    def build_viz_channel_checkboxes(self, subject):
        """Create checkboxes for each available photometry channel for the given subject"""
        # Clear existing
        for child in self.viz_channel_check_frame.winfo_children():
            child.destroy()
        self.viz_channel_vars = []

        data = self.processed_data.get(subject, {})
        num_channels = 0
        # Prefer corrected/zscore arrays to determine channel count
        for key in ('zscore_470', 'zscore_570', 'corrected_470', 'corrected_570', 'dff_470', 'dff_570', 'data_470', 'data_570'):
            if key in data:
                arr = data[key]
                if arr is not None and arr.shape[1] > 2:
                    if key.startswith('data_'):
                        # raw data: signals and isosbestic pairs -> count pairs
                        num_channels = (arr.shape[1] - 2) // 2
                    else:
                        num_channels = arr.shape[1] - 2
                    break

        if num_channels <= 0:
            # Fallback to two-channel legacy
            num_channels = 2

        # Create checkboxes labelled with the real channel designation (G0/R4/…)
        # so every channel — regardless of count or region index — is selectable.
        for ch in range(num_channels):
            var = tk.IntVar(value=1 if ch < 2 else 0)
            cb = ttk.Checkbutton(self.viz_channel_check_frame,
                                 text=self.get_channel_name(data, ch), variable=var)
            cb.pack(side='left', padx=2)
            self.viz_channel_vars.append(var)

    def get_selected_viz_channels(self, data):
        """Return list of selected channel indices (0-based) for given data.
        Falls back to legacy G0/G1 if dynamic checkboxes not present."""
        # If dynamic vars exist and non-empty, use them
        if getattr(self, 'viz_channel_vars', None):
            return [i for i, v in enumerate(self.viz_channel_vars) if v.get()]

        # Legacy fallback: use first two channels based on show_g0/show_g1
        sel = []
        if self.show_g0.get():
            sel.append(0)
        if self.show_g1.get():
            sel.append(1)
        return sel

    def _viz_bout_channel_slots(self, subjects, max_slots=2):
        """Resolve the visualization channel checkboxes into up to ``max_slots``
        ``(bout_key, label)`` pairs for the group/multi bout plots.

        The group/multi bout visualizers historically hardcoded the first two
        channels as ``G0``/``G1``, so a red/570 selection (e.g. ``R4``/``R5``)
        was ignored and the green channels were plotted instead.  Resolving the
        actual checkbox selection here makes those plots honor the same channel
        choice as the single-subject views.

        ``bout_key`` is the ``Ch{n}`` key used to look up stored bouts (always
        present in a bout entry, alongside the real designation and the legacy
        G0/G1 aliases); ``label`` is the human channel designation (e.g. ``R4``),
        also used as the per-channel exclusion key.  Missing slots are returned
        as ``(None, None)`` so callers can skip them.
        """
        ref = {}
        for s in subjects:
            if s in self.processed_data:
                ref = self.processed_data[s]
                break
        sel = self.get_selected_viz_channels(ref)
        if not sel:
            sel = [0, 1]
        slots = []
        for idx in sel[:max_slots]:
            slots.append((f'Ch{idx}', self.get_channel_name(ref, idx)))
        while len(slots) < max_slots:
            slots.append((None, None))
        return slots

    def _viz_channel_wavelengths(self, data, sel_chs, has_470, has_570):
        """Map each selected channel to its OWN wavelength for plotting.

        A green channel is shown only at 470 nm and a red channel only at
        560/570 nm (gated by the wavelength checkboxes), so the overlay never
        plots a channel against the wrong excitation wavelength.
        Returns a list of (channel_index, '470'|'570') pairs.
        """
        pairs = []
        for ch in sel_chs:
            wl = self.resolve_channel_wavelength(data, ch)  # 470 or 570
            if wl == 470 and has_470:
                pairs.append((ch, '470'))
            elif wl == 570 and has_570:
                pairs.append((ch, '570'))
        return pairs

    def plot_raw_data(self, fig, data):
        """Plot raw deinterleaved data with dynamic channel selection"""
        show_470 = self.show_470.get()
        show_570 = self.show_570.get()

        if not show_470 and not show_570:
            fig.text(0.5, 0.5, 'Please select at least one wavelength (470nm or 570nm) to display',
                     ha='center', va='center', fontsize=14)
            return

        # Determine which wavelengths are available and selected
        has_470 = data.get('has_470', False) and show_470
        has_570 = data.get('has_570', False) and show_570

        if not has_470 and not has_570:
            fig.text(0.5, 0.5, 'Selected wavelength(s) not available in processed data',
                     ha='center', va='center', fontsize=14)
            return

        # Get selected channel indices (0-based)
        sel_chs = self.get_selected_viz_channels(data)
        if not sel_chs:
            fig.text(0.5, 0.5, 'No channels selected for plotting', ha='center', va='center', fontsize=14)
            return

        # One row per channel, each at its OWN wavelength (signal + isosbestic).
        pairs = self._viz_channel_wavelengths(data, sel_chs, has_470, has_570)
        if not pairs:
            fig.text(0.5, 0.5, 'No channels match the selected wavelength(s)',
                     ha='center', va='center', fontsize=14)
            return
        n_rows = len(pairs)
        plot_idx = 1

        for ch, wavelength in pairs:
            fp_data = data.get(f'data_{wavelength}')
            if fp_data is None:
                continue
            wl_label = f"{wavelength}nm"
            ch_label = self.get_channel_name(data, ch)
            sig_col = 2 + (ch * 2)
            iso_col = sig_col + 1

            # Signal subplot
            ax = fig.add_subplot(n_rows, 2, plot_idx)
            if sig_col < fp_data.shape[1]:
                signal = self._apply_visualizer_smoothing(fp_data[:, sig_col])
                ax.plot(fp_data[:, 0], signal, label=f'{ch_label} {wl_label}')
            ax.set_title(f'{ch_label} {wl_label} raw')
            ax.set_xlabel('Time (s)')
            ax.set_ylabel('F (a.u.)')
            ax.legend()
            plot_idx += 1

            # Isosbestic subplot (if present)
            ax = fig.add_subplot(n_rows, 2, plot_idx)
            if iso_col < fp_data.shape[1]:
                iso_signal = self._apply_visualizer_smoothing(fp_data[:, iso_col])
                ax.plot(fp_data[:, 0], iso_signal, label=f'{ch_label} 415nm')
                ax.set_title(f'{ch_label} 415nm isosbestic')
                ax.set_xlabel('Time (s)')
                ax.set_ylabel('F (a.u.)')
                ax.legend()
            else:
                ax.text(0.5, 0.5, 'No isosbestic', ha='center', va='center')
            plot_idx += 1

        fig.tight_layout()
    
    def plot_dff_data(self, fig, data):
        """Plot normalized dF/F data"""
        # Use same dynamic channel selection approach as raw plotting
        show_470 = self.show_470.get()
        show_570 = self.show_570.get()

        if not show_470 and not show_570:
            fig.text(0.5, 0.5, 'Please select at least one wavelength (470nm or 570nm) to display',
                     ha='center', va='center', fontsize=14)
