    def _dec_prob_toggle_mode(self):
        """Switch the selector panel between Subject and Group mode."""
        mode = self.dec_prob_by_var.get()
        # The two selectors share one slot in the Selection zone, so exactly one
        # is packed at a time and the other leaves no gap behind.
        if mode == "Group":
            self._dec_prob_subj_container.pack_forget()
            self._dec_prob_grp_container.pack(fill='both', expand=True)
            self.update_dec_prob_groups()
            self.refresh_facet_controls()
        else:
            self._dec_prob_grp_container.pack_forget()
            self._dec_prob_subj_container.pack(fill='both', expand=True)

    def _dec_prob_show_placeholder(self):
        """Clear the plot area and show instructional placeholder text."""
        if self.dec_prob_canvas_widget is not None:
            try:
                self.dec_prob_canvas_widget.get_tk_widget().pack_forget()
                self.dec_prob_canvas_widget.get_tk_widget().destroy()
            except Exception:
                pass
            self.dec_prob_canvas_widget = None
        if self.dec_prob_figure is not None:
            try:
                plt.close(self.dec_prob_figure)
            except Exception:
                pass
            self.dec_prob_figure = None
        for w in self.dec_prob_plot_frame.winfo_children():
            try:
                w.destroy()
            except Exception:
                pass
        ttk.Label(self.dec_prob_plot_frame,
                  text="Select subjects or groups and click 'Run Analysis'",
                  font=('TkDefaultFont', 11)).pack(expand=True)

    def update_dec_prob_subjects(self):
        """Refresh the subject listbox on the Decision Probability tab."""
        if not hasattr(self, 'dec_prob_subject_listbox'):
            return
        sel = {self.dec_prob_subject_listbox.get(i)
               for i in self.dec_prob_subject_listbox.curselection()}
        self.dec_prob_subject_listbox.delete(0, 'end')
        sorted_subjects = sorted(
            s for s, d in self.processed_data.items() if d.get('has_position', False))
        for i, subj in enumerate(sorted_subjects):
            self.dec_prob_subject_listbox.insert('end', subj)
            if subj in sel:
                self.dec_prob_subject_listbox.selection_set(i)
        # Keep the Kinematics tab's selectors in sync at every project-load point.
        if hasattr(self, 'kin_subject_listbox'):
            self.update_kin_subjects()

    def update_dec_prob_groups(self):
        """Refresh the group listbox on the Decision Probability tab."""
        self.fill_group_listbox(getattr(self, 'dec_prob_group_listbox', None))

